INSERT INTO tmp_jlpt_study_item (exam_code, item_kind, sort_order, payload) VALUES
    ('N1_2021_07', 'GRAMMAR', 1, '{"pattern":"～はおろか","expressions":["はおろか"],"is_answer":false,"link":"https://onjlpt.com/ngu-phap/N1/はおろか","level":"N1","question":{"text":"26. このカメラは、プロの写真家( )、普通の人間には使いこなせないだろ","options":["1) はおろか","2) ならまだしも","3) どころではなく","4) に比して"],"correct":2},"lesson":{"pattern":"～はおろか","meaning":null,"note":null,"usages":[{"title":"N là đương nhiên, sự vật, sự việc có mức độ khác cũng có thể nói, đánh giá giống như N.","meaning":"Ôn JLPTChào mừng ngày 30/4 - Tự hào Việt Nam – Một lần ngoảnh lại, vạn niềm kiêu hãnh!","description":"Follow Onjlpt Luyện tập N3N2N1 Luyện đề N5N4N3N2N1 Kanji N3N2 Từ vựng Từ vựng đề thi214 Bộ thủHiraganaKatakana Ngữ pháp N5N4N3N2N1 Video HomeGóp ý Furigana Chưa thuộc ～はおろか Các cách sử dụng N là đương nhiên, sự vật, sự việc có mức độ khác cũng có thể nói, đánh giá giống như N. Đưa ra ví dụ N để thể hiện điều đương nhiên, so với N trong trường hợp mức độ cao hơn thì dùng mẫu câu này để nhấn mạnh trạng thái. Toàn bộ câu văn thể hiện ấn tượng, cảm nghĩ không tốt của tác giả. Câu văn sau thường dùng những từ như も、さえ、まで để nhấn mạnh mức độ cao hơn so với vế trước.","structure":"N(+trợ từ) + はおろか","examples":[{"ja":"手間がかかる料理はおろか、日常の簡単な料理を作るのさえ面倒だ。","ja_furigana":"手間がかかる料理はおろか、日常の簡単な料理を作るのさえ面倒だ。","vi":"Những món ăn tốn công thì đương nhiên, cỡ như việc làm nhưng món ăn đơn giản bình thường thì cũng phiền phức."},{"ja":"私は花粉症がひどくて、外ではおろか、家の中でさえマスクが外せない。","ja_furigana":"私は花粉症がひどくて、外ではおろか、家の中でさえマスクが外せない。","vi":"Tôi thì dị ứng phấn hoa nặng, bên ngoài thì đương nhiên rồi, ngay cả trong nhà cũng không thể tháo khẩu trang."}]}]},"source_question_ids":[6830],"match_status":"catalog_match"}'),
    ('N1_2021_07', 'GRAMMAR', 2, '{"pattern":"〜て以来","expressions":["開催されて以来"],"is_answer":false,"link":"https://onjlpt.com/ngu-phap/N2/te-irai","level":"N2","question":{"text":"28. 新作ケーム機の発売イベントは、今週末に東京でん( )、全国を巡回していく予定だ。","options":["1) 開催されてのを皮切りに","2) 開催されるや否や","3) 開催されたとたんに","4) 開催されて以来"],"correct":1},"lesson":{"pattern":"〜て以来","meaning":"Cấu trúc: Động từ thể て + 以来 (いらい）. Ý nghĩa: “kể từ sau khi…”. A て以来 B nghĩa là kể từ sau khi xảy ra A thì B tiếp diễn (1 cách liên tục, đều đặn).","note":"Cấu trúc: Động từ thể て + 以来 (いらい）。Ý nghĩa: “kể từ sau khi…”. A て以来 B nghĩa là kể từ sau khi xảy ra A thì B tiếp diễn (1 cách liên tục, đều đặn).","usages":[{"title":"Kể từ sau khi","meaning":"Ôn JLPTChào mừng ngày 30/4 - Tự hào Việt Nam – Một lần ngoảnh lại, vạn niềm kiêu hãnh!","description":"Follow Onjlpt Luyện tập N3N2N1 Luyện đề N5N4N3N2N1 Kanji N3N2 Từ vựng Từ vựng đề thi214 Bộ thủHiraganaKatakana Ngữ pháp N5N4N3N2N1 Video HomeGóp ý Furigana Chưa thuộc 〜て以来 Cấu trúc: Động từ thể て + 以来 (いらい）. Ý nghĩa: “kể từ sau khi…”. A て以来 B nghĩa là kể từ sau khi xảy ra A thì B tiếp diễn (1 cách liên tục, đều đặn). Các cách sử dụng Kể từ sau khi kể từ sau khi… A て以来 B nghĩa là kể từ sau khi xảy ra A thì B tiếp diễn (1 cách liên tục, đều đặn)","structure":"Động từ thể て + 以来","examples":[{"ja":"犬を飼って以来、毎朝の散歩が日課になった。","ja_furigana":"犬を飼って以来、毎朝の散歩が日課になった。","vi":"Kể từ sau khi nuôi chó thì đi bộ buổi sáng đã trở thành việc hàng ngày của tôi."},{"ja":"彼に会ったのは、大学を卒業して以来です。","ja_furigana":"彼に会ったのは、大学を卒業して以来です。","vi":"Tôi gặp anh ấy là kể từ sau khi tốt nghiệp đại học."},{"ja":"引っ越して以来、まだ一度もエアコンを使っていない。","ja_furigana":"引っ越して以来、まだ一度もエアコンを使っていない。","vi":"Kể từ sau khi chuyển nhà tôi vẫn chưa dùng điều hoà lần nào."},{"ja":"彼は学校始まって以来の秀才と言われていた。","ja_furigana":"彼は学校始まって以来の秀才と言われていた。","vi":"Người ta nói rằng cậu bé này là một tài năng kể từ khi bắt đầu đi học."},{"ja":"この会社に入って以来、まだ一度も休んだことがない。","ja_furigana":"この会社に入って以来、まだ一度も休んだことがない。","vi":"Kể từ khi vào làm ở công ty này tôi chưa từng nghỉ một lần nào."},{"ja":"彼は結婚して以来、まるで人が変わったようにまじめになった。","ja_furigana":"彼は結婚して以来、まるで人が変わったようにまじめになった。","vi":"Từ sau khi kết hôn, anh ấy đã trở nên nghiêm chỉnh như 1 người hoàn toàn khác."}]}]},"source_question_ids":[6832],"match_status":"catalog_match"}'),
    ('N1_2021_07', 'GRAMMAR', 3, '{"pattern":"～ あまり","expressions":["落とそうとするあまり"],"is_answer":true,"link":"https://onjlpt.com/ngu-phap/N2/あまり","level":"N2","question":{"text":"31. 歯医者「歯を磨くときに、汚れをく( )、強い力で磨いてしまいがちですが、カを入れすぎると、歯を傷つけてしまいます。優しく磨きましょう。」","options":["1) 落とそうとするあまり","2) 落とそうとしたわりに","3) 落とせばいしのであれば","4) 落とせばいいかというと"],"correct":1},"lesson":{"pattern":"～ あまり","meaning":"Cấu trúc: [Thể thường (ふつう)] + あまり\\n\\n* Tính từ-na + な/ Danh từ + の + あまり\\n\\nÝ nghĩa: “Quá …“, điều gì đó vượt quá mức độ, gây ra kết quả không bình thường.","note":null,"usages":[{"title":"Quá mức độ gây ra kết quả không bình thường","meaning":"Ôn JLPTChào mừng ngày 30/4 - Tự hào Việt Nam – Một lần ngoảnh lại, vạn niềm kiêu hãnh!","description":"Follow Onjlpt Luyện tập N3N2N1 Luyện đề N5N4N3N2N1 Kanji N3N2 Từ vựng Từ vựng đề thi214 Bộ thủHiraganaKatakana Ngữ pháp N5N4N3N2N1 Video HomeGóp ý Furigana Chưa thuộc ～ あまり Cấu trúc: [Thể thường (ふつう)] + あまり\\n\\n* Tính từ-na + な/ Danh từ + の + あまり\\n\\nÝ nghĩa: “Quá …“, điều gì đó vượt quá mức độ, gây ra kết quả không bình thường. Các cách sử dụng Quá mức độ gây ra kết quả không bình thường Quá … Điều gì đó vượt quá mức độ, gây ra kết quả không bình thường.","structure":"[Thể thường (ふつう)] + あまり\\nTính từ-na + な/ Danh từ + の + あまり","examples":[{"ja":"母は、私を心配するあまり、体調を崩（くず）したようです。","ja_furigana":"母は、私を心配するあまり、体調を崩（くず）したようです。","vi":"Mẹ tôi vì quá lo lắng cho tôi nên dường như sức khỏe đã suy sụp."},{"ja":"その犬が死んだ時、先生は悲しみのあまり、しばらく仕事を休んでいました。","ja_furigana":"その犬が死んだ時、先生は悲しみのあまり、しばらく仕事を休んでいました。","vi":"Khi con chó đó chết đi, cô giáo vì quá buồn nên đã xin nghỉ làm một thời gian."},{"ja":"スピーチコンテストでは、緊張のあまり、話す内容をかなり忘れてしまった。","ja_furigana":"スピーチコンテストでは、緊張のあまり、話す内容をかなり忘れてしまった。","vi":"Tại cuộc thi diễn thuyết, vì quá hồi hộp nên tôi đã quên mất cả nội dung cần nói."},{"ja":"ゲームを熱中（ねっちゅう）するあまり、食事をするのを忘れていました。","ja_furigana":"ゲームを熱中（ねっちゅう）するあまり、食事をするのを忘れていました。","vi":"Quá mải chơi game đến mức quên cả ăn."},{"ja":"うれしさのあまり、彼は涙（なみだ）を流（なが）しました。","ja_furigana":"うれしさのあまり、彼は涙（なみだ）を流（なが）しました。","vi":"Vì quá vui sướng anh ấy đã rơi lệ."},{"ja":"興奮（こうふん）のあまり、写真を取るのを忘れてしまった。","ja_furigana":"興奮（こうふん）のあまり、写真を取るのを忘れてしまった。","vi":"Quá phấn khích nên tôi quên cả chụp ảnh."}]}]},"source_question_ids":[6835],"match_status":"catalog_match"}'),
    ('N1_2021_07', 'GRAMMAR', 4, '{"pattern":"〜まい","expressions":["にすぎまい","でもあるまい"],"is_answer":true,"link":"https://onjlpt.com/ngu-phap/N2/まい","level":"N2","question":{"text":"34. X 社は経営に行き詰まっている。今回の成果主義導入も、労働意欲向上のためとはいうが、結局は人件費削減を正当化するための口実( )。","options":["1) になどせぬ","2) にすぎまい","3) でかまわぬ","4) でもあるまい"],"correct":2},"lesson":{"pattern":"〜まい","meaning":"Cấu trúc: Động từ thể từ điển + まい\\n（Động từ thuộc nhóm 2 có thể chia theo dạng bỏ る + まい. Ví dụ 忘れる→ 忘れまい/ 忘れるまい)\\nÝ nghĩa: “không” . Cấu trúc diễn đạt sự phủ định mạnh mẽ (nhất định không làm)","note":null,"usages":[{"title":"Diễn đạt sự phủ định mạnh mẽ (nhất định không làm)","meaning":"Ôn JLPTChào mừng ngày 30/4 - Tự hào Việt Nam – Một lần ngoảnh lại, vạn niềm kiêu hãnh!","description":"Follow Onjlpt Luyện tập N3N2N1 Luyện đề N5N4N3N2N1 Kanji N3N2 Từ vựng Từ vựng đề thi214 Bộ thủHiraganaKatakana Ngữ pháp N5N4N3N2N1 Video HomeGóp ý Furigana Chưa thuộc 〜まい Cấu trúc: Động từ thể từ điển + まい\\n（Động từ thuộc nhóm 2 có thể chia theo dạng bỏ る + まい. Ví dụ 忘れる→ 忘れまい/ 忘れるまい)\\nÝ nghĩa: “không” . Cấu trúc diễn đạt sự phủ định mạnh mẽ (nhất định không làm) Các cách sử dụng Diễn đạt sự phủ định mạnh mẽ (nhất định không làm) không Cấu trúc diễn đạt sự phủ định mạnh mẽ (nhất định không làm). Thường dùng với thể từ điển của động từ nhóm 1 và nhóm 2 (bỏ る + まい).","structure":"Động từ thể từ điển + まい","examples":[{"ja":"今日のことは決けっして忘れるまいと心に誓ちかった。","ja_furigana":"今日のことは決けっして忘れるまいと心に誓ちかった。","vi":"Tôi đã thề với lòng là nhất định sẽ không quên việc xảy ra ngày hôm nay."},{"ja":"もう二度とお酒は飲むまいと思ったんですが、その日はちょっと飲んでしまったんです。","ja_furigana":"もう二度とお酒は飲むまいと思ったんですが、その日はちょっと飲んでしまったんです。","vi":"Tôi đã nghĩ là nhất định sẽ không uống rượu thêm lần nữa nhưng ngày hôm đó tôi lại uống 1 chút mất rồi."},{"ja":"何があっても、言い訳だけはするまいと思っています。","ja_furigana":"何があっても、言い訳だけはするまいと思っています。","vi":"Dù có chuyện gì đi nữa tôi cũng sẽ không biện bạch lý do lý trấu."},{"ja":"どういう結果（けっか）になろうと、後悔（こうかい）だけはするまいと思っていた。","ja_furigana":"どういう結果（けっか）になろうと、後悔（こうかい）だけはするまいと思っていた。","vi":"Dù kết quả thế nào thì tôi nhất định sẽ không hối hận."},{"ja":"その時は結局（けっきょく）１週間会社を休むことになったので、もう二度と無理（むり）はするまいと思ったんです。","ja_furigana":"その時は結局（けっきょく）１週間会社を休むことになったので、もう二度と無理（むり）はするまいと思ったんです。","vi":"Kết cục là lúc đó tôi đã phải nghỉ làm tận 1 tuần nên tôi đã nghĩ là nhất định sẽ không cố làm quá sức nữa."}]}]},"source_question_ids":[6838],"match_status":"catalog_match"}'),
    ('N1_2021_07', 'GRAMMAR', 5, '{"pattern":"～ のみならず","expressions":["のみならず"],"is_answer":false,"link":"https://onjlpt.com/ngu-phap/N2/のみならず","level":"N2","question":{"text":"38. 彼はとても優秀で成績が学年の上位に入っている ___ ___ _★_ ___ 真面目で好感が持てる。","options":["1) 授業に取り組む","2) のみならず","3) 姿勢そのものも","4) ことが多い"],"correct":1},"lesson":{"pattern":"～ のみならず","meaning":"“Không chỉ…” (Thường dùng trong văn viết hay hoàn cảnh trang trọng)","note":null,"usages":[{"title":"Cấu trúc 1","meaning":"Không chỉ…","description":"Dùng để diễn đạt ý \"không chỉ A mà còn B\", thường dùng trong văn viết hoặc trong những hoàn cảnh trang trọng.","structure":"[ふつう] + のみならず","examples":[{"ja":"（広告）今や、女性のみならず男性も、肌(はだ)のお手入(てい)れが必要です。","ja_furigana":"（広告）今や、女性のみならず男性も、肌(はだ)のお手入(てい)れが必要です。","vi":"（Quảng cáo）Giờ đây không chỉ phụ nữ mà đàn ông cũng cần chăm sóc da."},{"ja":"A: 社長、B社も来月、新商品を出すそうです。/ B: そうか。A社のみならず、B社もか・・・。うちも頑張らないとな。","ja_furigana":"A: 社長、B社も来月、新商品を出すそうです。/ B: そうか。A社のみならず、B社もか・・・。うちも頑張らないとな。","vi":"A: Giám đốc, nghe nói công ty B sẽ cho ra sản phẩm mới vào tháng sau./ B: Thế à. Không chỉ công ty A mà công ty B cũng ra à… Công ty chúng ta cũng phải cố gắng thôi."},{"ja":"日本のアニメは国内のみならず、海外でも人気がある。","ja_furigana":"日本のアニメは国内のみならず、海外でも人気がある。","vi":"Phim hoạt hình của Nhật không chỉ nổi tiếng trong nước mà còn ở cả nước ngoài."},{"ja":"彼女はスタイルのみならず、歩き方もきれいだ。","ja_furigana":"彼女はスタイルのみならず、歩き方もきれいだ。","vi":"Không chỉ phong cách mà dáng đi của cô ấy cũng đẹp."},{"ja":"この映画は、日本のみならず、海外でも話題になった。","ja_furigana":"この映画は、日本のみならず、海外でも話題になった。","vi":"Bộ phim này không chỉ gây được sự chú ý ở Nhật mà còn ở cả nước ngoài."}]},{"title":"Cấu trúc 2","meaning":"Không chỉ…","description":"Dùng khi kết hợp với danh từ hoặc tính từ na thì thêm である trước のみならず","structure":"[ナ形/ 名] + （である） + のみならず","examples":[]}]},"source_question_ids":[6842],"match_status":"catalog_match"}'),
    ('N1_2021_07', 'GRAMMAR', 6, '{"pattern":"～のが、～のは、～のに","expressions":["常に考えているのは"],"is_answer":false,"link":"https://onjlpt.com/ngu-phap/N4/no-ga-no-wa-no-ni","level":"N4","question":{"text":"40. 私が接客するにあたって ___ ___ _★_ ___ 自分は何をすべきかということだ。","options":["1) 常に考えているのは","2) 何であって","3) それに応えるために","4) お客様が求めていることは"],"correct":2},"lesson":{"pattern":"～のが、～のは、～のに","meaning":"Danh từ hóa động từ, tính từ bằng cách thêm の, với các cách dùng khác nhau tùy theo trợ từ đi kèm","note":"～のは/のが: có thể thay thế cho こと trong nhiều trường hợp danh từ hóa.\n～のは: dùng để chỉ người, vật, địa điểm, thời gian, nguyên nhân cụ thể.\n～のに: dùng để diễn đạt mục đích sử dụng, thường đi với các động từ như 使う、役に立つ、便利だ.\nKhi chỉ đồ vật, の có thể thay bằng もの.\nDanh từ hóa với の thường dùng trong văn nói, trong khi こと thường dùng trong văn viết.","usages":[{"title":"～のは/のが (thay thế こと)","meaning":"Việc...","description":"Danh từ hóa động từ, có thể thay thế cho こと trong nhiều trường hợp","structure":"[Động từ thể thường] + のは/のが","examples":[{"ja":"料理を作るのは楽しいです。","ja_furigana":"料理を作るのは楽しいです。","vi":"Việc nấu ăn thật là vui.","note":"料理: りょうり: nấu ăn, 作る: つくる: làm, nấu"},{"ja":"料理をするのが楽しいです。","ja_furigana":"料理をするのが楽しいです。","vi":"Tôi thấy nấu ăn rất thú vị."},{"ja":"鍵を持ってくるのをわすれました。","ja_furigana":"鍵を持ってくるのをわすれました。","vi":"Tôi đã quên mang theo chìa khóa rồi.","note":"鍵: かぎ: chìa khóa, 持ってくる: もってくる: mang theo"},{"ja":"彼が海外へ引っ越すのを知っています。","ja_furigana":"彼が海外へ引っ越すのを知っています。","vi":"Tôi biết việc anh ấy chuyển ra nước ngoài.","note":"海外: かいがい: nước ngoài, 引っ越す: ひっこす: chuyển nhà"},{"ja":"暗いところにいるのがこわいです。","ja_furigana":"暗いところにいるのがこわいです。","vi":"Việc ở trong bóng tối thật là đáng sợ.","note":"暗い: くらい: tối, 怖い: こわい: sợ"}]},{"title":"～のは (chỉ người/vật/địa điểm)","meaning":"...là...","description":"Danh từ hóa để chỉ người, vật, địa điểm, thời gian, nguyên nhân","structure":"[Động từ/Tính từ/Danh từ thể thường] + のは","examples":[{"ja":"彼が働いているのは東京の会社です。","ja_furigana":"彼が働いているのは東京の会社です。","vi":"Nơi anh ấy làm việc là một công ty ở Tokyo.","note":"働く: はたらく: làm việc, 東京: とうきょう: Tokyo, 会社: かいしゃ: công ty"},{"ja":"学生なのは鈴木さんだけです。","ja_furigana":"学生なのは鈴木さんだけです。","vi":"Người còn là sinh viên chỉ có anh Suzuki.","note":"学生: がくせい: sinh viên"},{"ja":"一番安いのはこの店です。","ja_furigana":"一番安いのはこの店です。","vi":"Rẻ nhất là cửa hàng này.","note":"店: cửa hàng"},{"ja":"新しい家を買ったのは家族が増えたからです。","ja_furigana":"新しい家を買ったのは家族が増えたからです。","vi":"Mua nhà mới là vì gia đình đã có thêm thành viên.","note":"新しい: あたらしい: mới, 家: いえ: nhà, 増える: ふえる: tăng lên"},{"ja":"パーティーが始まるのは7時です。","ja_furigana":"パーティーが始まるのは7時です。","vi":"Giờ tiệc bắt đầu là 7 giờ.","note":"パーティー: パーティー: bữa tiệc, 始まる: はじまる: bắt đầu"},{"ja":"もっとあたたかいのはこのセーターです。","ja_furigana":"もっとあたたかいのはこのセーターです。","vi":"Cái ấm hơn là cái áo len này.","note":"暖かい: あたたかい: ấm"}]},{"title":"～のに (mục đích sử dụng)","meaning":"Để..., dùng để...","description":"Diễn đạt mục đích sử dụng của một vật hoặc hành động","structure":"[Động từ thể từ điển] + のに","examples":[{"ja":"ハサミは紙を切るのに使います。","ja_furigana":"ハサミは紙を切るのに使います。","vi":"Kéo là dùng để cắt giấy.","note":"ハサミ: はさみ: kéo, 紙: かみ: giấy"},{"ja":"はさみはかみをきるのにつかいます。","ja_furigana":"はさみはかみをきるのにつかいます。","vi":"Kéo là dùng để cắt giấy.","note":"はさみ: kéo, 紙: かみ: giấy, 切る: きる: cắt"},{"ja":"この地図は新しい場所を見つけるのに役に立ちます。","ja_furigana":"この地図は新しい場所を見つけるのに役に立ちます。","vi":"Bản đồ này rất hữu ích cho việc tìm kiếm địa điểm mới.","note":"地図: ちず: bản đồ, 新しい: あたらしい: mới, 場所: ばしょ: địa điểm, 見つける: みつける: tìm kiếm"}]}]},"source_question_ids":[6844],"match_status":"catalog_match"}'),
    ('N1_2021_07', 'GRAMMAR', 7, '{"pattern":"～ために、～ように","expressions":["それに応えるために","あのように"],"is_answer":false,"link":"https://onjlpt.com/ngu-phap/N4/tame-ni-you-ni","level":"N4","question":{"text":"40. 私が接客するにあたって ___ ___ _★_ ___ 自分は何をすべきかということだ。","options":["1) 常に考えているのは","2) 何であって","3) それに応えるために","4) お客様が求めていることは"],"correct":2},"lesson":{"pattern":"～ために、～ように","meaning":"Diễn đạt mục đích với sự khác biệt về sắc thái: ～ために cho mục đích trực tiếp, ～ように cho mục đích gián tiếp hoặc không thuộc kiểm soát trực tiếp","note":"「～ために」dùng cho mục đích trực tiếp thuộc kiểm soát của người nói\n「～ように」dùng cho mục đích gián tiếp, không thuộc kiểm soát trực tiếp, hoặc liên quan đến khả năng\nThể ない thường chỉ dùng với 「ように」\nMục đích hướng về người khác thường dùng 「ように」","usages":[{"title":"～ために (Danh từ)","meaning":"Để làm gì/Vì cái gì","description":"Diễn đạt mục đích trực tiếp với danh từ","structure":"[Danh từ] + の + ために","examples":[{"ja":"健康のために、毎朝ジョギングしています。","ja_furigana":"健康のために、毎朝ジョギングしています。","vi":"Tôi chạy bộ mỗi sáng để giữ sức khỏe.","note":"健康: けんこう: sức khỏe, 毎朝: まいあさ: mỗi sáng"},{"ja":"健康のために、毎日ジョギングをしています。","ja_furigana":"健康のために、毎日ジョギングをしています。","vi":"Tôi chạy bộ mỗi ngày để giữ gìn sức khỏe.","note":"健康: けんこう: sức khỏe"}]},{"title":"～ために (Động từ)","meaning":"Để làm gì/Vì cái gì","description":"Diễn đạt mục đích trực tiếp với động từ","structure":"[Động từ thể từ điển] + ために","examples":[{"ja":"仕事をするために、東京に引っ越しました。","ja_furigana":"仕事をするために、東京に引っ越しました。","vi":"Tôi đã chuyển đến Tokyo để làm việc."},{"ja":"旅行に行くために、荷物を準備します。","ja_furigana":"旅行に行くために、荷物を準備します。","vi":"Tôi chuẩn bị hành lý để đi du lịch.","note":"旅行: りょこう: du lịch, 荷物: にもつ: hành lý, 準備: じゅんび: chuẩn bị"},{"ja":"映画を見るために、映画館に行きました。","ja_furigana":"映画を見るために、映画館に行きました。","vi":"Tôi đã đi đến rạp chiếu phim để xem phim."},{"ja":"彼は仕事をするために、新しいパソコンを買いました。","ja_furigana":"彼は仕事をするために、新しいパソコンを買いました。","vi":"Anh ấy mua máy tính mới để làm việc.","note":"→ mục đích hướng về bản thân \"anh ấy\""}]},{"title":"～ように","meaning":"Để có thể mà, để mà…","description":"Diễn đạt mục đích gián tiếp, không thuộc kiểm soát trực tiếp","structure":"[Động từ thể từ điển/thể ない/thể khả năng] + ように","examples":[{"ja":"学生が理解できるように、説明をゆっくりしました。","ja_furigana":"学生が理解できるように、説明をゆっくりしました。","vi":"Tôi đã giải thích chậm rãi để học sinh có thể hiểu."},{"ja":"風邪をひかないように、暖かくして寝ます。","ja_furigana":"風邪をひかないように、暖かくして寝ます。","vi":"Tôi giữ ấm khi ngủ để không bị cảm."},{"ja":"試験に合格できるように、毎日勉強しています。","ja_furigana":"試験に合格できるように、毎日勉強しています。","vi":"Tôi học mỗi ngày để có thể đỗ kỳ thi.","note":"試験: しけん: kỳ thi, 合格する: ごうかくする: đỗ, 毎日: まいにち: mỗi ngày, 勉強する: べんきょうする: học"},{"ja":"犬が飲めるように、牛乳を温かくしました。","ja_furigana":"犬が飲めるように、牛乳を温かくしました。","vi":"Tôi làm ấm sữa để chó có thể uống được.","note":"温かい: あたたかい: ấm"},{"ja":"けがをしないように、運動靴を履いた。","ja_furigana":"けがをしないように、運動靴を履いた。","vi":"Tôi đi giày thể thao để không bị thương.","note":"けが: chấn thương, 運動靴: うんどうぐつ: giày thể thao, 履く: はく: đi (giày)"},{"ja":"彼女が料理を習うように、料理教室に通わせています。","ja_furigana":"彼女が料理を習うように、料理教室に通わせています。","vi":"Tôi cho cô ấy tham gia lớp học nấu ăn để cô ấy học nấu ăn.","note":"料理教室: りょうりきょうしつ: lớp học nấu ăn → mục đích hướng về \"cô ấy\""},{"ja":"学生に理解してもらうために、図を描きました。","ja_furigana":"学生に理解してもらうために、図を描きました。","vi":"Tôi đã vẽ sơ đồ để học sinh có thể hiểu.","note":"理解: りかい: hiểu → mục đích hướng về \"tôi\""},{"ja":"日本語が上手に話せるように、毎日練習しています。","ja_furigana":"日本語が上手に話せるように、毎日練習しています。","vi":"Tôi luyện tập mỗi ngày để có thể nói tiếng Nhật giỏi.","note":"練習する: れんしゅうする: luyện tập → thuộc về khả năng"}]}]},"source_question_ids":[6844,6848],"match_status":"catalog_match"}'),
    ('N1_2021_07', 'GRAMMAR', 8, '{"pattern":"〜とは","expressions":["お客様が求めていることは"],"is_answer":false,"link":"https://onjlpt.com/ngu-phap/N1/とは","level":"N1","question":{"text":"40. 私が接客するにあたって ___ ___ _★_ ___ 自分は何をすべきかということだ。","options":["1) 常に考えているのは","2) 何であって","3) それに応えるために","4) お客様が求めていることは"],"correct":2},"lesson":{"pattern":"〜とは","meaning":null,"note":null,"usages":[{"title":"~ thì kinh khủng, sửng sốt, ghê.","meaning":"Ôn JLPTChào mừng ngày 30/4 - Tự hào Việt Nam – Một lần ngoảnh lại, vạn niềm kiêu hãnh!","description":"Follow Onjlpt Luyện tập N3N2N1 Luyện đề N5N4N3N2N1 Kanji N3N2 Từ vựng Từ vựng đề thi214 Bộ thủHiraganaKatakana Ngữ pháp N5N4N3N2N1 Video HomeGóp ý Furigana Chưa thuộc 〜とは Các cách sử dụng ~ thì kinh khủng, sửng sốt, ghê. Nhấn mạnh cảm giác kinh ngạc, thán phục, ngạc nhiên của tác giả đối với sự thực nào đó. Thường đi kèm với câu văn thể hiện sự thật mà tác giả đã ngạc nhiên. Vế sau là câu văn thể hiện cảm xúc của tác giả nhưng cũng có thể lược bỏ vế sau. Thường thì không sử dụng cho chính bản thân mình.","structure":"Thể thông thường（な形（だ）・名（だ）） + とは","examples":[{"ja":"鳥の足が２本であることさえ知らない子供がいるとは驚きだ。","ja_furigana":"鳥の足が２本であることさえ知らない子供がいるとは驚きだ。","vi":"Việc có những đứa trẻ không biết những việc cỡ như chim có 2 chân thì làm cho tôi rất ngạc nhiên。"},{"ja":"この先に滝があると聞いたので、こんなに歩いてきたのに、ここで行き止まりとは。。。","ja_furigana":"この先に滝があると聞いたので、こんなに歩いてきたのに、ここで行き止まりとは。。。","vi":"Vì nghe là phía trước có con thác nên đã chạy đến như thế này rồi vậy mà đến đây dùng lại thì thật là...。"}]}]},"source_question_ids":[6844],"match_status":"catalog_match"}'),
    ('N1_2021_07', 'GRAMMAR', 9, '{"pattern":"～なら","expressions":["なら"],"is_answer":true,"link":"https://onjlpt.com/ngu-phap/N4/nara","level":"N4","question":{"text":"【42】","options":["1) も","2) なら","3) さえ","4) だけ"],"correct":2},"lesson":{"pattern":"～なら","meaning":"Mẫu câu điều kiện diễn đạt giả định dựa trên thông tin có sẵn, dùng để đưa ra đánh giá, mệnh lệnh, mong muốn hoặc ý định","note":"Đặc điểm khác biệt:\nKhác với các mẫu câu điều kiện khác, ～なら không yêu cầu mối quan hệ thời gian giữa hai vế (vế 1 không cần xảy ra trước vế 2)\nThường dùng để phản hồi lại thông tin đã nghe từ người đối diện\nCó thể thêm の hoặc ん phía trước なら để nhấn mạnh mà không thay đổi nghĩa","usages":[{"title":"Đưa ra đánh giá, đề xuất","meaning":"Nếu A thì B (đề xuất)","description":"Dựa vào giả định/điều kiện ở vế 1 để đưa ra đánh giá, mệnh lệnh, mong muốn hoặc ý định","structure":"Vる/Vた/Vない + なら\\nAい + なら\\nAな + なら\\nN + なら","examples":[{"ja":"大阪へ行くなら, 飛行機が速いです。","ja_furigana":"大阪へ行くなら, 飛行機が速いです。","vi":"Nếu mà đi Osaka thì đi máy bay là nhanh.","note":"飛行機: ひこうき: máy bay、速い: はやい: nhanh"},{"ja":"天気がいいなら、公園に行きましょう。","ja_furigana":"天気がいいなら、公園に行きましょう。","vi":"Nếu thời tiết đẹp thì đi công viên đi."},{"ja":"雨なら、家にいたほうがいいですよ。","ja_furigana":"雨なら、家にいたほうがいいですよ。","vi":"Nếu mà trời mưa thì ở nhà sẽ tốt hơn đấy.","note":"雨: あめ: mưa"},{"ja":"日本人なら","ja_furigana":"日本人なら","vi":"Nếu là người Nhật thì chắc chắn thích sushi."},{"ja":"行くなら早く行ったほうがいい。","ja_furigana":"行くなら早く行ったほうがいい。","vi":"Nếu đi thì nên đi sớm."}]},{"title":"Phản hồi thông tin","meaning":"Nếu đã A thì B (phản hồi)","description":"Dùng để phản hồi lại thông tin nghe được từ người đối diện và đưa ra nhận xét","structure":"Vる/Vた/Vない + なら\\nAい + なら\\nAな + なら\\nN + なら","examples":[{"ja":"スマホがあるなら、写真が撮れますね。","ja_furigana":"スマホがあるなら、写真が撮れますね。","vi":"Nếu có điện thoại thông minh thì chụp được ảnh nhỉ.","note":"Phản hồi thông tin từ người đối diện"}]}]},"source_question_ids":[6846],"match_status":"catalog_match"}'),
    ('N1_2021_07', 'GRAMMAR', 10, '{"pattern":"～だけ、～しか","expressions":["だけ"],"is_answer":false,"link":"https://onjlpt.com/ngu-phap/N5/dake-shika","level":"N5","question":{"text":"【42】","options":["1) も","2) なら","3) さえ","4) だけ"],"correct":2},"lesson":{"pattern":"～だけ、～しか","meaning":"Diễn đạt ý giới hạn \"chỉ\", trong đó だけ dùng với thể khẳng định còn しか luôn dùng với thể phủ định và mang ý nghĩa mạnh hơn","note":"Quy tắc sử dụng:\nだけ: Dùng với câu khẳng định, có thể đứng sau danh từ, động từ, tính từ\nしか: Luôn dùng với câu phủ định, mang ý nghĩa mạnh hơn だけ\nTrợ từ: Không dùng trợ từ を、が với cả だけ và しか. Với trợ từ に、で: だけ có thể đứng trước hoặc sau, しか chỉ đứng sau\nLưu ý: しか luôn đi với động từ phủ định, mang ý nghĩa \"ngoài cái này ra thì không còn gì khác\"","usages":[{"title":"Danh từ + だけ + [khẳng định]","meaning":"Chỉ","description":"Diễn đạt giới hạn, chỉ có điều được đề cập, dùng với câu khẳng định","structure":"[Danh từ] + だけ + [Động từ/Tính từ khẳng định]","examples":[{"ja":"りんごだけあります。","ja_furigana":"りんごだけあります。","vi":"Chỉ có táo."},{"ja":"くだものだけたべます。","ja_furigana":"くだものだけたべます。","vi":"Tôi chỉ ăn mỗi trái cây.","note":"Không dùng trợ từ を"},{"ja":"いぬだけいました。","ja_furigana":"いぬだけいました。","vi":"Chỉ có con chó đã ở đó.","note":"Không dùng trợ từ が"},{"ja":"カフェでだけべんきょうします。","ja_furigana":"カフェでだけべんきょうします。","vi":"Tôi chỉ học ở quán cà phê.","note":"だけ đứng sau trợ từ で"},{"ja":"ここにだけ行きます。","ja_furigana":"ここにだけ行きます。","vi":"Chỉ đi đến đây thôi.","note":"だけ đứng sau trợ từ に"}]},{"title":"Danh từ + しか + [phủ định]","meaning":"Chỉ (ngoài... không còn)","description":"Diễn đạt giới hạn mạnh, ngoài điều được đề cập ra thì không còn gì khác, luôn dùng với phủ định","structure":"[Danh từ] + しか + [Động từ/Tính từ phủ định]","examples":[{"ja":"水しか飲みません。","ja_furigana":"水しか飲みません。","vi":"Chỉ uống nước.","note":"Ngoài nước ra thì không uống gì khác"},{"ja":"パンしかたべません。","ja_furigana":"パンしかたべません。","vi":"Tôi chỉ ăn mỗi bánh mì.","note":"Luôn dùng phủ định"},{"ja":"いぬしかいません。","ja_furigana":"いぬしかいません。","vi":"Chỉ có mỗi con chó.","note":"Luôn dùng phủ định"},{"ja":"家でしかテレビを見ません。","ja_furigana":"家でしかテレビを見ません。","vi":"Tôi chỉ xem tivi ở nhà.","note":"しか chỉ đứng sau trợ từ"},{"ja":"この店にしかありません。","ja_furigana":"この店にしかありません。","vi":"Chỉ ở cửa hàng này mới có.","note":"しか chỉ đứng sau trợ từ"},{"ja":"りんごしかたべません。","ja_furigana":"りんごしかたべません。","vi":"Tôi chỉ ăn táo.","note":"Luôn dùng phủ định"}]},{"title":"Động từ/Tính từ + だけ","meaning":"Chỉ","description":"だけ có thể đứng sau động từ thể thường hoặc tính từ để diễn đạt giới hạn","structure":"[Động từ/Tính từ thể thường] + だけ","examples":[{"ja":"トムさんだけきています。","ja_furigana":"トムさんだけきています。","vi":"Chỉ có anh Tom đến thôi.","note":"来る: くる: đến"},{"ja":"あまいものはすこしだけ食べました。","ja_furigana":"あまいものはすこしだけ食べました。","vi":"Chỉ ăn một chút đồ ngọt thôi.","note":"あまいもの: đồ ngọt"}]}]},"source_question_ids":[6846],"match_status":"catalog_match"}'),
    ('N1_2021_07', 'GRAMMAR', 11, '{"pattern":"～とはいえ","expressions":["とはいえ"],"is_answer":true,"link":"https://onjlpt.com/ngu-phap/N1/とはいえ","level":"N1","question":{"text":"【43】","options":["1) 確かに","2) むしろ","3) とはいえ","4) とすると"],"correct":3},"lesson":{"pattern":"～とはいえ","meaning":null,"note":null,"usages":[{"title":"Có thể điều đó là sự thật nhưng cho dù như thế thì tình trạng cũng giống nhau.","meaning":"Ôn JLPTChào mừng ngày 30/4 - Tự hào Việt Nam – Một lần ngoảnh lại, vạn niềm kiêu hãnh!","description":"Follow Onjlpt Luyện tập N3N2N1 Luyện đề N5N4N3N2N1 Kanji N3N2 Từ vựng Từ vựng đề thi214 Bộ thủHiraganaKatakana Ngữ pháp N5N4N3N2N1 Video HomeGóp ý Furigana Chưa thuộc ～とはいえ Các cách sử dụng Có thể điều đó là sự thật nhưng cho dù như thế thì tình trạng cũng giống nhau. Đi kèm với những câu văn thể hiện sự thật hoặc thể hiện suy nghĩ của tác giả rằng điều đó là sự thật. Vế sau là câu văn thể hiện điều đó không phải là sự thật đơn giản mà thể hiện sự đánh giá của tác giả hoặc có ý nghĩa ngược lại với sự thật đã nêu ở vế đầu.","structure":"N・V thông thường + とはいえ","examples":[{"ja":"ダイエット中とはいえ、出されたごちそうに手をつけないなんて失礼だと思う。","ja_furigana":"ダイエット中とはいえ、出されたごちそうに手をつけないなんて失礼だと思う。","vi":"Mặc dù là đang ăn kiêng nhưng món ăn đã mang ra rồi mà không chạm tay vào thì tôi nghĩ thật là thất lễ。"},{"ja":"まだ締め切りまで時間があるとはいえ、早めに完成させておいたほうがいい。","ja_furigana":"まだ締め切りまで時間があるとはいえ、早めに完成させておいたほうがいい。","vi":"Mặc dù là đến hạn chót thì vẫn còn thời gian nhưng hoàn thành sớm vẫn tốt hơn。"}]}]},"source_question_ids":[6847],"match_status":"catalog_match"}'),
