    ('N2_2021_12', 'UNMATCHED_GRAMMAR', 13, '{"pattern":"されて","expressions":["されて"],"is_answer":true,"link":null,"level":null,"question":{"text":"35)X 社の健康食品はテレビ番組で紹介( )以来、とても売れている。","options":["1) されて","2) される","3) されている","4) された"],"correct":1},"lesson":null,"source_question_ids":[8367],"match_status":"expression_only"}'),
    ('N2_2021_12', 'UNMATCHED_GRAMMAR', 14, '{"pattern":"される","expressions":["される"],"is_answer":false,"link":null,"level":null,"question":{"text":"35)X 社の健康食品はテレビ番組で紹介( )以来、とても売れている。","options":["1) されて","2) される","3) されている","4) された"],"correct":1},"lesson":null,"source_question_ids":[8367],"match_status":"expression_only"}'),
    ('N2_2021_12', 'UNMATCHED_GRAMMAR', 15, '{"pattern":"されている","expressions":["されている"],"is_answer":false,"link":null,"level":null,"question":{"text":"35)X 社の健康食品はテレビ番組で紹介( )以来、とても売れている。","options":["1) されて","2) される","3) されている","4) された"],"correct":1},"lesson":null,"source_question_ids":[8367],"match_status":"expression_only"}'),
    ('N2_2021_12', 'UNMATCHED_GRAMMAR', 16, '{"pattern":"された","expressions":["された"],"is_answer":false,"link":null,"level":null,"question":{"text":"35)X 社の健康食品はテレビ番組で紹介( )以来、とても売れている。","options":["1) されて","2) される","3) されている","4) された"],"correct":1},"lesson":null,"source_question_ids":[8367],"match_status":"expression_only"}'),
