    ('N3_2010_07', 'VOCABULARY', 80, '{"word":"簡単","reading":"かんたん","meaning_vi":"đơn giản; dễ","han_viet":"GIẢN ĐƠN","tested":false,"question_type":"paraphrase","examples":[{"ja":"この問題は簡単です。","ja_furigana":"この問題は簡単です。","vi":"Vấn đề này đơn giản.","source":"dictionary"}]}'),
