    ('N3_2012_07', 'VOCABULARY', 79, '{"word":"試食","reading":"ししょく","meaning_vi":"nếm thử","han_viet":"THỬ THỰC","tested":false,"question_type":"context","examples":[{"ja":"新しいパンを試食した。","ja_furigana":"新しいパンを試食した。","vi":"Tôi đã nếm thử bánh mì mới.","source":"dictionary"}]}'),
    ('N3_2012_07', 'VOCABULARY', 80, '{"word":"運ぶ","reading":"はこぶ","meaning_vi":"mang","han_viet":"VẬN","tested":false,"question_type":"paraphrase","examples":[{"ja":"荷物を運ぶ。","ja_furigana":"荷物を運ぶ。","vi":"Mang hành lý.","source":"dictionary"}]}'),
