    ('N3_2012_12', 'VOCABULARY', 83, '{"word":"間接的","reading":"かんせつてき","meaning_vi":"gián tiếp","han_viet":"","tested":false,"question_type":"context","examples":[{"ja":"彼の助言は間接的だった。","ja_furigana":"彼の助言は間接的だった。","vi":"Lời khuyên của anh ấy là gián tiếp.","source":"dictionary"}]}'),
    ('N3_2012_12', 'VOCABULARY', 84, '{"word":"離す","reading":"はなす","meaning_vi":"tách ra","han_viet":"LY","tested":false,"question_type":"context","examples":[{"ja":"子どもを親から離す。","ja_furigana":"子どもを親から離す。","vi":"Tách đứa trẻ ra khỏi cha mẹ.","source":"dictionary"}]}'),
    ('N3_2012_12', 'GRAMMAR', 1, '{"pattern":"～てほしい","expressions":["してほしい"],"is_answer":true,"link":"https://onjlpt.com/ngu-phap/n3/te-hoshii","level":"N3","question":{"text":"5. 今日は神父の80歳の誕生日だ。大好きな祖父には、いつまでも元気で長生き( )。","options":["1) したがる","2) してほしい","3) していたい","4) したがっている"],"correct":2},"lesson":null}'),
    ('N3_2012_12', 'GRAMMAR', 2, '{"pattern":"～ために、～ように","expressions":["ためにも"],"is_answer":true,"link":"https://onjlpt.com/ngu-phap/n4/tame-ni-you-ni","level":"N4","question":{"text":"10. 高山選手は試合前のインタビューで、「いつも応援してくれているファンの( )勝ちたい。」と語った","options":["1) ためにも","2) ようにも","3) おかげでも","4) ときでも"],"correct":1},"lesson":{"pattern":"～ために、～ように","name":"Để làm gì/Vì cái gì","meaning":"Diễn đạt mục đích với sự khác biệt về sắc thái: ～ために cho mục đích trực tiếp, ～ように cho mục đích gián tiếp hoặc không thuộc kiểm soát trực tiếp","note":"「～ために」dùng cho mục đích trực tiếp thuộc kiểm soát của người nói\n「～ように」dùng cho mục đích gián tiếp, không thuộc kiểm soát trực tiếp, hoặc liên quan đến khả năng\nThể ない thường chỉ dùng với 「ように」\nMục đích hướng về người khác thường dùng 「ように」","usages":[{"title":"～ために (Danh từ)","meaning":"Để làm gì/Vì cái gì","description":"Diễn đạt mục đích trực tiếp với danh từ","structure":"[Danh từ] + の + ために","examples":[{"ja":"健康のために、毎朝ジョギングしています。","ja_furigana":"健康のために、毎朝ジョギングしています。","vi":"Tôi chạy bộ mỗi sáng để giữ sức khỏe.","note":"健康: けんこう: sức khỏe, 毎朝: まいあさ: mỗi sáng"},{"ja":"健康のために、毎日ジョギングをしています。","ja_furigana":"健康のために、毎日ジョギングをしています。","vi":"Tôi chạy bộ mỗi ngày để giữ gìn sức khỏe.","note":"健康: けんこう: sức khỏe"}]},{"title":"～ために (Động từ)","meaning":"Để làm gì/Vì cái gì","description":"Diễn đạt mục đích trực tiếp với động từ","structure":"[Động từ thể từ điển] + ために","examples":[{"ja":"仕事をするために、東京に引っ越しました。","ja_furigana":"仕事をするために、東京に引っ越しました。","vi":"Tôi đã chuyển đến Tokyo để làm việc."},{"ja":"旅行に行くために、荷物を準備します。","ja_furigana":"旅行に行くために、荷物を準備します。","vi":"Tôi chuẩn bị hành lý để đi du lịch.","note":"旅行: りょこう: du lịch, 荷物: にもつ: hành lý, 準備: じゅんび: chuẩn bị"},{"ja":"映画を見るために、映画館に行きました。","ja_furigana":"映画を見るために、映画館に行きました。","vi":"Tôi đã đi đến rạp chiếu phim để xem phim."},{"ja":"彼は仕事をするために、新しいパソコンを買いました。","ja_furigana":"彼は仕事をするために、新しいパソコンを買いました。","vi":"Anh ấy mua máy tính mới để làm việc.","note":"→ mục đích hướng về bản thân \"anh ấy\""}]},{"title":"～ように","meaning":"Để có thể mà, để mà…","description":"Diễn đạt mục đích gián tiếp, không thuộc kiểm soát trực tiếp","structure":"[Động từ thể từ điển/thể ない/thể khả năng] + ように","examples":[{"ja":"学生が理解できるように、説明をゆっくりしました。","ja_furigana":"学生が理解できるように、説明をゆっくりしました。","vi":"Tôi đã giải thích chậm rãi để học sinh có thể hiểu."},{"ja":"風邪をひかないように、暖かくして寝ます。","ja_furigana":"風邪をひかないように、暖かくして寝ます。","vi":"Tôi giữ ấm khi ngủ để không bị cảm."},{"ja":"試験に合格できるように、毎日勉強しています。","ja_furigana":"試験に合格できるように、毎日勉強しています。","vi":"Tôi học mỗi ngày để có thể đỗ kỳ thi.","note":"試験: しけん: kỳ thi, 合格する: ごうかくする: đỗ, 毎日: まいにち: mỗi ngày, 勉強する: べんきょうする: học"},{"ja":"犬が飲めるように、牛乳を温かくしました。","ja_furigana":"犬が飲めるように、牛乳を温かくしました。","vi":"Tôi làm ấm sữa để chó có thể uống được.","note":"温かい: あたたかい: ấm"},{"ja":"けがをしないように、運動靴を履いた。","ja_furigana":"けがをしないように、運動靴を履いた。","vi":"Tôi đi giày thể thao để không bị thương.","note":"けが: chấn thương, 運動靴: うんどうぐつ: giày thể thao, 履く: はく: đi (giày)"},{"ja":"彼女が料理を習うように、料理教室に通わせています。","ja_furigana":"彼女が料理を習うように、料理教室に通わせています。","vi":"Tôi cho cô ấy tham gia lớp học nấu ăn để cô ấy học nấu ăn.","note":"料理教室: りょうりきょうしつ: lớp học nấu ăn → mục đích hướng về \"cô ấy\""},{"ja":"学生に理解してもらうために、図を描きました。","ja_furigana":"学生に理解してもらうために、図を描きました。","vi":"Tôi đã vẽ sơ đồ để học sinh có thể hiểu.","note":"理解: りかい: hiểu → mục đích hướng về \"tôi\""},{"ja":"日本語が上手に話せるように、毎日練習しています。","ja_furigana":"日本語が上手に話せるように、毎日練習しています。","vi":"Tôi luyện tập mỗi ngày để có thể nói tiếng Nhật giỏi.","note":"練習する: れんしゅうする: luyện tập → thuộc về khả năng"}]}],"examples":[{"ja":"健康のために、毎朝ジョギングしています。","ja_furigana":"健康のために、毎朝ジョギングしています。","vi":"Tôi chạy bộ mỗi sáng để giữ sức khỏe.","note":"健康: けんこう: sức khỏe, 毎朝: まいあさ: mỗi sáng"},{"ja":"健康のために、毎日ジョギングをしています。","ja_furigana":"健康のために、毎日ジョギングをしています。","vi":"Tôi chạy bộ mỗi ngày để giữ gìn sức khỏe.","note":"健康: けんこう: sức khỏe"},{"ja":"仕事をするために、東京に引っ越しました。","ja_furigana":"仕事をするために、東京に引っ越しました。","vi":"Tôi đã chuyển đến Tokyo để làm việc."},{"ja":"旅行に行くために、荷物を準備します。","ja_furigana":"旅行に行くために、荷物を準備します。","vi":"Tôi chuẩn bị hành lý để đi du lịch.","note":"旅行: りょこう: du lịch, 荷物: にもつ: hành lý, 準備: じゅんび: chuẩn bị"},{"ja":"映画を見るために、映画館に行きました。","ja_furigana":"映画を見るために、映画館に行きました。","vi":"Tôi đã đi đến rạp chiếu phim để xem phim."},{"ja":"彼は仕事をするために、新しいパソコンを買いました。","ja_furigana":"彼は仕事をするために、新しいパソコンを買いました。","vi":"Anh ấy mua máy tính mới để làm việc.","note":"→ mục đích hướng về bản thân \"anh ấy\""},{"ja":"学生が理解できるように、説明をゆっくりしました。","ja_furigana":"学生が理解できるように、説明をゆっくりしました。","vi":"Tôi đã giải thích chậm rãi để học sinh có thể hiểu."},{"ja":"風邪をひかないように、暖かくして寝ます。","ja_furigana":"風邪をひかないように、暖かくして寝ます。","vi":"Tôi giữ ấm khi ngủ để không bị cảm."},{"ja":"試験に合格できるように、毎日勉強しています。","ja_furigana":"試験に合格できるように、毎日勉強しています。","vi":"Tôi học mỗi ngày để có thể đỗ kỳ thi.","note":"試験: しけん: kỳ thi, 合格する: ごうかくする: đỗ, 毎日: まいにち: mỗi ngày, 勉強する: べんきょうする: học"},{"ja":"犬が飲めるように、牛乳を温かくしました。","ja_furigana":"犬が飲めるように、牛乳を温かくしました。","vi":"Tôi làm ấm sữa để chó có thể uống được.","note":"温かい: あたたかい: ấm"},{"ja":"けがをしないように、運動靴を履いた。","ja_furigana":"けがをしないように、運動靴を履いた。","vi":"Tôi đi giày thể thao để không bị thương.","note":"けが: chấn thương, 運動靴: うんどうぐつ: giày thể thao, 履く: はく: đi (giày)"},{"ja":"彼女が料理を習うように、料理教室に通わせています。","ja_furigana":"彼女が料理を習うように、料理教室に通わせています。","vi":"Tôi cho cô ấy tham gia lớp học nấu ăn để cô ấy học nấu ăn.","note":"料理教室: りょうりきょうしつ: lớp học nấu ăn → mục đích hướng về \"cô ấy\""},{"ja":"学生に理解してもらうために、図を描きました。","ja_furigana":"学生に理解してもらうために、図を描きました。","vi":"Tôi đã vẽ sơ đồ để học sinh có thể hiểu.","note":"理解: りかい: hiểu → mục đích hướng về \"tôi\""},{"ja":"日本語が上手に話せるように、毎日練習しています。","ja_furigana":"日本語が上手に話せるように、毎日練習しています。","vi":"Tôi luyện tập mỗi ngày để có thể nói tiếng Nhật giỏi.","note":"練習する: れんしゅうする: luyện tập → thuộc về khả năng"}],"structures":[{"Cách dùng":"～ために (Danh từ)","Cấu trúc":"[Danh từ] + の + ために","Nghĩa":"Để làm gì/Vì cái gì"},{"Cách dùng":"～ために (Động từ)","Cấu trúc":"[Động từ thể từ điển] + ために","Nghĩa":"Để làm gì/Vì cái gì"},{"Cách dùng":"～ように","Cấu trúc":"[Động từ thể từ điển/thể ない/thể khả năng] + ように","Nghĩa":"Để có thể mà, để mà…"}],"related":[{"title":"～んです","link":"https://onjlpt.com/ngu-phap/n4/ndesu"},{"title":"～ほうがいいです","link":"https://onjlpt.com/ngu-phap/n4/hou-ga-ii-desu"},{"title":"Động từ thể ý chí","link":"https://onjlpt.com/ngu-phap/n4/doutai-there-y-chi"},{"title":"～ようと思います/ようと思っています","link":"https://onjlpt.com/ngu-phap/n4/you-to-omoimasu-you-to-omotteimasu"}],"description":"Diễn đạt mục đích với sự khác biệt về sắc thái: ～ために cho mục đích trực tiếp, ～ように cho mục đích gián tiếp hoặc không thuộc kiểm soát trực tiếp"}}'),
    ('N3_2012_12', 'GRAMMAR', 3, '{"pattern":"～だけ、～しか","expressions":["だけ","しか"],"is_answer":true,"link":"https://onjlpt.com/ngu-phap/n5/dake-shika","level":"N5","question":{"text":"6. (電話で) 母「何か父さんに伝言はある?」 娘「じゃあ、体に気をつけてと ( ) 伝えておいてよ。」","options":["1) だけ","2) なら","3) しか","4) にも"],"correct":1},"lesson":{"pattern":"～だけ、～しか","name":"Chỉ","meaning":"Diễn đạt ý giới hạn \"chỉ\", trong đó だけ dùng với thể khẳng định còn しか luôn dùng với thể phủ định và mang ý nghĩa mạnh hơn","note":"Quy tắc sử dụng:\nだけ: Dùng với câu khẳng định, có thể đứng sau danh từ, động từ, tính từ\nしか: Luôn dùng với câu phủ định, mang ý nghĩa mạnh hơn だけ\nTrợ từ: Không dùng trợ từ を、が với cả だけ và しか. Với trợ từ に、で: だけ có thể đứng trước hoặc sau, しか chỉ đứng sau\nLưu ý: しか luôn đi với động từ phủ định, mang ý nghĩa \"ngoài cái này ra thì không còn gì khác\"","usages":[{"title":"Danh từ + だけ + [khẳng định]","meaning":"Chỉ","description":"Diễn đạt giới hạn, chỉ có điều được đề cập, dùng với câu khẳng định","structure":"[Danh từ] + だけ + [Động từ/Tính từ khẳng định]","examples":[{"ja":"りんごだけあります。","ja_furigana":"りんごだけあります。","vi":"Chỉ có táo."},{"ja":"くだものだけたべます。","ja_furigana":"くだものだけたべます。","vi":"Tôi chỉ ăn mỗi trái cây.","note":"Không dùng trợ từ を"},{"ja":"いぬだけいました。","ja_furigana":"いぬだけいました。","vi":"Chỉ có con chó đã ở đó.","note":"Không dùng trợ từ が"},{"ja":"カフェでだけべんきょうします。","ja_furigana":"カフェでだけべんきょうします。","vi":"Tôi chỉ học ở quán cà phê.","note":"だけ đứng sau trợ từ で"},{"ja":"ここにだけ行きます。","ja_furigana":"ここにだけ行きます。","vi":"Chỉ đi đến đây thôi.","note":"だけ đứng sau trợ từ に"}]},{"title":"Danh từ + しか + [phủ định]","meaning":"Chỉ (ngoài... không còn)","description":"Diễn đạt giới hạn mạnh, ngoài điều được đề cập ra thì không còn gì khác, luôn dùng với phủ định","structure":"[Danh từ] + しか + [Động từ/Tính từ phủ định]","examples":[{"ja":"水しか飲みません。","ja_furigana":"水しか飲みません。","vi":"Chỉ uống nước.","note":"Ngoài nước ra thì không uống gì khác"},{"ja":"パンしかたべません。","ja_furigana":"パンしかたべません。","vi":"Tôi chỉ ăn mỗi bánh mì.","note":"Luôn dùng phủ định"},{"ja":"いぬしかいません。","ja_furigana":"いぬしかいません。","vi":"Chỉ có mỗi con chó.","note":"Luôn dùng phủ định"},{"ja":"家でしかテレビを見ません。","ja_furigana":"家でしかテレビを見ません。","vi":"Tôi chỉ xem tivi ở nhà.","note":"しか chỉ đứng sau trợ từ"},{"ja":"この店にしかありません。","ja_furigana":"この店にしかありません。","vi":"Chỉ ở cửa hàng này mới có.","note":"しか chỉ đứng sau trợ từ"},{"ja":"りんごしかたべません。","ja_furigana":"りんごしかたべません。","vi":"Tôi chỉ ăn táo.","note":"Luôn dùng phủ định"}]},{"title":"Động từ/Tính từ + だけ","meaning":"Chỉ","description":"だけ có thể đứng sau động từ thể thường hoặc tính từ để diễn đạt giới hạn","structure":"[Động từ/Tính từ thể thường] + だけ","examples":[{"ja":"トムさんだけきています。","ja_furigana":"トムさんだけきています。","vi":"Chỉ có anh Tom đến thôi.","note":"来る: くる: đến"},{"ja":"あまいものはすこしだけ食べました。","ja_furigana":"あまいものはすこしだけ食べました。","vi":"Chỉ ăn một chút đồ ngọt thôi.","note":"あまいもの: đồ ngọt"}]}],"examples":[{"ja":"りんごだけあります。","ja_furigana":"りんごだけあります。","vi":"Chỉ có táo."},{"ja":"くだものだけたべます。","ja_furigana":"くだものだけたべます。","vi":"Tôi chỉ ăn mỗi trái cây.","note":"Không dùng trợ từ を"},{"ja":"いぬだけいました。","ja_furigana":"いぬだけいました。","vi":"Chỉ có con chó đã ở đó.","note":"Không dùng trợ từ が"},{"ja":"カフェでだけべんきょうします。","ja_furigana":"カフェでだけべんきょうします。","vi":"Tôi chỉ học ở quán cà phê.","note":"だけ đứng sau trợ từ で"},{"ja":"ここにだけ行きます。","ja_furigana":"ここにだけ行きます。","vi":"Chỉ đi đến đây thôi.","note":"だけ đứng sau trợ từ に"},{"ja":"水しか飲みません。","ja_furigana":"水しか飲みません。","vi":"Chỉ uống nước.","note":"Ngoài nước ra thì không uống gì khác"},{"ja":"パンしかたべません。","ja_furigana":"パンしかたべません。","vi":"Tôi chỉ ăn mỗi bánh mì.","note":"Luôn dùng phủ định"},{"ja":"いぬしかいません。","ja_furigana":"いぬしかいません。","vi":"Chỉ có mỗi con chó.","note":"Luôn dùng phủ định"},{"ja":"家でしかテレビを見ません。","ja_furigana":"家でしかテレビを見ません。","vi":"Tôi chỉ xem tivi ở nhà.","note":"しか chỉ đứng sau trợ từ"},{"ja":"この店にしかありません。","ja_furigana":"この店にしかありません。","vi":"Chỉ ở cửa hàng này mới có.","note":"しか chỉ đứng sau trợ từ"},{"ja":"りんごしかたべません。","ja_furigana":"りんごしかたべません。","vi":"Tôi chỉ ăn táo.","note":"Luôn dùng phủ định"},{"ja":"トムさんだけきています。","ja_furigana":"トムさんだけきています。","vi":"Chỉ có anh Tom đến thôi.","note":"来る: くる: đến"},{"ja":"あまいものはすこしだけ食べました。","ja_furigana":"あまいものはすこしだけ食べました。","vi":"Chỉ ăn một chút đồ ngọt thôi.","note":"あまいもの: đồ ngọt"}],"structures":[{"Cách dùng":"Danh từ + だけ + [khẳng định]","Cấu trúc":"[Danh từ] + だけ + [Động từ/Tính từ khẳng định]","Nghĩa":"Chỉ"},{"Cách dùng":"Danh từ + しか + [phủ định]","Cấu trúc":"[Danh từ] + しか + [Động từ/Tính từ phủ định]","Nghĩa":"Chỉ (ngoài... không còn)"},{"Cách dùng":"Động từ/Tính từ + だけ","Cấu trúc":"[Động từ/Tính từ thể thường] + だけ","Nghĩa":"Chỉ"}],"related":[{"title":"Các cấu trúc sử dụng thể て","link":"https://onjlpt.com/ngu-phap/n5/cac-cau-truc-su-dung-the-te"},{"title":"～たことがある","link":"https://onjlpt.com/ngu-phap/n5/ta-koto-ga-aru"},{"title":"あげます・もらいます・くれます","link":"https://onjlpt.com/ngu-phap/n5/agemasu-moraimasu-kuremasu"},{"title":"～があります・～がいます","link":"https://onjlpt.com/ngu-phap/n5/aru-iru"}],"description":"Diễn đạt ý giới hạn \"chỉ\", trong đó だけ dùng với thể khẳng định còn しか luôn dùng với thể phủ định và mang ý nghĩa mạnh hơn"}}'),
    ('N3_2012_12', 'GRAMMAR', 4, '{"pattern":"～ばかり","expressions":["ばかりなのに","ばかりだから"],"is_answer":true,"link":"https://onjlpt.com/ngu-phap/n3/bakari","level":"N3","question":{"text":"9. A 「あの人の名前、山田さんだよね。」 B「違うよ。前田さんだよ。さっき教えた( ) どうして忘れちゃうの?」","options":["1) あとなのに","2) あとだから","3) ばかりなのに","4) ばかりだから"],"correct":3},"lesson":null}'),
    ('N3_2012_12', 'GRAMMAR', 5, '{"pattern":"～てくれと頼まれる/言われる","expressions":["「おかえり。」と言われると"],"is_answer":false,"link":"https://onjlpt.com/ngu-phap/n3/te-kure-to-tanomareru-ierareru","level":"N3","question":{"text":"15. 仕事から帰って、娘に笑顔で__ __ _★_ __幸せだといつも思う。","options":["1) 私は本当に","2) 「おかえり。」と言われると","3) 娘がいる","4) こんなかわいい"],"correct":3},"lesson":null}'),
    ('N3_2012_12', 'GRAMMAR', 6, '{"pattern":"～てあげます、～てくれます、～てもらいます","expressions":["おいてあげますよ"],"is_answer":false,"link":"https://onjlpt.com/ngu-phap/n4/te-agemasu-te-kuremasu-te-moraimasu","level":"N4","question":{"text":"11. 山口「すみませんが、この書類を広田さんに渡して( )、お願いします。」 北川「いいですよ。」","options":["1) おいてあげますよ","2) おこうと思えますか","3) おいてもらえませんか","4) おこうと思いませんよ"],"correct":3},"lesson":{"pattern":"～てあげます、～てくれます、～てもらいます","name":"Làm cho ai việc gì","meaning":"Diễn đạt việc cho/nhận hành động, thể hiện việc làm cho ai, được ai làm giúp hoặc nhờ ai làm giúp việc gì đó","note":"「～てあげます」ngụ ý có ơn, không dùng với người lớn hơn hoặc cấp trên.\n「～てくれます」dùng khi người khác tự động làm giúp mà không cần nhờ vả.\n「～てもらいます」dùng khi người nói chủ động nhờ vả người khác.\nChủ ngữ (người cho) thường được lược bỏ khi là người nói (trong ～てあげます) hoặc người nhận là người nói (trong ～てもらいます).\nSo sánh: ～てくれます (được làm giúp) vs ～てもらいます (nhờ làm giúp).","usages":[{"title":"～てあげます","meaning":"Làm cho ai việc gì","description":"Diễn đạt việc người nói làm gì đó cho người khác (từ góc độ người cho)","structure":"[Danh từ 1] は [Danh từ 2] に + ～てあげます","examples":[{"ja":"あした (私は) 本を貸してあげるよ。","ja_furigana":"あした (私は) 本を貸してあげるよ。","vi":"Mai tôi sẽ cho bạn mượn sách nhé.","note":"貸す: かす: cho mượn (người nói bị lược)"},{"ja":"私は友達にプレゼントを買ってあげました。","ja_furigana":"私は友達にプレゼントを買ってあげました。","vi":"Tôi đã mua quà cho bạn.","note":"友達: ともだち, 買う: かう: mua (người nói bị lược)"},{"ja":"友達に荷物を持ってあげました。","ja_furigana":"友達に荷物を持ってあげました。","vi":"Tôi đã mang hành lý giúp bạn.","note":"友達: ともだち: bạn, 荷物: にもつ: hành lý, 持つ: もつ: mang, cầm"},{"ja":"佐藤さんはマイさんに料理を作ってあげます。","ja_furigana":"佐藤さんはマイさんに料理を作ってあげます。","vi":"Sato nấu ăn cho Mai.","note":"作る: つくる: nấu ăn (ngôi thứ 3 làm cho ngôi thứ 3)"}]},{"title":"～てくれます","meaning":"Được ai làm giúp việc gì","description":"Diễn đạt việc người khác làm gì đó cho người nói hoặc người thân của người nói","structure":"[Danh từ 1] は/が [Danh từ 2] に + ～てくれます","examples":[{"ja":"友達がケーキを焼いてくれた。","ja_furigana":"友達がケーキを焼いてくれた。","vi":"Bạn đã nướng bánh cho tôi.","note":"ケーキ: ケーキ: bánh, 焼く: やく: nướng"},{"ja":"姉が宿題を手伝ってくれました。","ja_furigana":"姉が宿題を手伝ってくれました。","vi":"Chị tôi đã giúp tôi làm bài tập về nhà.","note":"手伝う: てつだう: giúp đỡ"},{"ja":"田中さんが私に本を貸してくれました。","ja_furigana":"田中さんが私に本を貸してくれました。","vi":"Anh Tanaka đã cho tôi mượn sách.","note":"貸す: かす: cho mượn, 本: ほん: sách"}]},{"title":"～てもらいます","meaning":"Nhờ ai làm giúp việc gì","description":"Diễn đạt việc người nói nhờ vả người khác làm gì đó cho mình","structure":"[Danh từ 1] は/が [Danh từ 2] に + ～てもらいます","examples":[{"ja":"田中さんにレポートをチェックしてもらいました。","ja_furigana":"田中さんにレポートをチェックしてもらいました。","vi":"Tôi đã nhờ anh Tanaka kiểm tra giúp báo cáo.","note":"田中: たなか, レポート: báo cáo, チェックする: kiểm tra (người nhận \"tôi\" bị lược)"},{"ja":"友達に宿題を手伝ってもらった。","ja_furigana":"友達に宿題を手伝ってもらった。","vi":"Tôi nhờ bạn làm giúp bài tập về nhà.","note":"友達: ともだち: bạn, 宿題: しゅくだい: bài tập về nhà (người nhận \"tôi\" bị lược)"},{"ja":"山田さんに荷物を運んでもらいました。","ja_furigana":"山田さんに荷物を運んでもらいました。","vi":"Tôi đã nhờ anh Yamada mang giúp đồ đạc.","note":"山田: やまだ, 荷物: にもつ: đồ đạc, 運ぶ: はこぶ: mang vác (người nhận \"tôi\" bị lược)"},{"ja":"私は友達に宿題を手伝ってもらいました。","ja_furigana":"私は友達に宿題を手伝ってもらいました。","vi":"Tôi đã nhờ bạn giúp làm bài tập về nhà.","note":"手伝う: てつだう: giúp đỡ"}]}],"examples":[{"ja":"あした (私は) 本を貸してあげるよ。","ja_furigana":"あした (私は) 本を貸してあげるよ。","vi":"Mai tôi sẽ cho bạn mượn sách nhé.","note":"貸す: かす: cho mượn (người nói bị lược)"},{"ja":"私は友達にプレゼントを買ってあげました。","ja_furigana":"私は友達にプレゼントを買ってあげました。","vi":"Tôi đã mua quà cho bạn.","note":"友達: ともだち, 買う: かう: mua (người nói bị lược)"},{"ja":"友達に荷物を持ってあげました。","ja_furigana":"友達に荷物を持ってあげました。","vi":"Tôi đã mang hành lý giúp bạn.","note":"友達: ともだち: bạn, 荷物: にもつ: hành lý, 持つ: もつ: mang, cầm"},{"ja":"佐藤さんはマイさんに料理を作ってあげます。","ja_furigana":"佐藤さんはマイさんに料理を作ってあげます。","vi":"Sato nấu ăn cho Mai.","note":"作る: つくる: nấu ăn (ngôi thứ 3 làm cho ngôi thứ 3)"},{"ja":"友達がケーキを焼いてくれた。","ja_furigana":"友達がケーキを焼いてくれた。","vi":"Bạn đã nướng bánh cho tôi.","note":"ケーキ: ケーキ: bánh, 焼く: やく: nướng"},{"ja":"姉が宿題を手伝ってくれました。","ja_furigana":"姉が宿題を手伝ってくれました。","vi":"Chị tôi đã giúp tôi làm bài tập về nhà.","note":"手伝う: てつだう: giúp đỡ"},{"ja":"田中さんが私に本を貸してくれました。","ja_furigana":"田中さんが私に本を貸してくれました。","vi":"Anh Tanaka đã cho tôi mượn sách.","note":"貸す: かす: cho mượn, 本: ほん: sách"},{"ja":"田中さんにレポートをチェックしてもらいました。","ja_furigana":"田中さんにレポートをチェックしてもらいました。","vi":"Tôi đã nhờ anh Tanaka kiểm tra giúp báo cáo.","note":"田中: たなか, レポート: báo cáo, チェックする: kiểm tra (người nhận \"tôi\" bị lược)"},{"ja":"友達に宿題を手伝ってもらった。","ja_furigana":"友達に宿題を手伝ってもらった。","vi":"Tôi nhờ bạn làm giúp bài tập về nhà.","note":"友達: ともだち: bạn, 宿題: しゅくだい: bài tập về nhà (người nhận \"tôi\" bị lược)"},{"ja":"山田さんに荷物を運んでもらいました。","ja_furigana":"山田さんに荷物を運んでもらいました。","vi":"Tôi đã nhờ anh Yamada mang giúp đồ đạc.","note":"山田: やまだ, 荷物: にもつ: đồ đạc, 運ぶ: はこぶ: mang vác (người nhận \"tôi\" bị lược)"},{"ja":"私は友達に宿題を手伝ってもらいました。","ja_furigana":"私は友達に宿題を手伝ってもらいました。","vi":"Tôi đã nhờ bạn giúp làm bài tập về nhà.","note":"手伝う: てつだう: giúp đỡ"}],"structures":[{"Cách dùng":"～てあげます","Cấu trúc":"[Danh từ 1] は [Danh từ 2] に + ～てあげます","Nghĩa":"Làm cho ai việc gì"},{"Cách dùng":"～てくれます","Cấu trúc":"[Danh từ 1] は/が [Danh từ 2] に + ～てくれます","Nghĩa":"Được ai làm giúp việc gì"},{"Cách dùng":"～てもらいます","Cấu trúc":"[Danh từ 1] は/が [Danh từ 2] に + ～てもらいます","Nghĩa":"Nhờ ai làm giúp việc gì"}],"related":[{"title":"～んです","link":"https://onjlpt.com/ngu-phap/n4/ndesu"},{"title":"～ほうがいいです","link":"https://onjlpt.com/ngu-phap/n4/hou-ga-ii-desu"},{"title":"Động từ thể ý chí","link":"https://onjlpt.com/ngu-phap/n4/doutai-there-y-chi"},{"title":"～ようと思います/ようと思っています","link":"https://onjlpt.com/ngu-phap/n4/you-to-omoimasu-you-to-omotteimasu"}],"description":"Diễn đạt việc cho/nhận hành động, thể hiện việc làm cho ai, được ai làm giúp hoặc nhờ ai làm giúp việc gì đó"}}'),
    ('N3_2012_12', 'GRAMMAR', 7, '{"pattern":"～おかげで","expressions":["おかげでも"],"is_answer":false,"link":"https://onjlpt.com/ngu-phap/n3/okage-de","level":"N3","question":{"text":"10. 高山選手は試合前のインタビューで、「いつも応援してくれているファンの( )勝ちたい。」と語った","options":["1) ためにも","2) ようにも","3) おかげでも","4) ときでも"],"correct":1},"lesson":null}'),
    ('N3_2012_12', 'GRAMMAR', 8, '{"pattern":"～ないで、～なくて、～ず、～ずに","expressions":["しないで"],"is_answer":false,"link":"https://onjlpt.com/ngu-phap/n3/naide-nakute-zu-zuni","level":"N3","question":{"text":"17. 父はいつも、「何も__ __ _★_ __ ほうがいい。」と言っている。","options":["1) チャレンジして","2) 失敗する","3) しないで","4) いるより"],"correct":1},"lesson":null}'),
    ('N3_2012_12', 'GRAMMAR', 9, '{"pattern":"～そうです","expressions":["そうですし"],"is_answer":false,"link":"https://onjlpt.com/ngu-phap/n4/sou-desu","level":"N4","question":{"text":"14. A「片づけはあしたにしますか。」 B『あしたは朝から__ __ _★_ __ましょう。」","options":["1) 忙しくなり","2) 今日中に","3) そうですし","4) やってしまい"],"correct":2},"lesson":{"pattern":"～そうです","name":"Nghe nói là...","meaning":"Mẫu câu diễn đạt thông tin nghe được (truyền văn) hoặc suy đoán dựa trên quan sát (trạng thái)","note":"Khác biệt quan trọng giữa hai cách dùng:\n伝聞 (でんぶん): Diễn đạt thông tin nghe được, không dùng dạng quá khứ そうでした\n様態 (ようたい): Diễn đạt suy đoán từ quan sát, có thể dùng dạng quá khứ そうでした\n様態 được dùng như một tính từ -na\nPhía trước そうです (様態) không dùng thì quá khứ\nCấu trúc phủ định của 様態 có nhiều dạng: なさそうです、そうじゃありません、じゃなさそうです","usages":[{"title":"～そうです (伝聞)","meaning":"Nghe nói là...","description":"Diễn đạt thông tin nghe được từ người khác hoặc phương tiện truyền thông","structure":"Vる/Vない/Vた + そうです\\nAい/Aくない/Aかった/Aくなかった + そうです\\nAなだ/Aなじゃない/Aなだった/Aなじゃなかった + そうです\\nNだ/Nじゃない/Nだった/Nじゃなかった + そうです","examples":[{"ja":"その映画は面白いそうです。","ja_furigana":"その映画は面白いそうです。","vi":"Nghe nói là bộ phim đó thú vị lắm đấy.","note":"伝聞 - thông tin nghe được"},{"ja":"彼女は結婚するそうです。","ja_furigana":"彼女は結婚するそうです。","vi":"Nghe nói là cô ấy sẽ kết hôn.","note":"伝聞 - thông tin nghe được"},{"ja":"彼は学生だそうです。","ja_furigana":"彼は学生だそうです。","vi":"Nghe nói là anh ấy là sinh viên.","note":"伝聞 - thông tin nghe được"},{"ja":"彼は新しい仕事を見つけたそうです。","ja_furigana":"彼は新しい仕事を見つけたそうです。","vi":"Nghe nói là anh ấy đã tìm được công việc mới.","note":"伝聞 - thông tin nghe được"},{"ja":"あの有名な俳優は新しい映画に出演するそうです。","ja_furigana":"あの有名な俳優は新しい映画に出演するそうです。","vi":"Nghe nói là diễn viên nổi tiếng kia sẽ tham gia đóng phim mới.","note":"伝聞 - thông tin nghe được"}]},{"title":"～そうです (様態 - khẳng định)","meaning":"Trông có vẻ, dường như sắp","description":"Diễn đạt suy đoán dựa trên quan sát trực tiếp về trạng thái hoặc sự việc sắp xảy ra","structure":"Vます(bỏ ます) + そうです\\nAい(bỏ い) + そうです\\nAな(bỏ な) + そうです","examples":[{"ja":"このスープは熱そうですね。","ja_furigana":"このスープは熱そうですね。","vi":"Món súp này trông có vẻ nóng nhỉ.","note":"様態 - suy đoán từ quan sát"},{"ja":"空が曇って雨が降りそうです。","ja_furigana":"空が曇って雨が降りそうです。","vi":"Trời có vẻ sắp mưa.","note":"様態 - suy đoán từ quan sát"},{"ja":"雪が降りそうです。","ja_furigana":"雪が降りそうです。","vi":"Có vẻ trời sắp có tuyết.","note":"様態 - sự việc sắp xảy ra"},{"ja":"このケーキはおいしそうですから、みんな喜びそうですね。","ja_furigana":"このケーキはおいしそうですから、みんな喜びそうですね。","vi":"Cái bánh này trông có vẻ ngon nên có vẻ mọi người sẽ vui lắm nhỉ.","note":"様態 - suy đoán từ quan sát"}]},{"title":"～そうです (様態 - phủ định)","meaning":"Trông có vẻ không, dường như không","description":"Diễn đạt suy đoán phủ định dựa trên quan sát trực tiếp","structure":"Vない → なさそうです\\nAい → くなさそうです\\nAな → そうじゃありません/じゃなさそうです","examples":[{"ja":"このスープは温かくなさそうです。","ja_furigana":"このスープは温かくなさそうです。","vi":"Bát súp này trông có vẻ không ấm lắm.","note":"様態 phủ định"},{"ja":"天気は晴れじゃなさそうです。","ja_furigana":"天気は晴れじゃなさそうです。","vi":"Trông thời tiết có vẻ không nắng.","note":"様態 phủ định"},{"ja":"この料理は美味しくなさそうです。","ja_furigana":"この料理は美味しくなさそうです。","vi":"Món ăn này trông có vẻ không ngon lắm.","note":"様態 phủ định"}]}],"examples":[{"ja":"その映画は面白いそうです。","ja_furigana":"その映画は面白いそうです。","vi":"Nghe nói là bộ phim đó thú vị lắm đấy.","note":"伝聞 - thông tin nghe được"},{"ja":"彼女は結婚するそうです。","ja_furigana":"彼女は結婚するそうです。","vi":"Nghe nói là cô ấy sẽ kết hôn.","note":"伝聞 - thông tin nghe được"},{"ja":"彼は学生だそうです。","ja_furigana":"彼は学生だそうです。","vi":"Nghe nói là anh ấy là sinh viên.","note":"伝聞 - thông tin nghe được"},{"ja":"彼は新しい仕事を見つけたそうです。","ja_furigana":"彼は新しい仕事を見つけたそうです。","vi":"Nghe nói là anh ấy đã tìm được công việc mới.","note":"伝聞 - thông tin nghe được"},{"ja":"あの有名な俳優は新しい映画に出演するそうです。","ja_furigana":"あの有名な俳優は新しい映画に出演するそうです。","vi":"Nghe nói là diễn viên nổi tiếng kia sẽ tham gia đóng phim mới.","note":"伝聞 - thông tin nghe được"},{"ja":"このスープは熱そうですね。","ja_furigana":"このスープは熱そうですね。","vi":"Món súp này trông có vẻ nóng nhỉ.","note":"様態 - suy đoán từ quan sát"},{"ja":"空が曇って雨が降りそうです。","ja_furigana":"空が曇って雨が降りそうです。","vi":"Trời có vẻ sắp mưa.","note":"様態 - suy đoán từ quan sát"},{"ja":"雪が降りそうです。","ja_furigana":"雪が降りそうです。","vi":"Có vẻ trời sắp có tuyết.","note":"様態 - sự việc sắp xảy ra"},{"ja":"このケーキはおいしそうですから、みんな喜びそうですね。","ja_furigana":"このケーキはおいしそうですから、みんな喜びそうですね。","vi":"Cái bánh này trông có vẻ ngon nên có vẻ mọi người sẽ vui lắm nhỉ.","note":"様態 - suy đoán từ quan sát"},{"ja":"このスープは温かくなさそうです。","ja_furigana":"このスープは温かくなさそうです。","vi":"Bát súp này trông có vẻ không ấm lắm.","note":"様態 phủ định"},{"ja":"天気は晴れじゃなさそうです。","ja_furigana":"天気は晴れじゃなさそうです。","vi":"Trông thời tiết có vẻ không nắng.","note":"様態 phủ định"},{"ja":"この料理は美味しくなさそうです。","ja_furigana":"この料理は美味しくなさそうです。","vi":"Món ăn này trông có vẻ không ngon lắm.","note":"様態 phủ định"}],"structures":[{"Cách dùng":"～そうです (伝聞)","Cấu trúc":"Vる/Vない/Vた + そうです\\nAい/Aくない/Aかった/Aくなかった + そうです\\nAなだ/Aなじゃない/Aなだった/Aなじゃなかった + そうです\\nNだ/Nじゃない/Nだった/Nじゃなかった + そうです","Nghĩa":"Nghe nói là..."},{"Cách dùng":"～そうです (様態 - khẳng định)","Cấu trúc":"Vます(bỏ ます) + そうです\\nAい(bỏ い) + そうです\\nAな(bỏ な) + そうです","Nghĩa":"Trông có vẻ, dường như sắp"},{"Cách dùng":"～そうです (様態 - phủ định)","Cấu trúc":"Vない → なさそうです\\nAい → くなさそうです\\nAな → そうじゃありません/じゃなさそうです","Nghĩa":"Trông có vẻ không, dường như không"}],"related":[{"title":"～んです","link":"https://onjlpt.com/ngu-phap/n4/ndesu"},{"title":"～ほうがいいです","link":"https://onjlpt.com/ngu-phap/n4/hou-ga-ii-desu"},{"title":"Động từ thể ý chí","link":"https://onjlpt.com/ngu-phap/n4/doutai-there-y-chi"},{"title":"～ようと思います/ようと思っています","link":"https://onjlpt.com/ngu-phap/n4/you-to-omoimasu-you-to-omotteimasu"}],"description":"Mẫu câu diễn đạt thông tin nghe được (truyền văn) hoặc suy đoán dựa trên quan sát (trạng thái)"}}'),
    ('N3_2012_12', 'GRAMMAR', 10, '{"pattern":"～なら","expressions":["なら"],"is_answer":false,"link":"https://onjlpt.com/ngu-phap/n4/nara","level":"N4","question":{"text":"6. (電話で) 母「何か父さんに伝言はある?」 娘「じゃあ、体に気をつけてと ( ) 伝えておいてよ。」","options":["1) だけ","2) なら","3) しか","4) にも"],"correct":1},"lesson":{"pattern":"～なら","name":"Nếu A thì B (đề xuất)","meaning":"Mẫu câu điều kiện diễn đạt giả định dựa trên thông tin có sẵn, dùng để đưa ra đánh giá, mệnh lệnh, mong muốn hoặc ý định","note":"Đặc điểm khác biệt:\nKhác với các mẫu câu điều kiện khác, ～なら không yêu cầu mối quan hệ thời gian giữa hai vế (vế 1 không cần xảy ra trước vế 2)\nThường dùng để phản hồi lại thông tin đã nghe từ người đối diện\nCó thể thêm の hoặc ん phía trước なら để nhấn mạnh mà không thay đổi nghĩa","usages":[{"title":"Đưa ra đánh giá, đề xuất","meaning":"Nếu A thì B (đề xuất)","description":"Dựa vào giả định/điều kiện ở vế 1 để đưa ra đánh giá, mệnh lệnh, mong muốn hoặc ý định","structure":"Vる/Vた/Vない + なら\\nAい + なら\\nAな + なら\\nN + なら","examples":[{"ja":"大阪へ行くなら, 飛行機が速いです。","ja_furigana":"大阪へ行くなら, 飛行機が速いです。","vi":"Nếu mà đi Osaka thì đi máy bay là nhanh.","note":"飛行機: ひこうき: máy bay、速い: はやい: nhanh"},{"ja":"天気がいいなら、公園に行きましょう。","ja_furigana":"天気がいいなら、公園に行きましょう。","vi":"Nếu thời tiết đẹp thì đi công viên đi."},{"ja":"雨なら、家にいたほうがいいですよ。","ja_furigana":"雨なら、家にいたほうがいいですよ。","vi":"Nếu mà trời mưa thì ở nhà sẽ tốt hơn đấy.","note":"雨: あめ: mưa"},{"ja":"日本人なら","ja_furigana":"日本人なら","vi":"Nếu là người Nhật thì chắc chắn thích sushi."},{"ja":"行くなら早く行ったほうがいい。","ja_furigana":"行くなら早く行ったほうがいい。","vi":"Nếu đi thì nên đi sớm."}]},{"title":"Phản hồi thông tin","meaning":"Nếu đã A thì B (phản hồi)","description":"Dùng để phản hồi lại thông tin nghe được từ người đối diện và đưa ra nhận xét","structure":"Vる/Vた/Vない + なら\\nAい + なら\\nAな + なら\\nN + なら","examples":[{"ja":"スマホがあるなら、写真が撮れますね。","ja_furigana":"スマホがあるなら、写真が撮れますね。","vi":"Nếu có điện thoại thông minh thì chụp được ảnh nhỉ.","note":"Phản hồi thông tin từ người đối diện"}]}],"examples":[{"ja":"大阪へ行くなら, 飛行機が速いです。","ja_furigana":"大阪へ行くなら, 飛行機が速いです。","vi":"Nếu mà đi Osaka thì đi máy bay là nhanh.","note":"飛行機: ひこうき: máy bay、速い: はやい: nhanh"},{"ja":"天気がいいなら、公園に行きましょう。","ja_furigana":"天気がいいなら、公園に行きましょう。","vi":"Nếu thời tiết đẹp thì đi công viên đi."},{"ja":"雨なら、家にいたほうがいいですよ。","ja_furigana":"雨なら、家にいたほうがいいですよ。","vi":"Nếu mà trời mưa thì ở nhà sẽ tốt hơn đấy.","note":"雨: あめ: mưa"},{"ja":"日本人なら","ja_furigana":"日本人なら","vi":"Nếu là người Nhật thì chắc chắn thích sushi."},{"ja":"行くなら早く行ったほうがいい。","ja_furigana":"行くなら早く行ったほうがいい。","vi":"Nếu đi thì nên đi sớm."},{"ja":"スマホがあるなら、写真が撮れますね。","ja_furigana":"スマホがあるなら、写真が撮れますね。","vi":"Nếu có điện thoại thông minh thì chụp được ảnh nhỉ.","note":"Phản hồi thông tin từ người đối diện"}],"structures":[{"Cách dùng":"Đưa ra đánh giá, đề xuất","Cấu trúc":"Vる/Vた/Vない + なら\\nAい + なら\\nAな + なら\\nN + なら","Nghĩa":"Nếu A thì B (đề xuất)"},{"Cách dùng":"Phản hồi thông tin","Cấu trúc":"Vる/Vた/Vない + なら\\nAい + なら\\nAな + なら\\nN + なら","Nghĩa":"Nếu đã A thì B (phản hồi)"}],"related":[{"title":"～んです","link":"https://onjlpt.com/ngu-phap/n4/ndesu"},{"title":"～ほうがいいです","link":"https://onjlpt.com/ngu-phap/n4/hou-ga-ii-desu"},{"title":"Động từ thể ý chí","link":"https://onjlpt.com/ngu-phap/n4/doutai-there-y-chi"},{"title":"～ようと思います/ようと思っています","link":"https://onjlpt.com/ngu-phap/n4/you-to-omoimasu-you-to-omotteimasu"}],"description":"Mẫu câu điều kiện diễn đạt giả định dựa trên thông tin có sẵn, dùng để đưa ra đánh giá, mệnh lệnh, mong muốn hoặc ý định"}}'),
    ('N3_2012_12', 'GRAMMAR', 11, '{"pattern":"～まで","expressions":["まで"],"is_answer":false,"link":"https://onjlpt.com/ngu-phap/n3/made","level":"N3","question":{"text":"18.「ねえ、来近の日曜日、北町の美術館に行かない?」 B「いいね。あ、私、そこの割引券を持ってるよ。その__ __ _★_ __ になるんだ。」","options":["1) 三人","2) 割引券一枚で","3) 二割引","4) まで"],"correct":4},"lesson":null}'),
    ('N3_2012_12', 'GRAMMAR', 12, '{"pattern":"～ように、～ような","expressions":["ようにも","食べられるようになった","食べるようになった"],"is_answer":false,"link":"https://onjlpt.com/ngu-phap/n3/you-ni-you-na","level":"N3","question":{"text":"10. 高山選手は試合前のインタビューで、「いつも応援してくれているファンの( )勝ちたい。」と語った","options":["1) ためにも","2) ようにも","3) おかげでも","4) ときでも"],"correct":1},"lesson":null}');
INSERT INTO tmp_jlpt_study_item (exam_code, item_kind, sort_order, payload) VALUES
    ('N3_2013_12', 'VOCABULARY', 1, '{"word":"全部","reading":"ぜんぶ","meaning_vi":"toàn bộ","han_viet":"TOÀN BỘ","tested":true,"question_type":"paraphrase","examples":[{"ja":"全部食べました。","ja_furigana":"全部食べました。","vi":"Tôi đã ăn hết toàn bộ.","source":"dictionary"}]}'),
    ('N3_2013_12', 'VOCABULARY', 2, '{"word":"おぼれる","reading":"おぼれる","meaning_vi":"chìm đắm","han_viet":"","tested":true,"question_type":"context","examples":[{"ja":"わたしは泳ぐのが下手なので、この前、海でおぼれそうになりました。","ja_furigana":"わたしは泳ぐのが下手なので、この前、海でおぼれそうになりました。","vi":"Tôi bơi kém nên lần trước suýt nữa đã bị đuối nước ở biển.","source":"exam"}]}'),
    ('N3_2013_12', 'VOCABULARY', 3, '{"word":"こぼす","reading":"こぼす","meaning_vi":"làm đổ; làm rơi; làm rơi lệ","han_viet":"","tested":true,"question_type":"usage","examples":[{"ja":"机の上にジュースをこぼして、ノートを汚してしまいました。","ja_furigana":"机の上にジュースをこぼして、ノートを汚してしまいました。","vi":"Tôi đã làm đổ nước trái cây lên bàn, làm bẩn vở ghi chép.","source":"exam"}]}'),
    ('N3_2013_12', 'VOCABULARY', 4, '{"word":"たつ","reading":"たつ","meaning_vi":"cắt đứt","han_viet":"","tested":true,"question_type":"context","examples":[{"ja":"日本に来てから、もう3年たちました。","ja_furigana":"日本に来てから、もう3年たちました。","vi":"Từ khi đến Nhật, đã được 3 năm rồi.","source":"exam"}]}'),
    ('N3_2013_12', 'VOCABULARY', 5, '{"word":"わけ","reading":"わけ","meaning_vi":"phân chia","han_viet":"","tested":true,"question_type":"paraphrase","examples":[{"ja":"今度、わけを教えてください。","ja_furigana":"今度、わけを教えてください。","vi":"Lần tới, hãy nói cho tôi biết lý do nhé.","source":"exam"}]}'),
    ('N3_2013_12', 'VOCABULARY', 6, '{"word":"キッチン","reading":"キッチン","meaning_vi":"nhà bếp","han_viet":"","tested":true,"question_type":"paraphrase","examples":[{"ja":"高橋さんの家はキッチンが広くていいですね。","ja_furigana":"高橋さんの家はキッチンが広くていいですね。","vi":"Nhà anh Takahashi có bếp rộng, thật tốt nhỉ.","source":"exam"}]}'),
    ('N3_2013_12', 'VOCABULARY', 7, '{"word":"位置","reading":"いち","meaning_vi":"vị trí","han_viet":"VỊ TRÍ","tested":true,"question_type":"paraphrase","examples":[{"ja":"机の位置を確認しておいてください。","ja_furigana":"机の位置を確認しておいてください。","vi":"Hãy kiểm tra vị trí của cái bàn trước nhé.","source":"exam"}]}'),
    ('N3_2013_12', 'VOCABULARY', 8, '{"word":"余る","reading":"あまる","meaning_vi":"còn dư","han_viet":"DƯ","tested":true,"question_type":"usage","examples":[{"ja":"授業を欠席した人がいたので、資料が何人分か余っている。","ja_furigana":"授業を欠席した人がいたので、資料が何人分か余っている。","vi":"Vì có người vắng học nên còn thừa tài liệu cho mấy người.","source":"exam"}]}'),
    ('N3_2013_12', 'VOCABULARY', 9, '{"word":"倍","reading":"ばい","meaning_vi":"gấp đôi","han_viet":"BỘI","tested":true,"question_type":"orthography","examples":[{"ja":"米の輸出量が去年の2倍になった。","ja_furigana":"米の輸出量が去年の2倍になった。","vi":"Lượng gạo xuất khẩu đã tăng gấp đôi so với năm ngoái.","source":"exam"}]}'),
    ('N3_2013_12', 'VOCABULARY', 10, '{"word":"停電","reading":"ていでん","meaning_vi":"mất điện","han_viet":"ĐÌNH ĐIỆN","tested":true,"question_type":"orthography","examples":[{"ja":"昨日の夕方、この辺りで停電があった。","ja_furigana":"昨日の夕方、この辺りで停電があった。","vi":"Chiều hôm qua, khu vực này bị mất điện.","source":"exam"}]}'),
    ('N3_2013_12', 'VOCABULARY', 11, '{"word":"別々に","reading":"べつべつに","meaning_vi":"riêng rẽ","han_viet":"","tested":true,"question_type":"context","examples":[{"ja":"あの兄弟はいつも一緒に学校に来るのに、今日は別々に来た。","ja_furigana":"あの兄弟はいつも一緒に学校に来るのに、今日は別々に来た。","vi":"Hai anh em đó lúc nào cũng cùng đến trường, vậy mà hôm nay lại đến riêng.","source":"exam"}]}'),
    ('N3_2013_12', 'VOCABULARY', 12, '{"word":"効果","reading":"こうか","meaning_vi":"hiệu quả","han_viet":"HIỆU QUẢ","tested":true,"question_type":"usage","examples":[{"ja":"広告の効果があったようで、今月はお客さんが多かった。","ja_furigana":"広告の効果があったようで、今月はお客さんが多かった。","vi":"Có vẻ quảng cáo đã có hiệu quả, nên tháng này khách đến nhiều.","source":"exam"}]}'),
    ('N3_2013_12', 'VOCABULARY', 13, '{"word":"包む","reading":"つつむ","meaning_vi":"gói","han_viet":"BAO","tested":true,"question_type":"orthography","examples":[{"ja":"すぐに包んでください。","ja_furigana":"すぐに包んでください。","vi":"Làm ơn gói ngay giúp tôi.","source":"exam"}]}'),
    ('N3_2013_12', 'VOCABULARY', 14, '{"word":"台所","reading":"だいどころ","meaning_vi":"nhà bếp","han_viet":"ĐÀI SỞ","tested":true,"question_type":"paraphrase","examples":[{"ja":"台所で料理をします。","ja_furigana":"台所で料理をします。","vi":"Tôi nấu ăn trong nhà bếp.","source":"dictionary"}]}'),
    ('N3_2013_12', 'VOCABULARY', 15, '{"word":"各地","reading":"かくち","meaning_vi":"khắp nơi","han_viet":"CÁC ĐỊA","tested":true,"question_type":"reading","examples":[{"ja":"今週は各地でいろいろなお祭りがあります。","ja_furigana":"今週は各地でいろいろなお祭りがあります。","vi":"Tuần này có nhiều lễ hội ở khắp nơi.","source":"exam"}]}'),
    ('N3_2013_12', 'VOCABULARY', 16, '{"word":"回収","reading":"かいしゅう","meaning_vi":"thu hồi","han_viet":"HỒI THU","tested":true,"question_type":"paraphrase","examples":[{"ja":"今からアンケートを回収します。","ja_furigana":"今からアンケートを回収します。","vi":"Bây giờ tôi sẽ thu lại bảng khảo sát.","source":"exam"}]}'),
    ('N3_2013_12', 'VOCABULARY', 17, '{"word":"場所","reading":"ばしょ","meaning_vi":"nơi chốn","han_viet":"TRƯỜNG SỞ","tested":true,"question_type":"paraphrase","examples":[{"ja":"ここは静かな場所です。","ja_furigana":"ここは静かな場所です。","vi":"Đây là một nơi yên tĩnh.","source":"dictionary"}]}'),
    ('N3_2013_12', 'VOCABULARY', 18, '{"word":"売り切れる","reading":"うりきれる","meaning_vi":"bán hết","han_viet":"MẠI THIẾT","tested":true,"question_type":"paraphrase","examples":[{"ja":"その商品は売り切れた。","ja_furigana":"その商品は売り切れた。","vi":"Sản phẩm đó đã bán hết.","source":"exam"}]}'),
    ('N3_2013_12', 'VOCABULARY', 19, '{"word":"引き受ける","reading":"ひきうける","meaning_vi":"nhận làm","han_viet":"DẪN THỤ","tested":true,"question_type":"context","examples":[{"ja":"佐藤さんに仕事をお願いしたら、引き受けて くれました。","ja_furigana":"佐藤さんに仕事をお願いしたら、引き受けて くれました。","vi":"Tôi nhờ anh Sato làm việc, thì anh ấy đã nhận lời.","source":"exam"}]}'),
