    ('N3_2013_12', 'VOCABULARY', 77, '{"word":"資源","reading":"しげん","meaning_vi":"tài nguyên","han_viet":"TƯ NGUYÊN","tested":false,"question_type":"context","examples":[{"ja":"資源を大切に使う。","ja_furigana":"資源を大切に使う。","vi":"Hãy sử dụng tài nguyên một cách tiết kiệm.","source":"dictionary"}]}'),
    ('N3_2013_12', 'VOCABULARY', 78, '{"word":"賛成","reading":"さんせい","meaning_vi":"tán thành","han_viet":"TÁN THÀNH","tested":false,"question_type":"context","examples":[{"ja":"私はその案に賛成です。","ja_furigana":"私はその案に賛成です。","vi":"Tôi tán thành đề án đó.","source":"dictionary"}]}'),
    ('N3_2013_12', 'VOCABULARY', 79, '{"word":"贈る","reading":"おくる","meaning_vi":"tặng","han_viet":"TẶNG","tested":false,"question_type":"paraphrase","examples":[{"ja":"花を贈る。","ja_furigana":"花を贈る。","vi":"Tặng hoa.","source":"dictionary"}]}'),
    ('N3_2013_12', 'VOCABULARY', 80, '{"word":"通る","reading":"とおる","meaning_vi":"đi qua","han_viet":"THÔNG","tested":false,"question_type":"context","examples":[{"ja":"この道を通る。","ja_furigana":"この道を通る。","vi":"Đi qua con đường này.","source":"dictionary"}]}'),
    ('N3_2013_12', 'VOCABULARY', 81, '{"word":"部品","reading":"ぶひん","meaning_vi":"bộ phận","han_viet":"BỘ PHẨN","tested":false,"question_type":"context","examples":[{"ja":"この機械の部品を交換した。","ja_furigana":"この機械の部品を交換した。","vi":"Tôi đã thay bộ phận của chiếc máy này.","source":"dictionary"}]}'),
    ('N3_2013_12', 'VOCABULARY', 82, '{"word":"部屋","reading":"へや","meaning_vi":"phòng","han_viet":"BỘ ỐC","tested":false,"question_type":"paraphrase","examples":[{"ja":"部屋を掃除します。","ja_furigana":"部屋を掃除します。","vi":"Tôi dọn dẹp phòng.","source":"dictionary"}]}'),
    ('N3_2013_12', 'VOCABULARY', 83, '{"word":"都合","reading":"つごう","meaning_vi":"tình hình; sự tiện","han_viet":"ĐÔ HỢP","tested":false,"question_type":"context","examples":[{"ja":"都合がいいです。","ja_furigana":"都合がいいです。","vi":"Rất tiện.","source":"dictionary"}]}'),
    ('N3_2013_12', 'GRAMMAR', 1, '{"pattern":"～うちに","expressions":["ならないうちに"],"is_answer":true,"link":"https://onjlpt.com/ngu-phap/n3/uchi-ni","level":"N3","question":{"text":"11. 妹「お兄ちゃん、もう6時過ぎたよ。暗く( )帰ろうよ。」 兄「そうだね。」","options":["1) なるときで","2)ならないうちに","3)なるまえ","4) ならないあいだ"],"correct":2},"lesson":null}'),
    ('N3_2013_12', 'GRAMMAR', 2, '{"pattern":"～にとって","expressions":["にとって"],"is_answer":true,"link":"https://onjlpt.com/ngu-phap/n3/ni-totte","level":"N3","question":{"text":"4. ガソリンの値段が高くなった。毎日車を運転する私 ( ) これは大きな問題だ。","options":["1) では","2) からは","3) にとって","4)によって"],"correct":3},"lesson":null}'),
    ('N3_2013_12', 'GRAMMAR', 3, '{"pattern":"～すぎる","expressions":["やりすぎるのもよくない"],"is_answer":true,"link":"https://onjlpt.com/ngu-phap/n4/sugiru","level":"N4","question":{"text":"13. この花は、土が乾いたら水をやる必要があるが、( )。水が多いと根が腐ってしまう。","options":["1) やりすぎるのもよくない","2) やらなくていいのがいい","3) やってやるのもよくない","4) やらないでおくのがいい"],"correct":1},"lesson":{"pattern":"～すぎる","name":"Làm gì quá nhiều, quá mức","meaning":"Biểu thị sự vượt quá mức độ nào đó, thể hiện thái độ không thích, không hài lòng của người nói","note":"","usages":[{"title":"Động từ","meaning":"Làm gì quá nhiều, quá mức","description":"Diễn đạt hành động được thực hiện quá mức","structure":"[Động từ thể ます (bỏ ます)] + すぎる","examples":[{"ja":"アキラさんはゲームをやりすぎる。","ja_furigana":"アキラさんはゲームをやりすぎる。","vi":"Anh Akira chơi game quá nhiều.","note":"ゲーム: game"},{"ja":"かのじょはテレビをみすぎました。","ja_furigana":"かのじょはテレビをみすぎました。","vi":"Cô ấy đã xem TV quá nhiều.","note":"テレビ: TV"}]},{"title":"Tính từ -i","meaning":"Quá...","description":"Diễn đạt tính chất vượt quá mức bình thường","structure":"[Tính từ -i (bỏ い)] + すぎる","examples":[{"ja":"このスープはあつすぎます。","ja_furigana":"このスープはあつすぎます。","vi":"Món súp này nóng quá.","note":"あつい: nóng、スープ: súp"},{"ja":"このテストはかんたんすぎる。","ja_furigana":"このテストはかんたんすぎる。","vi":"Bài kiểm tra này quá dễ.","note":"かんたん: dễ"},{"ja":"このスープはあつすぎる。","ja_furigana":"このスープはあつすぎる。","vi":"Món súp này quá nóng.","note":"あつい: nóng"},{"ja":"このコーヒーは苦すぎる。","ja_furigana":"このコーヒーは苦すぎる。","vi":"Cà phê này quá đắng.","note":"苦い：にがい: đắng"}]},{"title":"Tính từ -na","meaning":"Quá...","description":"Diễn đạt tính chất vượt quá mức bình thường","structure":"[Tính từ -na (bỏ な)] + すぎる","examples":[{"ja":"この町は静かすぎます。","ja_furigana":"この町は静かすぎます。","vi":"Thị trấn này quá yên tĩnh.","note":"静か（な）: yên tĩnh"}]}],"examples":[{"ja":"アキラさんはゲームをやりすぎる。","ja_furigana":"アキラさんはゲームをやりすぎる。","vi":"Anh Akira chơi game quá nhiều.","note":"ゲーム: game"},{"ja":"かのじょはテレビをみすぎました。","ja_furigana":"かのじょはテレビをみすぎました。","vi":"Cô ấy đã xem TV quá nhiều.","note":"テレビ: TV"},{"ja":"このスープはあつすぎます。","ja_furigana":"このスープはあつすぎます。","vi":"Món súp này nóng quá.","note":"あつい: nóng、スープ: súp"},{"ja":"このテストはかんたんすぎる。","ja_furigana":"このテストはかんたんすぎる。","vi":"Bài kiểm tra này quá dễ.","note":"かんたん: dễ"},{"ja":"このスープはあつすぎる。","ja_furigana":"このスープはあつすぎる。","vi":"Món súp này quá nóng.","note":"あつい: nóng"},{"ja":"このコーヒーは苦すぎる。","ja_furigana":"このコーヒーは苦すぎる。","vi":"Cà phê này quá đắng.","note":"苦い：にがい: đắng"},{"ja":"この町は静かすぎます。","ja_furigana":"この町は静かすぎます。","vi":"Thị trấn này quá yên tĩnh.","note":"静か（な）: yên tĩnh"}],"structures":[{"Cách dùng":"Động từ","Cấu trúc":"[Động từ thể ます (bỏ ます)] + すぎる","Nghĩa":"Làm gì quá nhiều, quá mức"},{"Cách dùng":"Tính từ -i","Cấu trúc":"[Tính từ -i (bỏ い)] + すぎる","Nghĩa":"Quá..."},{"Cách dùng":"Tính từ -na","Cấu trúc":"[Tính từ -na (bỏ な)] + すぎる","Nghĩa":"Quá..."}],"related":[{"title":"～んです","link":"https://onjlpt.com/ngu-phap/n4/ndesu"},{"title":"～ほうがいいです","link":"https://onjlpt.com/ngu-phap/n4/hou-ga-ii-desu"},{"title":"Động từ thể ý chí","link":"https://onjlpt.com/ngu-phap/n4/doutai-there-y-chi"},{"title":"～ようと思います/ようと思っています","link":"https://onjlpt.com/ngu-phap/n4/you-to-omoimasu-you-to-omotteimasu"}],"description":"Biểu thị sự vượt quá mức độ nào đó, thể hiện thái độ không thích, không hài lòng của người nói"}}'),
    ('N3_2013_12', 'GRAMMAR', 4, '{"pattern":"～ないと、～なくちゃ","expressions":["出さないといけない"],"is_answer":true,"link":"https://onjlpt.com/ngu-phap/n3/nai-to-nakucha","level":"N3","question":{"text":"7. A「忙しそうだね。」 B「うん。今日中に( ) レポートがまだ終わらないんだ。」","options":["1) 出すようになる","2) 出すことがある","3) 出さないかもしれないだ","4) 出さないといけない"],"correct":4},"lesson":null}'),
    ('N3_2013_12', 'GRAMMAR', 5, '{"pattern":"～ないで、～なくて、～ず、～ずに","expressions":["あきらめないで","やらないでおくのがいい","やらなくていいのがいい","見せなくて","見なくて"],"is_answer":false,"link":"https://onjlpt.com/ngu-phap/n3/naide-nakute-zu-zuni","level":"N3","question":{"text":"17. 庭に植えたスイカは、これまでなかなか ___ ___ _★_ ___今年になっておいしいのができた。","options":["1) あきらめないで","2) ようやく","3) うまく育たなかったが","4) 毎年チャレンジしていたら"],"correct":4},"lesson":null}'),
    ('N3_2013_12', 'GRAMMAR', 6, '{"pattern":"～あいだ、～あいだに","expressions":["ならないあいだ"],"is_answer":false,"link":"https://onjlpt.com/ngu-phap/n3/aida-aida-ni","level":"N3","question":{"text":"11. 妹「お兄ちゃん、もう6時過ぎたよ。暗く( )帰ろうよ。」 兄「そうだね。」","options":["1) なるときで","2)ならないうちに","3)なるまえ","4) ならないあいだ"],"correct":2},"lesson":{"pattern":"～あいだ、～あいだに","name":"Trong suốt khoảng thời gian","meaning":"Diễn tả hành động xảy ra trong khoảng thời gian nào đó, phân biệt giữa hành động liên tục (あいだ) và hành động khoảnh khắc (あいだに)","note":"1. Phân biệt rõ:\n- あいだ: Hành động liên tục\n- あいだに: Hành động điểm\n2. So sánh với うちに:\n- あいだに: Khoảng thời gian xác định rõ\n- うちに: Nhấn mạnh cơ hội sắp mất\n3. Đặc biệt:\n- 知らない間に: Đột nhiên nhận ra\n- 長い間: Khoảng thời gian dài\n4. Cách dùng:\n- あいだに thường dùng với thời gian cụ thể\n- あいだ thường dùng với trạng thái kéo dài\n5. Hạn chế:\n- Không dùng ない形 với あいだ (chỉ dùng với あいだに)","usages":[{"title":"～あいだ (liên tục)","meaning":"Trong suốt khoảng thời gian","description":"Diễn tả hành động/sự việc diễn ra liên tục trong toàn bộ khoảng thời gian","structure":"Vている/Adj-i/Adj-naな/Nの + あいだ","examples":[{"ja":"冬休みのあいだ、姉は毎日ピアノを練習していた。","ja_furigana":"冬休みのあいだ、姉は毎日ピアノを練習していた。","vi":"Suốt kỳ nghỉ đông, chị tôi ngày nào cũng luyện tập piano.","note":"Nの + あいだ"},{"ja":"雪が降っているあいだ、家で暖かいココアを飲んでいた。","ja_furigana":"雪が降っているあいだ、家で暖かいココアを飲んでいた。","vi":"Trong lúc tuyết rơi, tôi đã ở nhà uống cacao nóng.","note":"Vている + あいだ"},{"ja":"彼女は東京にいるあいだ、ずっと新宿で働いていました。","ja_furigana":"彼女は東京にいるあいだ、ずっと新宿で働いていました。","vi":"Suốt thời gian ở Tokyo, cô ấy đã làm việc ở Shinjuku.","note":"Vている + あいだ"},{"ja":"彼女は休日のあいだずっと本を読んでいた。","ja_furigana":"彼女は休日のあいだずっと本を読んでいた。","vi":"Cô ấy đã đọc sách suốt cả kỳ nghỉ.","note":"So sánh với うちに"}]},{"title":"～あいだに (khoảnh khắc)","meaning":"Trong khoảng thời gian (trước khi kết thúc)","description":"Diễn tả hành động/sự việc xảy ra tại một điểm trong khoảng thời gian đó","structure":"Vる/Vている/Vない/Adj-i/Adj-naな/Nの + あいだに","examples":[{"ja":"料理をしているあいだに、電話が鳴った。","ja_furigana":"料理をしているあいだに、電話が鳴った。","vi":"Trong lúc đang nấu ăn thì điện thoại reo.","note":"Vている + あいだに"},{"ja":"この雑誌は友達を待っているあいだに、読んだ。","ja_furigana":"この雑誌は友達を待っているあいだに、読んだ。","vi":"Tôi đã đọc tạp chí này trong lúc đợi bạn.","note":"Vている + あいだに"},{"ja":"授業のあいだに質問を考えてください。","ja_furigana":"授業のあいだに質問を考えてください。","vi":"Hãy suy nghĩ câu hỏi trong giờ học nhé.","note":"Nの + あいだに"},{"ja":"学生のあいだに、海外旅行に行きたい。","ja_furigana":"学生のあいだに、海外旅行に行きたい。","vi":"Trong thời gian còn là sinh viên, tôi muốn đi du lịch nước ngoài.","note":"Vている + あいだに"},{"ja":"彼が外にいるあいだに、私は部屋を掃除した。","ja_furigana":"彼が外にいるあいだに、私は部屋を掃除した。","vi":"Trong lúc anh ấy ở ngoài, tôi đã dọn dẹp phòng.","note":"Vない + あいだに (đặc biệt)"},{"ja":"妻が買い物をしている間に掃除をしました。","ja_furigana":"妻が買い物をしている間に掃除をしました。","vi":"Tôi đã dọn dẹp trong lúc vợ đi mua sắm.","note":"Vている + あいだに"},{"ja":"昼休みのあいだにメールを送ってください。","ja_furigana":"昼休みのあいだにメールを送ってください。","vi":"Hãy gửi email trong giờ nghỉ trưa.","note":"So sánh với うちに"},{"ja":"雨が降らないあいだに帰りましょう。","ja_furigana":"雨が降らないあいだに帰りましょう。","vi":"Hãy về nhà trong lúc trời chưa mưa.","note":"So sánh với うちに"}]}],"examples":[{"ja":"冬休みのあいだ、姉は毎日ピアノを練習していた。","ja_furigana":"冬休みのあいだ、姉は毎日ピアノを練習していた。","vi":"Suốt kỳ nghỉ đông, chị tôi ngày nào cũng luyện tập piano.","note":"Nの + あいだ"},{"ja":"雪が降っているあいだ、家で暖かいココアを飲んでいた。","ja_furigana":"雪が降っているあいだ、家で暖かいココアを飲んでいた。","vi":"Trong lúc tuyết rơi, tôi đã ở nhà uống cacao nóng.","note":"Vている + あいだ"},{"ja":"彼女は東京にいるあいだ、ずっと新宿で働いていました。","ja_furigana":"彼女は東京にいるあいだ、ずっと新宿で働いていました。","vi":"Suốt thời gian ở Tokyo, cô ấy đã làm việc ở Shinjuku.","note":"Vている + あいだ"},{"ja":"彼女は休日のあいだずっと本を読んでいた。","ja_furigana":"彼女は休日のあいだずっと本を読んでいた。","vi":"Cô ấy đã đọc sách suốt cả kỳ nghỉ.","note":"So sánh với うちに"},{"ja":"料理をしているあいだに、電話が鳴った。","ja_furigana":"料理をしているあいだに、電話が鳴った。","vi":"Trong lúc đang nấu ăn thì điện thoại reo.","note":"Vている + あいだに"},{"ja":"この雑誌は友達を待っているあいだに、読んだ。","ja_furigana":"この雑誌は友達を待っているあいだに、読んだ。","vi":"Tôi đã đọc tạp chí này trong lúc đợi bạn.","note":"Vている + あいだに"},{"ja":"授業のあいだに質問を考えてください。","ja_furigana":"授業のあいだに質問を考えてください。","vi":"Hãy suy nghĩ câu hỏi trong giờ học nhé.","note":"Nの + あいだに"},{"ja":"学生のあいだに、海外旅行に行きたい。","ja_furigana":"学生のあいだに、海外旅行に行きたい。","vi":"Trong thời gian còn là sinh viên, tôi muốn đi du lịch nước ngoài.","note":"Vている + あいだに"},{"ja":"彼が外にいるあいだに、私は部屋を掃除した。","ja_furigana":"彼が外にいるあいだに、私は部屋を掃除した。","vi":"Trong lúc anh ấy ở ngoài, tôi đã dọn dẹp phòng.","note":"Vない + あいだに (đặc biệt)"},{"ja":"妻が買い物をしている間に掃除をしました。","ja_furigana":"妻が買い物をしている間に掃除をしました。","vi":"Tôi đã dọn dẹp trong lúc vợ đi mua sắm.","note":"Vている + あいだに"},{"ja":"昼休みのあいだにメールを送ってください。","ja_furigana":"昼休みのあいだにメールを送ってください。","vi":"Hãy gửi email trong giờ nghỉ trưa.","note":"So sánh với うちに"},{"ja":"雨が降らないあいだに帰りましょう。","ja_furigana":"雨が降らないあいだに帰りましょう。","vi":"Hãy về nhà trong lúc trời chưa mưa.","note":"So sánh với うちに"}],"structures":[{"Cách dùng":"～あいだ (liên tục)","Cấu trúc":"Vている/Adj-i/Adj-naな/Nの + あいだ","Nghĩa":"Trong suốt khoảng thời gian"},{"Cách dùng":"～あいだに (khoảnh khắc)","Cấu trúc":"Vる/Vている/Vない/Adj-i/Adj-naな/Nの + あいだに","Nghĩa":"Trong khoảng thời gian (trước khi kết thúc)"}],"related":[{"title":"～てしょうがない/～て仕方がない","link":"https://onjlpt.com/ngu-phap/n3/te-shouganai-te-shikata-ga-nai"},{"title":"～ため (に)","link":"https://onjlpt.com/ngu-phap/n3/tame-ni"},{"title":"～らしい","link":"https://onjlpt.com/ngu-phap/n3/rashii"},{"title":"まるで～よう/みたい","link":"https://onjlpt.com/ngu-phap/n3/marude-you-mitai"}],"description":"Diễn tả hành động xảy ra trong khoảng thời gian nào đó, phân biệt giữa hành động liên tục (あいだ) và hành động khoảnh khắc (あいだに)"}}'),
    ('N3_2013_12', 'GRAMMAR', 7, '{"pattern":"～によって","expressions":["によって"],"is_answer":false,"link":"https://onjlpt.com/ngu-phap/n3/ni-yotte","level":"N3","question":{"text":"4. ガソリンの値段が高くなった。毎日車を運転する私 ( ) これは大きな問題だ。","options":["1) では","2) からは","3) にとって","4)によって"],"correct":3},"lesson":null}'),
    ('N3_2013_12', 'GRAMMAR', 8, '{"pattern":"～ことがある/こともある","expressions":["出すことがある"],"is_answer":false,"link":"https://onjlpt.com/ngu-phap/n3/koto-ga-aru","level":"N3","question":{"text":"7. A「忙しそうだね。」 B「うん。今日中に( ) レポートがまだ終わらないんだ。」","options":["1) 出すようになる","2) 出すことがある","3) 出さないかもしれないだ","4) 出さないといけない"],"correct":4},"lesson":null}'),
    ('N3_2013_12', 'GRAMMAR', 9, '{"pattern":"～ように、～ような","expressions":["出すようになる"],"is_answer":false,"link":"https://onjlpt.com/ngu-phap/n3/you-ni-you-na","level":"N3","question":{"text":"7. A「忙しそうだね。」 B「うん。今日中に( ) レポートがまだ終わらないんだ。」","options":["1) 出すようになる","2) 出すことがある","3) 出さないかもしれないだ","4) 出さないといけない"],"correct":4},"lesson":null}');
