    ('N3_2016_12', 'VOCABULARY', 68, '{"word":"様子","reading":"ようす","meaning_vi":"tình hình","han_viet":"DẠNG TỬ","tested":false,"question_type":"context","examples":[{"ja":"彼の様子を見に行く。","ja_furigana":"彼の様子を見に行く。","vi":"Tôi đi xem tình hình của anh ấy.","source":"dictionary"}]}'),
