    ('N3_2016_12', 'VOCABULARY', 75, '{"word":"資源","reading":"しげん","meaning_vi":"tài nguyên","han_viet":"TƯ NGUYÊN","tested":false,"question_type":"context","examples":[{"ja":"資源を大切に使う。","ja_furigana":"資源を大切に使う。","vi":"Hãy sử dụng tài nguyên một cách tiết kiệm.","source":"dictionary"}]}'),
    ('N3_2016_12', 'VOCABULARY', 76, '{"word":"越え","reading":"ごえ","meaning_vi":"vượt qua","han_viet":"VIỆT","tested":false,"question_type":"context","examples":[{"ja":"山越えは大変だ。","ja_furigana":"山越えは大変だ。","vi":"Vượt núi thì rất vất vả.","source":"dictionary"}]}'),
    ('N3_2016_12', 'VOCABULARY', 77, '{"word":"通し","reading":"とおし","meaning_vi":"liên tục từ đầu đến cuối","han_viet":"","tested":false,"question_type":"context","examples":[{"ja":"この映画は通しで見た。","ja_furigana":"この映画は通しで見た。","vi":"Tôi đã xem bộ phim này từ đầu đến cuối.","source":"dictionary"}]}'),
    ('N3_2016_12', 'VOCABULARY', 78, '{"word":"閲","reading":"えつ","meaning_vi":"kiểm duyệt; dấu chấp thuận","han_viet":"DUYỆT","tested":false,"question_type":"context","examples":[{"ja":"この書類に閲を受ける。","ja_furigana":"この書類に閲を受ける。","vi":"Tài liệu này được kiểm tra và đóng dấu chấp thuận.","source":"dictionary"}]}'),
    ('N3_2016_12', 'VOCABULARY', 79, '{"word":"驚く","reading":"おどろく","meaning_vi":"ngạc nhiên","han_viet":"KINH","tested":false,"question_type":"paraphrase","examples":[{"ja":"彼はその知らせに驚いた。","ja_furigana":"彼はその知らせに驚いた。","vi":"Anh ấy đã ngạc nhiên trước tin đó.","source":"dictionary"}]}'),
    ('N3_2016_12', 'GRAMMAR', 1, '{"pattern":"～としたら/～とすれば","expressions":["としたら"],"is_answer":true,"link":"https://onjlpt.com/ngu-phap/n3/to-shitara-to-sureba","level":"N3","question":{"text":"37. 先週、会社面接で「もし自分を色で表す ( ) 、何色ですか。」と聞かれ、オレンジ色と答えた。「元気」や「健康」のイメージがあるからだ。","options":["1) ことから","2) いう点で","3) ように","4) としたら"],"correct":4},"lesson":null}'),
    ('N3_2016_12', 'GRAMMAR', 2, '{"pattern":"～として（は）/としても/としての","expressions":["として"],"is_answer":true,"link":"https://onjlpt.com/ngu-phap/n3/toshite","level":"N3","question":{"text":"36. 彼は小説家 ( ) 有名になったが、普段は小さな病院で働く医者だ。","options":["1) について","2) として","3) にしたがって","4) と比べて"],"correct":2},"lesson":null}'),
    ('N3_2016_12', 'GRAMMAR', 3, '{"pattern":"～ておく","expressions":["予約しておくよ"],"is_answer":true,"link":"https://onjlpt.com/ngu-phap/n4/te-oku","level":"N4","question":{"text":"46. 妻:「ねえ、ちょっと買い物に行ってくるから、今夜行くレストランの予約をお願いできる?」 夫:「うん、わかった（）。19時からで大丈夫?」 妻:「ええ、ありがとう。」","options":["1) 予約してね","2) 予約しておくよ","3) 予約しようよ","4) 予約してある"],"correct":2},"lesson":{"pattern":"～ておく","name":"Làm trước/làm sẵn","meaning":"Diễn đạt việc làm gì đó trước để chuẩn bị cho tương lai hoặc làm sẵn để giúp đỡ người khác","note":"Diễn đạt việc làm trước để chuẩn bị cho tương lai.\nDiễn đạt việc làm sẵn để giúp đỡ người khác.\nTrong hội thoại thường được rút gọn thành ～とく (ví dụ: しとく、しといて).\nThường đi với các từ chỉ mục đích như ため、ために.\nKhác với ～てある: ～ておく nhấn mạnh hành động chuẩn bị, ～てある nhấn mạnh trạng thái kết quả.","usages":[{"title":"Chuẩn bị cho tương lai","meaning":"Làm trước/làm sẵn","description":"Diễn đạt việc thực hiện hành động trước để chuẩn bị cho sự việc trong tương lai","structure":"[Danh từ] を + [Động từ thể て] + おく","examples":[{"ja":"明日のプレゼンのため、資料を準備しておきました。","ja_furigana":"明日のプレゼンのため、資料を準備しておきました。","vi":"Để chuẩn bị cho buổi thuyết trình ngày mai, tôi đã chuẩn bị sẵn tài liệu rồi.","note":"プレゼン: ぷれぜん: buổi thuyết trình, 資料: しりょう: tài liệu"},{"ja":"母が来る前に、夕食を作っておきます。","ja_furigana":"母が来る前に、夕食を作っておきます。","vi":"Mẹ sắp đến nên tôi nấu bữa tối trước."},{"ja":"パーティーのために、ケーキを注文しておきました。","ja_furigana":"パーティーのために、ケーキを注文しておきました。","vi":"Tôi đã đặt bánh sẵn để chuẩn bị cho bữa tiệc.","note":"パーティー: bữa tiệc, ケーキ: bánh"},{"ja":"旅行の前に地図を印刷しておくといい。","ja_furigana":"旅行の前に地図を印刷しておくといい。","vi":"Trước khi đi du lịch thì nên in sẵn bản đồ."},{"ja":"旅行のために荷物を詰めておく必要がある。","ja_furigana":"旅行のために荷物を詰めておく必要がある。","vi":"Cần phải sắp xếp hành lý sẵn sàng cho chuyến du lịch.","note":"荷物: にもつ: hành lý"}]},{"title":"Làm sẵn để giúp đỡ","meaning":"Làm sẵn cho ai","description":"Diễn đạt việc làm sẵn điều gì đó để giúp đỡ người khác","structure":"[Danh từ] を + [Động từ thể て] + おく","examples":[{"ja":"資料をコピーしておいたよ。","ja_furigana":"資料をコピーしておいたよ。","vi":"Tôi đã photo sẵn tài liệu rồi đấy.","note":"資料: しりょう: tài liệu"},{"ja":"その資料は僕に準備しておくよ。","ja_furigana":"その資料は僕に準備しておくよ。","vi":"Tài liệu đó cứ để tôi chuẩn bị sẵn cho.","note":"準備する: じゅんびする: chuẩn bị"},{"ja":"食材を買っておくから、料理が早くできるよ。","ja_furigana":"食材を買っておくから、料理が早くできるよ。","vi":"Tôi sẽ mua sẵn nguyên liệu nên có thể nấu ăn nhanh hơn.","note":"食材: しょくざい: nguyên liệu, 料理: りょうり: nấu ăn"},{"ja":"チケットを買っておくから、安心して。","ja_furigana":"チケットを買っておくから、安心して。","vi":"Tôi sẽ mua sẵn vé (cho anh) nên cứ yên tâm.","note":"Dạng rút gọn ～ておく → ～とく"}]}],"examples":[{"ja":"明日のプレゼンのため、資料を準備しておきました。","ja_furigana":"明日のプレゼンのため、資料を準備しておきました。","vi":"Để chuẩn bị cho buổi thuyết trình ngày mai, tôi đã chuẩn bị sẵn tài liệu rồi.","note":"プレゼン: ぷれぜん: buổi thuyết trình, 資料: しりょう: tài liệu"},{"ja":"母が来る前に、夕食を作っておきます。","ja_furigana":"母が来る前に、夕食を作っておきます。","vi":"Mẹ sắp đến nên tôi nấu bữa tối trước."},{"ja":"パーティーのために、ケーキを注文しておきました。","ja_furigana":"パーティーのために、ケーキを注文しておきました。","vi":"Tôi đã đặt bánh sẵn để chuẩn bị cho bữa tiệc.","note":"パーティー: bữa tiệc, ケーキ: bánh"},{"ja":"旅行の前に地図を印刷しておくといい。","ja_furigana":"旅行の前に地図を印刷しておくといい。","vi":"Trước khi đi du lịch thì nên in sẵn bản đồ."},{"ja":"旅行のために荷物を詰めておく必要がある。","ja_furigana":"旅行のために荷物を詰めておく必要がある。","vi":"Cần phải sắp xếp hành lý sẵn sàng cho chuyến du lịch.","note":"荷物: にもつ: hành lý"},{"ja":"資料をコピーしておいたよ。","ja_furigana":"資料をコピーしておいたよ。","vi":"Tôi đã photo sẵn tài liệu rồi đấy.","note":"資料: しりょう: tài liệu"},{"ja":"その資料は僕に準備しておくよ。","ja_furigana":"その資料は僕に準備しておくよ。","vi":"Tài liệu đó cứ để tôi chuẩn bị sẵn cho.","note":"準備する: じゅんびする: chuẩn bị"},{"ja":"食材を買っておくから、料理が早くできるよ。","ja_furigana":"食材を買っておくから、料理が早くできるよ。","vi":"Tôi sẽ mua sẵn nguyên liệu nên có thể nấu ăn nhanh hơn.","note":"食材: しょくざい: nguyên liệu, 料理: りょうり: nấu ăn"},{"ja":"チケットを買っておくから、安心して。","ja_furigana":"チケットを買っておくから、安心して。","vi":"Tôi sẽ mua sẵn vé (cho anh) nên cứ yên tâm.","note":"Dạng rút gọn ～ておく → ～とく"}],"structures":[{"Cách dùng":"Chuẩn bị cho tương lai","Cấu trúc":"[Danh từ] を + [Động từ thể て] + おく","Nghĩa":"Làm trước/làm sẵn"},{"Cách dùng":"Làm sẵn để giúp đỡ","Cấu trúc":"[Danh từ] を + [Động từ thể て] + おく","Nghĩa":"Làm sẵn cho ai"}],"related":[{"title":"～んです","link":"https://onjlpt.com/ngu-phap/n4/ndesu"},{"title":"～ほうがいいです","link":"https://onjlpt.com/ngu-phap/n4/hou-ga-ii-desu"},{"title":"Động từ thể ý chí","link":"https://onjlpt.com/ngu-phap/n4/doutai-there-y-chi"},{"title":"～ようと思います/ようと思っています","link":"https://onjlpt.com/ngu-phap/n4/you-to-omoimasu-you-to-omotteimasu"}],"description":"Diễn đạt việc làm gì đó trước để chuẩn bị cho tương lai hoặc làm sẵn để giúp đỡ người khác"}}'),
    ('N3_2016_12', 'GRAMMAR', 4, '{"pattern":"～ないと、～なくちゃ","expressions":["寝られないと"],"is_answer":true,"link":"https://onjlpt.com/ngu-phap/n3/nai-to-nakucha","level":"N3","question":{"text":"44. 昼寝をするのは気持ちがいいが、夜 ( ) 困るので、いつも15分ぐらいで起きる。","options":["1) 寝なくて","2) 寝られると思って","3) 寝られないと","4) 寝ると思うと"],"correct":3},"lesson":null}'),
    ('N3_2016_12', 'GRAMMAR', 5, '{"pattern":"～ことになった/～ことになっている","expressions":["持っていくことになっている"],"is_answer":true,"link":"https://onjlpt.com/ngu-phap/n3/koto-ni-natta","level":"N3","question":{"text":"43. 息子が通う高校では、お昼にパンや飲み物が買える場所もあるが、基本的には全員がお弁当を ( ) 。","options":["1) 持っていったばかりだ","2) 持っていくことになっている","3) 持っていきたい","4) 持っていくつ香りだ"],"correct":2},"lesson":null}'),
    ('N3_2016_12', 'GRAMMAR', 6, '{"pattern":"～ので、～から","expressions":["から"],"is_answer":false,"link":"https://onjlpt.com/ngu-phap/n5/node-kara","level":"N5","question":{"text":"52. (レスランで) 客: 「すみません 15分ぐらい前に案内をお願いして、しばらくここで待てって___ ___ _★_ ___ 。まだですか。」 店員:「大変申し訳ありません。」","options":["1) 待っているんです","2) 言われた","3) から","4) けど"],"correct":1},"lesson":{"pattern":"～ので、～から","name":"Vì/Bởi vì... nên...","meaning":"Diễn đạt nguyên nhân \"vì/bởi vì... nên...\", trong đó ので mang tính khách quan còn から thể hiện cảm xúc, thái độ người nói","note":"Quy tắc sử dụng:\nので: Mang tính khách quan, trang trọng, dùng cho sự việc đơn thuần\nから: Mang tính chủ quan, thể hiện cảm xúc, thái độ, dùng với mệnh lệnh, yêu cầu, nhờ vả\nんで: Cách nói thông tục của ので, dùng trong hội thoại\nからです: Dùng để trả lời câu hỏi どうして～か (tại sao?)\nLưu ý: ので thường đi với thể thường hoặc thể ます, còn から có thể đi với nhiều hình thức hơn bao gồm cả だ/です với danh từ và tính từ-na.","usages":[{"title":"～ので (khách quan)","meaning":"Vì/Bởi vì... nên...","description":"Diễn đạt nguyên nhân một cách khách quan, trang trọng, thường dùng cho sự việc đơn thuần","structure":"[Động từ/Tính từ/Danh từ] + ので","examples":[{"ja":"あめがふっているので、うちにいます。","ja_furigana":"あめがふっているので、うちにいます。","vi":"Vì trời mưa nên tôi ở nhà."},{"ja":"あめがふっているのでさんぽしません。","ja_furigana":"あめがふっているのでさんぽしません。","vi":"Vì trời đang mưa nên tôi không đi dạo."},{"ja":"このほんはおもしろいのでぜんぶよみました。","ja_furigana":"このほんはおもしろいのでぜんぶよみました。","vi":"Vì cuốn sách này thú vị nên tôi đã đọc hết.","note":"おもしろい: thú vị"},{"ja":"おなかがすいたのでごはんをたべましょう。","ja_furigana":"おなかがすいたのでごはんをたべましょう。","vi":"Vì đói bụng nên chúng ta hãy ăn cơm."},{"ja":"かのじょはせんせいですのでまいにちいそがしいです。","ja_furigana":"かのじょはせんせいですのでまいにちいそがしいです。","vi":"Cô ấy là giáo viên nên ngày nào cũng bận rộn.","note":"せんせい: giáo viên, まいにち: hàng ngày, いそがしい: bận"}]},{"title":"～から (chủ quan)","meaning":"Vì/Bởi vì... nên...","description":"Diễn đạt nguyên nhân mang tính chủ quan, thể hiện cảm xúc, thái độ người nói, dùng với mệnh lệnh, yêu cầu","structure":"[Động từ/Tính từ/Danh từ] + から","examples":[{"ja":"ねつがさがったから、がっこうにいきます。","ja_furigana":"ねつがさがったから、がっこうにいきます。","vi":"Vì đã hạ sốt nên tôi sẽ đi học."},{"ja":"きょうはあめがふるから、うちにいます。","ja_furigana":"きょうはあめがふるから、うちにいます。","vi":"Hôm nay trời mưa nên tôi ở nhà."},{"ja":"おなかがすいたから、ごはんをたべます。","ja_furigana":"おなかがすいたから、ごはんをたべます。","vi":"Tôi đói bụng nên tôi sẽ ăn cơm."},{"ja":"あめがふっているから、かさをもっていってください。","ja_furigana":"あめがふっているから、かさをもっていってください。","vi":"Vì trời đang mưa nên hãy mang theo ô."},{"ja":"かれはゆうめいだから、いつもいそがしいです。","ja_furigana":"かれはゆうめいだから、いつもいそがしいです。","vi":"Anh ấy nổi tiếng nên lúc nào cũng bận rộn.","note":"有名: ゆうめい: nổi tiếng"},{"ja":"あたまがいたいですから, しゅくだいをやすんでもいいですか。","ja_furigana":"あたまがいたいですから, しゅくだいをやすんでもいいですか。","vi":"Vì bị đau đầu nên em có thể không làm bài tập được không ạ?","note":"Dùng với yêu cầu, nhờ vả"}]},{"title":"～んで (thông tục)","meaning":"Vì/Bởi vì... nên...","description":"Cách nói thông thường, ít trang trọng của ので, thường dùng trong hội thoại","structure":"[Thể thường] + んで","examples":[{"ja":"あたまがいたいんで、うちでやすみます。","ja_furigana":"あたまがいたいんで、うちでやすみます。","vi":"Vì đau đầu nên tôi ở nhà nghỉ ngơi.","note":"Cách nói thông tục của ので"},{"ja":"今日は雨なんで、うちにいます。","ja_furigana":"今日は雨なんで、うちにいます。","vi":"Hôm nay trời mưa nên tôi ở nhà.","note":"Cách nói thông tục của ので"}]},{"title":"～からです (trả lời)","meaning":"Vì...","description":"Dùng để trả lời cho câu hỏi どうして～か (tại sao?)","structure":"[Lý do] + からです","examples":[{"ja":"ともだちが言ったからです。","ja_furigana":"ともだちが言ったからです。","vi":"Vì bạn tôi đã nói.","note":"Trả lời cho どうして"},{"ja":"かぜをひいたからです。","ja_furigana":"かぜをひいたからです。","vi":"Vì tớ bị cảm.","note":"Trả lời cho どうして"}]}],"examples":[{"ja":"あめがふっているので、うちにいます。","ja_furigana":"あめがふっているので、うちにいます。","vi":"Vì trời mưa nên tôi ở nhà."},{"ja":"あめがふっているのでさんぽしません。","ja_furigana":"あめがふっているのでさんぽしません。","vi":"Vì trời đang mưa nên tôi không đi dạo."},{"ja":"このほんはおもしろいのでぜんぶよみました。","ja_furigana":"このほんはおもしろいのでぜんぶよみました。","vi":"Vì cuốn sách này thú vị nên tôi đã đọc hết.","note":