    ('N3_2017_07', 'VOCABULARY', 80, '{"word":"組み立てる","reading":"くみたてる","meaning_vi":"lắp ráp; ghép lại","han_viet":"TỔM LẬP","tested":false,"question_type":"context","examples":[{"ja":"家具を組み立てる。","ja_furigana":"家具を組み立てる。","vi":"Lắp ráp đồ nội thất.","source":"dictionary"}]}'),
    ('N3_2017_07', 'VOCABULARY', 81, '{"word":"触れる","reading":"ふれる","meaning_vi":"chạm vào","han_viet":"XÚC","tested":false,"question_type":"context","examples":[{"ja":"壁に触れると冷たかった。","ja_furigana":"壁に触れると冷たかった。","vi":"Khi chạm vào bức tường thì thấy lạnh.","source":"dictionary"}]}'),
    ('N3_2017_07', 'VOCABULARY', 82, '{"word":"身近","reading":"みぢか","meaning_vi":"gần gũi","han_viet":"THÂN CẬN","tested":false,"question_type":"context","examples":[{"ja":"身近な問題を考える。","ja_furigana":"身近な問題を考える。","vi":"Suy nghĩ về vấn đề gần gũi.","source":"dictionary"}]}'),
