    ('N3_2018_12', 'VOCABULARY', 4, '{"word":"まよう","reading":"まよう","meaning_vi":"lạc đường","han_viet":"","tested":true,"question_type":"context","examples":[{"ja":"どちらのパソコンを買おうか、まだまよって います。","ja_furigana":"どちらのパソコンを買おうか、まだまよって います。","vi":"Tôi vẫn còn đang phân vân không biết nên mua máy tính nào.","source":"exam"}]}'),
    ('N3_2018_12', 'VOCABULARY', 5, '{"word":"やっと","reading":"やっと","meaning_vi":"cuối cùng","han_viet":"","tested":true,"question_type":"paraphrase","examples":[{"ja":"やっと宿題が終わった。","ja_furigana":"やっと宿題が終わった。","vi":"Cuối cùng tôi đã làm xong bài tập về nhà.","source":"dictionary"}]}'),
