    ('N3_2019_07', 'VOCABULARY', 4, '{"word":"かき混ぜる","reading":"かきまぜる","meaning_vi":"trộn","han_viet":"HỖN","tested":true,"question_type":"usage","examples":[{"ja":"牛乳に卵と佐藤を入れたら、よくかき混ぜてください。","ja_furigana":"牛乳に卵と佐藤を入れたら、よくかき混ぜてください。","vi":"Nếu cho trứng và đường vào sữa, hãy khuấy đều.","source":"exam"}]}'),
    ('N3_2019_07', 'VOCABULARY', 5, '{"word":"さっそく","reading":"さっそく","meaning_vi":"ngay lập tức","han_viet":"","tested":true,"question_type":"context","examples":[{"ja":"注文したカメラが届いたのがうれしくて、さっそく箱から出して使ってみた。","ja_furigana":"注文したカメラが届いたのがうれしくて、さっそく箱から出して使ってみた。","vi":"Tôi rất vui vì chiếc máy ảnh đã đặt mua được giao đến, nên lập tức lấy ra khỏi hộp và thử dùng.","source":"exam"}]}'),
    ('N3_2019_07', 'VOCABULARY', 6, '{"word":"したしい","reading":"したしい","meaning_vi":"thân thiết","han_viet":"","tested":true,"question_type":"context","examples":[{"ja":"私は引っ越ししてきたばかりなので、まだ近所にしたしい人がいません。","ja_furigana":"私は引っ越ししてきたばかりなので、まだ近所にしたしい人がいません。","vi":"Tôi mới chuyển đến nên vẫn chưa có người quen ở khu này.","source":"exam"}]}'),
    ('N3_2019_07', 'VOCABULARY', 7, '{"word":"しまう","reading":"しまう","meaning_vi":"kết thúc","han_viet":"","tested":true,"question_type":"context","examples":[{"ja":"使った後は、この箱にきちんとしまってください。","ja_furigana":"使った後は、この箱にきちんとしまってください。","vi":"Sau khi dùng xong, hãy cất gọn vào chiếc hộp này.","source":"exam"}]}'),
    ('N3_2019_07', 'VOCABULARY', 8, '{"word":"そのまま","reading":"そのまま","meaning_vi":"nguyên như vậy","han_viet":"","tested":true,"question_type":"paraphrase","examples":[{"ja":"先生に言われたことをそのまま書きました。","ja_furigana":"先生に言われたことをそのまま書きました。","vi":"Tôi đã viết đúng như những gì thầy giáo bảo.","source":"exam"}]}'),
    ('N3_2019_07', 'VOCABULARY', 9, '{"word":"よい","reading":"よい","meaning_vi":"tốt","han_viet":"","tested":true,"question_type":"paraphrase","examples":[{"ja":"この公園はとても良い。","ja_furigana":"この公園はとても良い。","vi":"Công viên này rất đẹp.","source":"dictionary"}]}'),
    ('N3_2019_07', 'VOCABULARY', 10, '{"word":"ノック","reading":"ノック","meaning_vi":"cú gõ","han_viet":"","tested":true,"question_type":"context","examples":[{"ja":"部屋に入るときは、ドアをノックしてください。","ja_furigana":"部屋に入るときは、ドアをノックしてください。","vi":"Khi vào phòng, hãy gõ cửa.","source":"exam"}]}'),
    ('N3_2019_07', 'VOCABULARY', 11, '{"word":"停電","reading":"ていでん","meaning_vi":"mất điện","han_viet":"ĐÌNH ĐIỆN","tested":true,"question_type":"orthography","examples":[{"ja":"昨日の夜、3０分停電した。","ja_furigana":"昨日の夜、3０分停電した。","vi":"Tối qua bị mất điện 30 phút.","source":"exam"}]}'),
    ('N3_2019_07', 'VOCABULARY', 12, '{"word":"内側","reading":"うちがわ","meaning_vi":"bên trong","han_viet":"NỘI TRẮC","tested":true,"question_type":"orthography","examples":[{"ja":"箱の内側を見てください。","ja_furigana":"箱の内側を見てください。","vi":"Hãy nhìn vào mặt trong của cái hộp.","source":"exam"}]}'),
    ('N3_2019_07', 'VOCABULARY', 13, '{"word":"冗談","reading":"じょうだん","meaning_vi":"trò đùa","han_viet":"TIỀU ĐÀM","tested":true,"question_type":"context","examples":[{"ja":"佐藤さんは、いつも冗談を言って、みんなを笑わせます。","ja_furigana":"佐藤さんは、いつも冗談を言って、みんなを笑わせます。","vi":"Anh Sato lúc nào cũng kể chuyện cười và làm mọi người bật cười.","source":"exam"}]}'),
    ('N3_2019_07', 'VOCABULARY', 14, '{"word":"包む","reading":"つつむ","meaning_vi":"gói","han_viet":"BAO","tested":true,"question_type":"reading","examples":[{"ja":"これを包んでもらえませんか。","ja_furigana":"これを包んでもらえませんか。","vi":"Anh/chị có thể gói cái này giúp tôi không?","source":"exam"}]}'),
    ('N3_2019_07', 'VOCABULARY', 15, '{"word":"取り消す","reading":"とりけす","meaning_vi":"hủy bỏ","han_viet":"THỦ TIÊU","tested":true,"question_type":"context","examples":[{"ja":"旅行に行かなくなってしまったので、ホテルの予約を取り消した。","ja_furigana":"旅行に行かなくなってしまったので、ホテルの予約を取り消した。","vi":"Vì tôi không đi du lịch nữa nên đã hủy đặt phòng khách sạn.","source":"exam"}]}'),
    ('N3_2019_07', 'VOCABULARY', 16, '{"word":"報告","reading":"ほうこく","meaning_vi":"báo cáo","han_viet":"BÁO CÁO","tested":true,"question_type":"usage","examples":[{"ja":"アンケートの結果について、今日の会議で報告があった。","ja_furigana":"アンケートの結果について、今日の会議で報告があった。","vi":"Trong cuộc họp hôm nay đã có báo cáo về kết quả của bảng khảo sát.","source":"exam"}]}'),
    ('N3_2019_07', 'VOCABULARY', 17, '{"word":"変","reading":"へん","meaning_vi":"kỳ lạ","han_viet":"BIẾN","tested":true,"question_type":"paraphrase","examples":[{"ja":"彼は変な人だ。","ja_furigana":"彼は変な人だ。","vi":"Anh ấy là một người kỳ lạ.","source":"dictionary"}]}'),
