    ('N3_2019_07', 'VOCABULARY', 20, '{"word":"方角","reading":"ほうがく","meaning_vi":"hướng","han_viet":"PHƯƠNG GIÁC","tested":true,"question_type":"reading","examples":[{"ja":"歩いているうちに方角がわからなくなった。","ja_furigana":"歩いているうちに方角がわからなくなった。","vi":"Trong lúc đi bộ, tôi đã không còn biết phương hướng nữa.","source":"exam"}]}'),
    ('N3_2019_07', 'VOCABULARY', 21, '{"word":"昼食","reading":"ちゅうしょく","meaning_vi":"bữa trưa","han_viet":"TRÚC THỰC","tested":true,"question_type":"reading","examples":[{"ja":"昼食の後は工場見学です。","ja_furigana":"昼食の後は工場見学です。","vi":"Sau bữa trưa là đi tham quan nhà máy.","source":"exam"}]}'),
    ('N3_2019_07', 'VOCABULARY', 22, '{"word":"最初","reading":"さいしょ","meaning_vi":"ban đầu","han_viet":"TỐI SƠ","tested":true,"question_type":"orthography","examples":[{"ja":"最初に来たのは鈴木さんです。","ja_furigana":"最初に来たのは鈴木さんです。","vi":"Người đến đầu tiên là anh Suzuki.","source":"exam"}]}'),
    ('N3_2019_07', 'VOCABULARY', 23, '{"word":"欠点","reading":"けってん","meaning_vi":"khuyết điểm","han_viet":"KHIẾM ĐIỂM","tested":true,"question_type":"paraphrase","examples":[{"ja":"このパソコンには何か欠点はありますか。","ja_furigana":"このパソコンには何か欠点はありますか。","vi":"Chiếc máy tính này có nhược điểm gì không?","source":"exam"}]}'),
    ('N3_2019_07', 'VOCABULARY', 24, '{"word":"浅い","reading":"あさい","meaning_vi":"nông","han_viet":"THIỂN","tested":true,"question_type":"orthography","examples":[{"ja":"もう少し浅い皿がほしいです。","ja_furigana":"もう少し浅い皿がほしいです。","vi":"Tôi muốn một cái đĩa nông hơn một chút.","source":"exam"}]}'),
    ('N3_2019_07', 'VOCABULARY', 25, '{"word":"済ませる","reading":"すませる","meaning_vi":"hoàn thành","han_viet":"TẾ","tested":true,"question_type":"paraphrase","examples":[{"ja":"早く済ませてください。","ja_furigana":"早く済ませてください。","vi":"Hãy làm cho xong nhanh lên.","source":"exam"}]}'),
