    ('N3_2019_07', 'VOCABULARY', 27, '{"word":"片付ける","reading":"かたづける","meaning_vi":"dọn dẹp","han_viet":"PHIẾN PHÓ","tested":true,"question_type":"paraphrase","examples":[{"ja":"部屋を片付ける。","ja_furigana":"部屋を片付ける。","vi":"Dọn dẹp phòng.","source":"dictionary"}]}'),
    ('N3_2019_07', 'VOCABULARY', 28, '{"word":"発生","reading":"はっせい","meaning_vi":"sự phát sinh","han_viet":"PHÁT SINH","tested":true,"question_type":"usage","examples":[{"ja":"火災が 発生したときのために、みんなで避難訓川練をした。","ja_furigana":"火災が 発生したときのために、みんなで避難訓川練をした。","vi":"Để phòng khi xảy ra hỏa hoạn, mọi người đã cùng nhau tập diễn tập sơ tán.","source":"exam"}]}'),
    ('N3_2019_07', 'VOCABULARY', 29, '{"word":"積極","reading":"せっきょく","meaning_vi":"tích cực","han_viet":"TÍCH CỰC","tested":true,"question_type":"context","examples":[{"ja":"中村さんは、いろんなことを自分からやってみようとする積極的な人です。","ja_furigana":"中村さんは、いろんなことを自分からやってみようとする積極的な人です。","vi":"Anh Nakamura là người rất chủ động, luôn muốn tự mình thử làm nhiều việc khác nhau.","source":"exam"}]}'),
    ('N3_2019_07', 'VOCABULARY', 30, '{"word":"終わる","reading":"おわる","meaning_vi":"kết thúc","han_viet":"CHUNG","tested":true,"question_type":"paraphrase","examples":[{"ja":"仕事が終わる。","ja_furigana":"仕事が終わる。","vi":"Công việc kết thúc.","source":"dictionary"}]}'),
