    ('N3_2022_12', 'VOCABULARY', 84, '{"word":"賛成","reading":"さんせい","meaning_vi":"tán thành","han_viet":"TÁN THÀNH","tested":false,"question_type":"paraphrase","examples":[{"ja":"私はその案に賛成です。","ja_furigana":"私はその案に賛成です。","vi":"Tôi tán thành đề án đó.","source":"dictionary"}]}'),
    ('N3_2022_12', 'VOCABULARY', 85, '{"word":"近く","reading":"ちかく","meaning_vi":"gần","han_viet":"","tested":false,"question_type":"paraphrase","examples":[{"ja":"駅の近くに住んでいます。","ja_furigana":"駅の近くに住んでいます。","vi":"Tôi sống gần nhà ga.","source":"dictionary"}]}'),
    ('N3_2022_12', 'VOCABULARY', 86, '{"word":"飛び出す","reading":"とびだす","meaning_vi":"lao ra","han_viet":"PHI XUẤT","tested":false,"question_type":"context","examples":[{"ja":"子どもが外へ飛び出す。","ja_furigana":"子どもが外へ飛び出す。","vi":"Đứa trẻ lao ra ngoài.","source":"dictionary"}]}'),
    ('N3_2022_12', 'VOCABULARY', 87, '{"word":"飽きる","reading":"あきる","meaning_vi":"chán","han_viet":"","tested":false,"question_type":"context","examples":[{"ja":"毎日同じ料理を食べると飽きる。","ja_furigana":"毎日同じ料理を食べると飽きる。","vi":"Nếu ăn cùng một món mỗi ngày thì sẽ chán.","source":"dictionary"}]}'),
    ('N3_2022_12', 'VOCABULARY', 88, '{"word":"騒ぐ","reading":"さわぐ","meaning_vi":"ồn ào","han_viet":"TÁO","tested":false,"question_type":"context","examples":[{"ja":"子どもたちが庭で騒ぐ。","ja_furigana":"子どもたちが庭で騒ぐ。","vi":"Bọn trẻ làm ồn trong sân.","source":"dictionary"}]}'),
    ('N3_2022_12', 'GRAMMAR', 1, '{"pattern":"～ために、～ように","expressions":["ために"],"is_answer":true,"link":"https://onjlpt.com/ngu-phap/n4/tame-ni-you-ni","level":"N4","question":{"text":"6) 私の応援している野球選手が、肩のけがの( )、しばらく試合に出られなくなった。とても心配だ。","options":["1) 途中で","2) 一方で","3) ように","4) ために"],"correct":4},"lesson":{"pattern":"～ために、～ように","name":"Để làm gì/Vì cái gì","meaning":"Diễn đạt mục đích với sự khác biệt về sắc thái: ～ために cho mục đích trực tiếp, ～ように cho mục đích gián tiếp hoặc không thuộc kiểm soát trực tiếp","note":"「～ために」dùng cho mục đích trực tiếp thuộc kiểm soát của người nói\n「～ように」dùng cho mục đích gián tiếp, không thuộc kiểm soát trực tiếp, hoặc liên quan đến khả năng\nThể ない thường chỉ dùng với 「ように」\nMục đích hướng về người khác thường dùng 「ように」","usages":[{"title":"～ために (Danh từ)","meaning":"Để làm gì/Vì cái gì","description":"Diễn đạt mục đích trực tiếp với danh từ","structure":"[Danh từ] + の + ために","examples":[{"ja":"健康のために、毎朝ジョギングしています。","ja_furigana":"健康のために、毎朝ジョギングしています。","vi":"Tôi chạy bộ mỗi sáng để giữ sức khỏe.","note":"健康: けんこう: sức khỏe, 毎朝: まいあさ: mỗi sáng"},{"ja":"健康のために、毎日ジョギングをしています。","ja_furigana":"健康のために、毎日ジョギングをしています。","vi":"Tôi chạy bộ mỗi ngày để giữ gìn sức khỏe.","note":"健康: けんこう: sức khỏe"}]},{"title":"～ために (Động từ)","meaning":"Để làm gì/Vì cái gì","description":"Diễn đạt mục đích trực tiếp với động từ","structure":"[Động từ thể từ điển] + ために","examples":[{"ja":"仕事をするために、東京に引っ越しました。","ja_furigana":"仕事をするために、東京に引っ越しました。","vi":"Tôi đã chuyển đến Tokyo để làm việc."},{"ja":"旅行に行くために、荷物を準備します。","ja_furigana":"旅行に行くために、荷物を準備します。","vi":"Tôi chuẩn bị hành lý để đi du lịch.","note":"旅行: りょこう: du lịch, 荷物: にもつ: hành lý, 準備: じゅんび: chuẩn bị"},{"ja":"映画を見るために、映画館に行きました。","ja_furigana":"映画を見るために、映画館に行きました。","vi":"Tôi đã đi đến rạp chiếu phim để xem phim."},{"ja":"彼は仕事をするために、新しいパソコンを買いました。","ja_furigana":"彼は仕事をするために、新しいパソコンを買いました。","vi":"Anh ấy mua máy tính mới để làm việc.","note":"→ mục đích hướng về bản thân \"anh ấy\""}]},{"title":"～ように","meaning":"Để có thể mà, để mà…","description":"Diễn đạt mục đích gián tiếp, không thuộc kiểm soát trực tiếp","structure":"[Động từ thể từ điển/thể ない/thể khả năng] + ように","examples":[{"ja":"学生が理解できるように、説明をゆっくりしました。","ja_furigana":"学生が理解できるように、説明をゆっくりしました。","vi":"Tôi đã giải thích chậm rãi để học sinh có thể hiểu."},{"ja":"風邪をひかないように、暖かくして寝ます。","ja_furigana":"風邪をひかないように、暖かくして寝ます。","vi":"Tôi giữ ấm khi ngủ để không bị cảm."},{"ja":"試験に合格できるように、毎日勉強しています。","ja_furigana":"試験に合格できるように、毎日勉強しています。","vi":"Tôi học mỗi ngày để có thể đỗ kỳ thi.","note":"試験: しけん: kỳ thi, 合格する: ごうかくする: đỗ, 毎日: まいにち: mỗi ngày, 勉強する: べんきょうする: học"},{"ja":"犬が飲めるように、牛乳を温かくしました。","ja_furigana":"犬が飲めるように、牛乳を温かくしました。","vi":"Tôi làm ấm sữa để chó có thể uống được.","note":"温かい: あたたかい: ấm"},{"ja":"けがをしないように、運動靴を履いた。","ja_furigana":"けがをしないように、運動靴を履いた。","vi":"Tôi đi giày thể thao để không bị thương.","note":"けが: chấn thương, 運動靴: うんどうぐつ: giày thể thao, 履く: はく: đi (giày)"},{"ja":"彼女が料理を習うように、料理教室に通わせています。","ja_furigana":"彼女が料理を習うように、料理教室に通わせています。","vi":"Tôi cho cô ấy tham gia lớp học nấu ăn để cô ấy học nấu ăn.","note":"料理教室: りょうりきょうしつ: lớp học nấu ăn → mục đích hướng về \"cô ấy\""},{"ja":"学生に理解してもらうために、図を描きました。","ja_furigana":"学生に理解してもらうために、図を描きました。","vi":"Tôi đã vẽ sơ đồ để học sinh có thể hiểu.","note":"理解: りかい: hiểu → mục đích hướng về \"tôi\""},{"ja":"日本語が上手に話せるように、毎日練習しています。","ja_furigana":"日本語が上手に話せるように、毎日練習しています。","vi":"Tôi luyện tập mỗi ngày để có thể nói tiếng Nhật giỏi.","note":"練習する: れんしゅうする: luyện tập → thuộc về khả năng"}]}],"examples":[{"ja":"健康のために、毎朝ジョギングしています。","ja_furigana":"健康のために、毎朝ジョギングしています。","vi":"Tôi chạy bộ mỗi sáng để giữ sức khỏe.","note":"健康: けんこう: sức khỏe, 毎朝: まいあさ: mỗi sáng"},{"ja":"健康のために、毎日ジョギングをしています。","ja_furigana":"健康のために、毎日ジョギングをしています。","vi":"Tôi chạy bộ mỗi ngày để giữ gìn sức khỏe.","note":"健康: けんこう: sức khỏe"},{"ja":"仕事をするために、東京に引っ越しました。","ja_furigana":"仕事をするために、東京に引っ越しました。","vi":"Tôi đã chuyển đến Tokyo để làm việc."},{"ja":"旅行に行くために、荷物を準備します。","ja_furigana":"旅行に行くために、荷物を準備します。","vi":"Tôi chuẩn bị hành lý để đi du lịch.","note":"旅行: りょこう: du lịch, 荷物: にもつ: hành lý, 準備: じゅんび: chuẩn bị"},{"ja":"映画を見るために、映画館に行きました。","ja_furigana":"映画を見るために、映画館に行きました。","vi":"Tôi đã đi đến rạp chiếu phim để xem phim."},{"ja":"彼は仕事をするために、新しいパソコンを買いました。","ja_furigana":"彼は仕事をするために、新しいパソコンを買いました。","vi":"Anh ấy mua máy tính mới để làm việc.","note":"→ mục đích hướng về bản thân \"anh ấy\""},{"ja":"学生が理解できるように、説明をゆっくりしました。","ja_furigana":"学生が理解できるように、説明をゆっくりしました。","vi":"Tôi đã giải thích chậm rãi để học sinh có thể hiểu."},{"ja":"風邪をひかないように、暖かくして寝ます。","ja_furigana":"風邪をひかないように、暖かくして寝ます。","vi":"Tôi giữ ấm khi ngủ để không bị cảm."},{"ja":"試験に合格できるように、毎日勉強しています。","ja_furigana":"試験に合格できるように、毎日勉強しています。","vi":"Tôi học mỗi ngày để có thể đỗ kỳ thi.","note":"試験: しけん: kỳ thi, 合格する: ごうかくする: đỗ, 毎日: まいにち: mỗi ngày, 勉強する: べんきょうする: học"},{"ja":"犬が飲めるように、牛乳を温かくしました。","ja_furigana":"犬が飲めるように、牛乳を温かくしました。","vi":"Tôi làm ấm sữa để chó có thể uống được.","note":"温かい: あたたかい: ấm"},{"ja":"けがをしないように、運動靴を履いた。","ja_furigana":"けがをしないように、運動靴を履いた。","vi":"Tôi đi giày thể thao để không bị thương.","note":"けが: chấn thương, 運動靴: うんどうぐつ: giày thể thao, 履く: はく: đi (giày)"},{"ja":"彼女が料理を習うように、料理教室に通わせています。","ja_furigana":"彼女が料理を習うように、料理教室に通わせています。","vi":"Tôi cho cô ấy tham gia lớp học nấu ăn để cô ấy học nấu ăn.","note":"料理教室: りょうりきょうしつ: lớp học nấu ăn → mục đích hướng về \"cô ấy\""},{"ja":"学生に理解してもらうために、図を描きました。","ja_furigana":"学生に理解してもらうために、図を描きました。","vi":"Tôi đã vẽ sơ đồ để học sinh có thể hiểu.","note":"理解: りかい: hiểu → mục đích hướng về \"tôi\""},{"ja":"日本語が上手に話せるように、毎日練習しています。","ja_furigana":"日本語が上手に話せるように、毎日練習しています。","vi":"Tôi luyện tập mỗi ngày để có thể nói tiếng Nhật giỏi.","note":"練習する: れんしゅうする: luyện tập → thuộc về khả năng"}],"structures":[{"Cách dùng":"～ために (Danh từ)","Cấu trúc":"[Danh từ] + の + ために","Nghĩa":"Để làm gì/Vì cái gì"},{"Cách dùng":"～ために (Động từ)","Cấu trúc":"[Động từ thể từ điển] + ために","Nghĩa":"Để làm gì/Vì cái gì"},{"Cách dùng":"～ように","Cấu trúc":"[Động từ thể từ điển/thể ない/thể khả năng] + ように","Nghĩa":"Để có thể mà, để mà…"}],"related":[{"title":"～んです","link":"https://onjlpt.com/ngu-phap/n4/ndesu"},{"title":"～ほうがいいです","link":"https://onjlpt.com/ngu-phap/n4/hou-ga-ii-desu"},{"title":"Động từ thể ý chí","link":"https://onjlpt.com/ngu-phap/n4/doutai-there-y-chi"},{"title":"～ようと思います/ようと思っています","link":"https://onjlpt.com/ngu-phap/n4/you-to-omoimasu-you-to-omotteimasu"}],"description":"Diễn đạt mục đích với sự khác biệt về sắc thái: ～ために cho mục đích trực tiếp, ～ように cho mục đích gián tiếp hoặc không thuộc kiểm soát trực tiếp"}}'),
    ('N3_2022_12', 'GRAMMAR', 2, '{"pattern":"～において","expressions":["において"],"is_answer":true,"link":"https://onjlpt.com/ngu-phap/n3/ni-oi-te","level":"N3","question":{"text":"2) （北山市のホームページで） 7 月 25 日と 26 日の 2 日間、北山公園( )夏祭りが行われました。","options":["1) において","2) にとって","3) に対して","4) について"],"correct":1},"lesson":null}'),
    ('N3_2022_12', 'GRAMMAR', 3, '{"pattern":"～ていく、～てくる","expressions":["のぼっていくと","のぼってくるとき","のぼってくるには"],"is_answer":true,"link":"https://onjlpt.com/ngu-phap/n3/teiku-tekuru","level":"N3","question":{"text":"9) （道で） A「すみません。東図書館を探しているんですが……。」 B 「ああ、東図書館ですね。この坂を( )郵便局がありますから、その角を右に曲がってください。右に曲がってすぐ図書館があります。」","options":["1) のぼっていくと","2) のぼっていきながら","3) のぼってくるには","4) のぼってくるとき"],"correct":1},"lesson":null}'),
    ('N3_2022_12', 'GRAMMAR', 4, '{"pattern":"～かける/～かけの/～かけだ","expressions":["出かけるところだから","出かけるところなのに"],"is_answer":true,"link":"https://onjlpt.com/ngu-phap/n3/kakeru-kakeno-kakeda","level":"N3","question":{"text":"8) （電話で） 中川「もしもし。林さん、今ちょっといい？J 林「あ、ごめん。これから( )、あとでこっちから電話するね。」","options":["1) 出かけるところなのに","2) 出かけているところなのに","3) 出かけるところだから","4) 出かけているところだから"],"correct":3},"lesson":null}'),
    ('N3_2022_12', 'GRAMMAR', 5, '{"pattern":"～ことだ/～ことはない","expressions":["行ったことはない"],"is_answer":true,"link":"https://onjlpt.com/ngu-phap/n3/koto-da-koto-wa-nai","level":"N3","question":{"text":"12) 私は美術館が好きで、今までいろいろな美術館に行った。国内の美術館が多いが、海外の美術館に( )。","options":["1) 行ったこともある","2) 行ったことはない","3) 行くこともできる","4) 行くこともできない"],"correct":2},"lesson":null}'),
    ('N3_2022_12', 'GRAMMAR', 6, '{"pattern":"～ので、～から","expressions":["から"],"is_answer":false,"link":"https://onjlpt.com/ngu-phap/n5/node-kara","level":"N5","question":{"text":"14) 留学している息子___ ___ _★_ ___ 毎日楽しく過ごしていると書かれていて安心した。","options":["1) メール","2) から","3) に","4) の"],"correct":1},"lesson":{"pattern":"～ので、～から","name":"Vì/Bởi vì... nên...","meaning":"Diễn đạt nguyên nhân \"vì/bởi vì... nên...\", trong đó ので mang tính khách quan còn から thể hiện cảm xúc, thái độ người nói","note":"Quy tắc sử dụng:\nので: Mang tính khách quan, trang trọng, dùng cho sự việc đơn thuần\nから: Mang tính chủ quan, thể hiện cảm xúc, thái độ, dùng với mệnh lệnh, yêu cầu, nhờ vả\nんで: Cách nói thông tục của ので, dùng trong hội thoại\nからです: Dùng để trả lời câu hỏi どうして～か (tại sao?)\nLưu ý: ので thường đi với thể thường hoặc thể ます, còn から có thể đi với nhiều hình thức hơn bao gồm cả だ/です với danh từ và tính từ-na.","usages":[{"title":"～ので (khách quan)","meaning":"Vì/Bởi vì... nên...","description":"Diễn đạt nguyên nhân một cách khách quan, trang trọng, thường dùng cho sự việc đơn thuần","structure":"[Động từ/Tính từ/Danh từ] + ので","examples":[{"ja":"あめがふっているので、うちにいます。","ja_furigana":"あめがふっているので、うちにいます。","vi":"Vì trời mưa nên tôi ở nhà."},{"ja":"あめがふっているのでさんぽしません。","ja_furigana":"あめがふっているのでさんぽしません。","vi":"Vì trời đang mưa nên tôi không đi dạo."},{"ja":"このほんはおもしろいのでぜんぶよみました。","ja_furigana":"このほんはおもしろいのでぜんぶよみました。","vi":"Vì cuốn sách này thú vị nên tôi đã đọc hết.","note":"おもしろい: thú vị"},{"ja":"おなかがすいたのでごはんをたべましょう。","ja_furigana":"おなかがすいたのでごはんをたべましょう。","vi":"Vì đói bụng nên chúng ta hãy ăn cơm."},{"ja":"かのじょはせんせいですのでまいにちいそがしいです。","ja_furigana":"かのじょはせんせいですのでまいにちいそがしいです。","vi":"Cô ấy là giáo viên nên ngày nào cũng bận rộn.","note":"せんせい: giáo viên, まいにち: hàng ngày, いそがしい: bận"}]},{"title":"～から (chủ quan)","meaning":"Vì/Bởi vì... nên...","description":"Diễn đạt nguyên nhân mang tính chủ quan, thể hiện cảm xúc, thái độ người nói, dùng với mệnh lệnh, yêu cầu","structure":"[Động từ/Tính từ/Danh từ] + から","examples":[{"ja":"ねつがさがったから、がっこうにいきます。","ja_furigana":"ねつがさがったから、がっこうにいきます。","vi":"Vì đã hạ sốt nên tôi sẽ đi học."},{"ja":"きょうはあめがふるから、うちにいます。","ja_furigana":"きょうはあめがふるから、うちにいます。","vi":"Hôm nay trời mưa nên tôi ở nhà."},{"ja":"おなかがすいたから、ごはんをたべます。","ja_furigana":"おなかがすいたから、ごはんをたべます。","vi":"Tôi đói bụng nên tôi sẽ ăn cơm."},{"ja":"あめがふっているから、かさをもっていってください。","ja_furigana":"あめがふっているから、かさをもっていってください。","vi":"Vì trời đang mưa nên hãy mang theo ô."},{"ja":"かれはゆうめいだから、いつもいそがしいです。","ja_furigana":"かれはゆうめいだから、いつもいそがしいです。","vi":"Anh ấy nổi tiếng nên lúc nào cũng bận rộn.","note":"有名: ゆうめい: nổi tiếng"},{"ja":"あたまがいたいですから, しゅくだいをやすんでもいいですか。","ja_furigana":"あたまがいたいですから, しゅくだいをやすんでもいいですか。","vi":"Vì bị đau đầu nên em có thể không làm bài tập được không ạ?","note":"Dùng với yêu cầu, nhờ vả"}]},{"title":"～んで (thông tục)","meaning":"Vì/Bởi vì... nên...","description":"Cách nói thông thường, ít trang trọng của ので, thường dùng trong hội thoại","structure":"[Thể thường] + んで","examples":[{"ja":"あたまがいたいんで、うちでやすみます。","ja_furigana":"あたまがいたいんで、うちでやすみます。","vi":"Vì đau đầu nên tôi ở nhà nghỉ ngơi.","note":"Cách nói thông tục của ので"},{"ja":"今日は雨なんで、うちにいます。","ja_furigana":"今日は雨なんで、うちにいます。","vi":"Hôm nay trời mưa nên tôi ở nhà.","note":"Cách nói thông tục của ので"}]},{"title":"～からです (trả lời)","meaning":"Vì...","description":"Dùng để trả lời cho câu hỏi どうして～か (tại sao?)","structure":"[Lý do] + からです","examples":[{"ja":"ともだちが言ったからです。","ja_furigana":"ともだちが言ったからです。","vi":"Vì bạn tôi đã nói.","note":"Trả lời cho どうして"},{"ja":"かぜをひいたからです。","ja_furigana":"かぜをひいたからです。","vi":"Vì tớ bị cảm.","note":"Trả lời cho どうして"}]}],"examples":[{"ja":"あめがふっているので、うちにいます。","ja_furigana":"あめがふっているので、うちにいます。","vi":"Vì trời mưa nên tôi ở nhà."},{"ja":"あめがふっているのでさんぽしません。","ja_furigana":"あめがふっているのでさんぽしません。","vi":"Vì trời đang mưa nên tôi không đi dạo."},{"ja":"このほんはおもしろいのでぜんぶよみました。","ja_furigana":"このほんはおもしろいのでぜんぶよみました。","vi":"Vì cuốn sách này thú vị nên tôi đã đọc hết.","note":"おもしろい: thú vị"},{"ja":"おなかがすいたのでごはんをたべましょう。","ja_furigana":"おなかがすいたのでごはんをたべましょう。","vi":"Vì đói bụng nên chúng ta hãy ăn cơm."},{"ja":"かのじょはせんせいですのでまいにちいそがしいです。","ja_furigana":"かのじょはせんせいですのでまいにちいそがしいです。","vi":"Cô ấy là giáo viên nên ngày nào cũng bận rộn.","note":"せんせい: giáo viên, まいにち: hàng ngày, いそがしい: bận"},{"ja":"ねつがさがったから、がっこうにいきます。","ja_furigana":"ねつがさがったから、がっこうにいきます。","vi":"Vì đã hạ sốt nên tôi sẽ đi học."},{"ja":"きょうはあめがふるから、うちにいます。","ja_furigana":"きょうはあめがふるから、うちにいます。","vi":"Hôm nay trời mưa nên tôi ở nhà."},{"ja":"おなかがすいたから、ごはんをたべます。","ja_furigana":"おなかがすいたから、ごはんをたべます。","vi":"Tôi đói bụng nên tôi sẽ ăn cơm."},{"ja":"あめがふっているから、かさをもっていってください。","ja_furigana":"あめがふっているから、かさをもっていってください。","vi":"Vì trời đang mưa nên hãy mang theo ô."},{"ja":"かれはゆうめいだから、いつもいそがしいです。","ja_furigana":"かれはゆうめいだから、いつもいそがしいです。","vi":"Anh ấy nổi tiếng nên lúc nào cũng bận rộn.","note":"有名: ゆうめい: nổi tiếng"},{"ja":"あたまがいたいですから, しゅくだいをやすんでもいいですか。","ja_furigana":"あたまがいたいですから, しゅくだいをやすんでもいいですか。","vi":"Vì bị đau đầu nên em có thể không làm bài tập được không ạ?","note":"Dùng với yêu cầu, nhờ vả"},{"ja":"あたまがいたいんで、うちでやすみます。","ja_furigana":"あたまがいたいんで、うちでやすみます。","vi":"Vì đau đầu nên tôi ở nhà nghỉ ngơi.","note":"Cách nói thông tục của ので"},{"ja":"今日は雨なんで、うちにいます。","ja_furigana":"今日は雨なんで、うちにいます。","vi":"Hôm nay trời mưa nên tôi ở nhà.","note":"Cách nói thông tục của ので"},{"ja":"ともだちが言ったからです。","ja_furigana":"ともだちが言ったからです。","vi":"Vì bạn tôi đã nói.","note":"Trả lời cho どうして"},{"ja":"かぜをひいたからです。","ja_furigana":"かぜをひいたからです。","vi":"Vì tớ bị cảm.","note":"Trả lời cho どうして"}],"structures":[{"Cách dùng":"～ので (khách quan)","Cấu trúc":"[Động từ/Tính từ/Danh từ] + ので","Nghĩa":"Vì/Bởi vì... nên..."},{"Cách dùng":"～から (chủ quan)","Cấu trúc":"[Động từ/Tính từ/Danh từ] + から","Nghĩa":"Vì/Bởi vì... nên..."},{"Cách dùng":"～んで (thông tục)","Cấu trúc":"[Thể thường] + んで","Nghĩa":"Vì/Bởi vì... nên..."},{"Cách dùng":"～からです (trả lời)","Cấu trúc":"[Lý do] + からです","Nghĩa":"Vì..."}],"related":[{"title":"Các cấu trúc sử dụng thể て","link":"https://onjlpt.com/ngu-phap/n5/cac-cau-truc-su-dung-the-te"},{"title":"～たことがある","link":"https://onjlpt.com/ngu-phap/n5/ta-koto-ga-aru"},{"title":"あげます・もらいます・くれます","link":"https://onjlpt.com/ngu-phap/n5/agemasu-moraimasu-kuremasu"},{"title":"～があります・～がいます","link":"https://onjlpt.com/ngu-phap/n5/aru-iru"}],"description":"Diễn đạt nguyên nhân \"vì/bởi vì... nên...\", trong đó ので mang tính khách quan còn から thể hiện cảm xúc, thái độ người nói"}}'),
    ('N3_2022_12', 'GRAMMAR', 7, '{"pattern":"～について","expressions":["について"],"is_answer":false,"link":"https://onjlpt.com/ngu-phap/n3/ni-tsuite","level":"N3","question":{"text":"2) （北山市のホームページで） 7 月 25 日と 26 日の 2 日間、北山公園( )夏祭りが行われました。","options":["1) において","2) にとって","3) に対して","4) について"],"correct":1},"lesson":null}'),
    ('N3_2022_12', 'GRAMMAR', 8, '{"pattern":"～にとって","expressions":["にとって"],"is_answer":false,"link":"https://onjlpt.com/ngu-phap/n3/ni-totte","level":"N3","question":{"text":"2) （北山市のホームページで） 7 月 25 日と 26 日の 2 日間、北山公園( )夏祭りが行われました。","options":["1) において","2) にとって","3) に対して","4) について"],"correct":1},"lesson":null}'),
    ('N3_2022_12', 'GRAMMAR', 9, '{"pattern":"～に対して","expressions":["に対して"],"is_answer":false,"link":"https://onjlpt.com/ngu-phap/n3/ni-taishite","level":"N3","question":{"text":"2) （北山市のホームページで） 7 月 25 日と 26 日の 2 日間、北山公園( )夏祭りが行われました。","options":["1) において","2) にとって","3) に対して","4) について"],"correct":1},"lesson":null}'),
    ('N3_2022_12', 'GRAMMAR', 10, '{"pattern":"～ながら","expressions":["のぼっていきながら"],"is_answer":false,"link":"https://onjlpt.com/ngu-phap/n4/nagara","level":"N4","question":{"text":"9) （道で） A「すみません。東図書館を探しているんですが……。」 B 「ああ、東図書館ですね。この坂を( )郵便局がありますから、その角を右に曲がってください。右に曲がってすぐ図書館があります。」","options":["1) のぼっていくと","2) のぼっていきながら","3) のぼってくるには","4) のぼってくるとき"],"correct":1},"lesson":{"pattern":"～ながら","name":"Ôn JLPTChào mừng ngày 30/4 - Tự hào Việt Nam – Một lần ngoảnh lại, vạn niềm kiêu hãnh!","meaning":"Diễn tả một hành động diễn ra cùng lúc với một hành động khác","note":"Ý nghĩa: Mẫu câu này diễn tả một hành động diễn ra cùng lúc với một hành động khác. Hành động được miêu tả ở vế 「～ながら」đứng trước, hành động ở vế sau là hành động chính.\nCấu trúc: [Động từ thể ます (bỏ ます)] + ながら\nVí dụ: 書く（かく）→ 書きます → 書きながら、話す（はなす）→ 話します → 話しながら、食べる（たべる）→ 食べます → 食べながら、する → します → しながら","usages":[{"title":"Hai hành động đồng thời","meaning":"Ôn JLPTChào mừng ngày 30/4 - Tự hào Việt Nam – Một lần ngoảnh lại, vạn niềm kiêu hãnh!","description":"Follow Onjlpt Luyện tập N3N2N1 Luyện đề N5N4N3N2N1 Kanji N3N2 Từ vựng Từ vựng đề thi214 Bộ thủHiraganaKatakana Ngữ pháp N5N4N3N2N1 Video HomeGóp ý Furigana Chưa thuộc ～ながら Diễn tả một hành động diễn ra cùng lúc với một hành động khác Các cách sử dụng Hai hành động đồng thời Diễn tả hai hành động xảy ra đồng thời Hành động ở vế 「～ながら」là hành động phụ, hành động ở vế sau là hành động chính","structure":"[Động từ thể ます (bỏ ます)] + ながら","examples":[{"ja":"音楽を聞きながら、宿題をします。","ja_furigana":"音楽を聞きながら、宿題をします。","vi":"Tôi nghe nhạc trong khi làm bài tập.","note":"Làm bài tập là hành động chính"},{"ja":"テレビを見ながら、ご飯を食べています。","ja_furigana":"テレビを見ながら、ご飯を食べています。","vi":"Tôi xem tivi trong khi đang ăn cơm","note":"Ăn cơm là hành động chính"},{"ja":"音楽を聞きながら、料理をするのが好きです。","ja_furigana":"音楽を聞きながら、料理をするのが好きです。","vi":"Tôi thích nấu ăn trong khi nghe nhạc.","note":"Nấu ăn là hành động chính"},{"ja":"彼女(かのじょ)は音楽(おんがく)を聴(き)きながら、料理(りょうり)をしています。","ja_furigana":"彼女(かのじょ)は音楽(おんがく)を聴(き)きながら、料理(りょうり)をしています。","vi":"Cô ấy nghe nhạc trong khi nấu ăn.","note":"Nấu ăn là hành động chính"},{"ja":"音楽(おんがく) を聞(き)きながら、宿題(しゅくだい) をします。","ja_furigana":"音楽(おんがく) を聞(き)きながら、宿題(しゅくだい) をします。","vi":"Tôi vừa nghe nhạc vừa làm bài tập về nhà."}]}],"examples":[{"ja":"音楽を聞きながら、宿題をします。","ja_furigana":"音楽を聞きながら、宿題をします。","vi":"Tôi nghe nhạc trong khi làm bài tập.","note":"Làm bài tập là hành động chính"},{"ja":"テレビを見ながら、ご飯を食べています。","ja_furigana":"テレビを見ながら、ご飯を食べています。","vi":"Tôi xem tivi trong khi đang ăn cơm","note":"Ăn cơm là hành động chính"},{"ja":"音楽を聞きながら、料理をするのが好きです。","ja_furigana":"音楽を聞きながら、料理をするのが好きです。","vi":"Tôi thích nấu ăn trong khi nghe nhạc.","note":"Nấu ăn là hành động chính"},{"ja":"彼女(かのじょ)は音楽(おんがく)を聴(き)きながら、料理(りょうり)をしています。","ja_furigana":"彼女(かのじょ)は音楽(おんがく)を聴(き)きながら、料理(りょうり)をしています。","vi":"Cô ấy nghe nhạc trong khi nấu ăn.","note":"Nấu ăn là hành động chính"},{"ja":"音楽(おんがく) を聞(き)きながら、宿題(しゅくだい) をします。","ja_furigana":"音楽(おんがく) を聞(き)きながら、宿題(しゅくだい) をします。","vi":"Tôi vừa nghe nhạc vừa làm bài tập về nhà."}],"structures":[{"Cách dùng":"Hai hành động đồng thời","Cấu trúc":"[Động từ thể ます (bỏ ます)] + ながら","Nghĩa":"Ôn JLPTChào mừng ngày 30/4 - Tự hào Việt Nam – Một lần ngoảnh lại, vạn niềm kiêu hãnh!"}],"related":[{"title":"～んです","link":"https://onjlpt.com/ngu-phap/n4/ndesu"},{"title":"～ほうがいいです","link":"https://onjlpt.com/ngu-phap/n4/hou-ga-ii-desu"},{"title":"Động từ thể ý chí","link":"https://onjlpt.com/ngu-phap/n4/doutai-there-y-chi"},{"title":"～ようと思います/ようと思っています","link":"https://onjlpt.com/ngu-phap/n4/you-to-omoimasu-you-to-omotteimasu"}],"description":"Diễn tả một hành động diễn ra cùng lúc với một hành động khác"}}'),
    ('N3_2022_12', 'GRAMMAR', 11, '{"pattern":"～ように、～ような","expressions":["ように","弾けるようになりたくて"],"is_answer":false,"link":"https://onjlpt.com/ngu-phap/n3/you-ni-you-na","level":"N3","question":{"text":"6) 私の応援している野球選手が、肩のけがの( )、しばらく試合に出られなくなった。とても心配だ。","options":["1) 途中で","2) 一方で","3) ように","4) ために"],"correct":4},"lesson":null}'),
    ('N3_2022_12', 'GRAMMAR', 12, '{"pattern":"～んです","expressions":["履かないんですか"],"is_answer":false,"link":"https://onjlpt.com/ngu-phap/n4/ndesu","level":"N4","question":{"text":"13) （靴屋で） 客「すみません。この靴、( )。」 店員「どうぞ。サイズはこちらでよろしいですか。」 客「はい。」","options":["1) 履いてもらえませんか","2) 履かないんですか","3) 履いてみてもいいですか","4) 履くことになりますか"],"correct":3},"lesson":{"pattern":"～んです","name":"Thể hiện sự quan tâm đến người đối diện, muốn hỏi thêm thông tin hoặc cần lời giải thích","meaning":"Dùng để giải thích, hỏi nguyên nhân lý do hoặc thể hiện sự quan tâm, muốn biết thêm thông tin.","note":"Lưu ý: Mẫu câu 「～んです」chủ yếu được dùng để giải thích hoặc đưa ra nguyên nhân cho sự việc gì đó. Khi dùng dưới dạng câu hỏi thì ngụ ý quan tâm, hoặc có nhu cầu biết thêm thông tin từ người đối diện. Vì vậy không dùng mẫu câu này để hỏi những người không liên quan hoặc không có trách nhiệm phải biết lý do hay nguyên nhân đó.\nVí dụ cách dùng không phù hợp: （ｘ）A: せんせい、マイクさんはまだこないんですか。(Thưa cô, bạn Mike vẫn chưa đến ạ?)\nThay vào đó nên dùng: A: せんせい、マイクさんはまだきていませんか。\nCấu trúc: [Thể thường (普通形)] + んです。(「～だ」→ なんです)\nVí dụ: いく → いくんです、あった → あったんです、こない → こないんです。すきだ → すきなんです、がくせいだ → がくせいなんです、あつい → あついんです。","usages":[{"title":"Thể hiện sự quan tâm, muốn hỏi thêm thông tin","meaning":"Thể hiện sự quan tâm đến người đối diện, muốn hỏi thêm thông tin hoặc cần lời giải thích","description":"Dùng để hỏi thêm thông tin một cách lịch sự, thể hiện sự quan tâm thực sự.","structure":"[Thể thường (普通形)] + んです","examples":[{"ja":"どこでしらべたんですか。","ja_furigana":"どこでしらべたんですか。","vi":"Bạn đã tra cứu ở đâu thế?"},{"ja":"どこで買ったんですか。","ja_furigana":"どこで買ったんですか。","vi":"Cậu đã mua ở đâu vậy?"},{"ja":"えいごがぺらぺらですね。アメリカにすんでいたことがあるんですか。","ja_furigana":"えいごがぺらぺらですね。アメリカにすんでいたことがあるんですか。","vi":"Cậu nói tiếng Anh trôi chảy quá. Cậu đã từng sống ở Mỹ chưa?"},{"ja":"あれ？どうして日本に行ったんですか？","ja_furigana":"あれ？どうして日本に行ったんですか？","vi":"Ơ? Tại sao bạn lại đến Nhật vậy?"}]},{"title":"Hỏi và trả lời về nguyên nhân, lý do","meaning":"Đặt câu hỏi về nguyên nhân, lý do của việc gì đó & trả lời cho câu hỏi đó","description":"Dùng để hỏi lý do hoặc giải thích nguyên nhân cho một sự việc.","structure":"[Thể thường (普通形)] + んです","examples":[{"ja":"どこに行くんですか。","ja_furigana":"どこに行くんですか。","vi":"Bạn đi đâu thế?"},{"ja":"のどがかわいたんです。","ja_furigana":"のどがかわいたんです。","vi":"Tôi bị khát nước."},{"ja":"どうしてねこがにげたんですか。","ja_furigana":"どうしてねこがにげたんですか。","vi":"Tại sao con mèo chạy mất vậy?","note":"にげる: chạy mất"},{"ja":"友達がずっと来なかったんです。","ja_furigana":"友達がずっと来なかったんです。","vi":"Tại bạn mãi không đến.","note":"ずっと～ない: mãi không …"}]},{"title":"Bổ sung, giải thích thêm thông tin","meaning":"Bổ sung, giải thích thêm cho thông tin mình đưa ra","description":"Dùng để cung cấp thêm thông tin giải thích cho câu nói trước đó.","structure":"[Thể thường (普通形)] + んです","examples":[{"ja":"きのう、かれはしごとをやすみました。かぜをひいたんです。","ja_furigana":"きのう、かれはしごとをやすみました。かぜをひいたんです。","vi":"Hôm qua anh ấy nghỉ làm. (Vì) anh ấy bị cảm.","note":"かぜをひく: bị cảm"},{"ja":"おなかがいたいんです。くすりをのんでもいいですか。","ja_furigana":"おなかがいたいんです。くすりをのんでもいいですか。","vi":"Bụng em đau quá. Em có thể uống thuốc được không?"},{"ja":"ええ、いぬが 2ひきもいるんですか。","ja_furigana":"ええ、いぬが 2ひきもいるんですか。","vi":"Oa, bạn có tới 2 con chó cơ à?"},{"ja":"そうです。ちょっと疲れているんです。","ja_furigana":"そうです。ちょっと疲れているんです。","vi":"Ừ, tại tớ hơi mệt mà."}]},{"title":"Mở đầu câu chuyện","meaning":"Mở đầu câu chuyện, thu hút sự chú ý của người đối diện trước khi vào chủ đề chính","description":"Dùng như một cách mở đầu câu chuyện một cách lịch sự.","structure":"[Thể thường (普通形)] + んです","examples":[{"ja":"ちょっと、聞きたいことがあるんですが。","ja_furigana":"ちょっと、聞きたいことがあるんですが。","vi":"Này, tôi có điều muốn hỏi."}]}],"examples":[{"ja":"どこでしらべたんですか。","ja_furigana":"どこでしらべたんですか。","vi":"Bạn đã tra cứu ở đâu thế?"},{"ja":"どこで買ったんですか。","ja_furigana":"どこで買ったんですか。","vi":"Cậu đã mua ở đâu vậy?"},{"ja":"えいごがぺらぺらですね。アメリカにすんでいたことがあるんですか。","ja_furigana":"えいごがぺらぺらですね。アメリカにすんでいたことがあるんですか。","vi":"Cậu nói tiếng Anh trôi chảy quá. Cậu đã từng sống ở Mỹ chưa?"},{"ja":"あれ？どうして日本に行ったんですか？","ja_furigana":"あれ？どうして日本に行ったんですか？","vi":"Ơ? Tại sao bạn lại đến Nhật vậy?"},{"ja":"どこに行くんですか。","ja_furigana":"どこに行くんですか。","vi":"Bạn đi đâu thế?"},{"ja":"のどがかわいたんです。","ja_furigana":"のどがかわいたんです。","vi":"Tôi bị khát nước."},{"ja":"どうしてねこがにげたんですか。","ja_furigana":"どうしてねこがにげたんですか。","vi":"Tại sao con mèo chạy mất vậy?","note":"にげる: chạy mất"},{"ja":"友達がずっと来なかったんです。","ja_furigana":"友達がずっと来なかったんです。","vi":"Tại bạn mãi không đến.","note":"ずっと～ない: mãi không …"},{"ja":"きのう、かれはしごとをやすみました。かぜをひいたんです。","ja_furigana":"きのう、かれはしごとをやすみました。かぜをひいたんです。","vi":"Hôm qua anh ấy nghỉ làm. (Vì) anh ấy bị cảm.","note":"かぜをひく: bị cảm"},{"ja":"おなかがいたいんです。くすりをのんでもいいですか。","ja_furigana":"おなかがいたいんです。くすりをのんでもいいですか。","vi":"Bụng em đau quá. Em có thể uống thuốc được không?"},{"ja":"ええ、いぬが 2ひきもいるんですか。","ja_furigana":"ええ、いぬが 2ひきもいるんですか。","vi":"Oa, bạn có tới 2 con chó cơ à?"},{"ja":"そうです。ちょっと疲れているんです。","ja_furigana":"そうです。ちょっと疲れているんです。","vi":"Ừ, tại tớ hơi mệt mà."},{"ja":"ちょっと、聞きたいことがあるんですが。","ja_furigana":"ちょっと、聞きたいことがあるんですが。","vi":"Này, tôi có điều muốn hỏi."}],"structures":[{"Cách dùng":"Thể hiện sự quan tâm, muốn hỏi thêm thông tin","Cấu trúc":"[Thể thường (普通形)] + んです","Nghĩa":"Thể hiện sự quan tâm đến người đối diện, muốn hỏi thêm thông tin hoặc cần lời giải thích"},{"Cách dùng":"Hỏi và trả lời về nguyên nhân, lý do","Cấu trúc":"[Thể thường (普通形)] + んです","Nghĩa":"Đặt câu hỏi về nguyên nhân, lý do của việc gì đó & trả lời cho câu hỏi đó"},{"Cách dùng":"Bổ sung, giải thích thêm thông tin","Cấu trúc":"[Thể thường (普通形)] + んです","Nghĩa":"Bổ sung, giải thích thêm cho thông tin mình đưa ra"},{"Cách dùng":"Mở đầu câu chuyện","Cấu trúc":"[Thể thường (普通形)] + んです","Nghĩa":"Mở đầu câu chuyện, thu hút sự chú ý của người đối diện trước khi vào chủ đề chính"}],"related":[{"title":"～ほうがいいです","link":"https://onjlpt.com/ngu-phap/n4/hou-ga-ii-desu"},{"title":"Động từ thể ý chí","link":"https://onjlpt.com/ngu-phap/n4/doutai-there-y-chi"},{"title":"～ようと思います/ようと思っています","link":"https://onjlpt.com/ngu-phap/n4/you-to-omoimasu-you-to-omotteimasu"},{"title":"～つもりです","link":"https://onjlpt.com/ngu-phap/n4/tsumori-desu"}],"description":"Dùng để giải thích, hỏi nguyên nhân lý do hoặc thể hiện sự quan tâm, muốn biết thêm thông tin."}}');
INSERT INTO tmp_jlpt_study_item (exam_code, item_kind, sort_order, payload) VALUES
    ('N3_2022_12', 'GRAMMAR', 13, '{"pattern":"～ないで、～なくて、～ず、～ずに","expressions":["磨かなくて"],"is_answer":false,"link":"https://onjlpt.com/ngu-phap/n3/naide-nakute-zu-zuni","level":"N3","question":{"text":"7) 歯医者「歯を( )寝てしまうと、虫歯になりやすくなります。寝る前にきちんと磨くようにしてください。」","options":["1) 磨いて","2) 磨かずに","3) 磨くたび","4) 磨かなくて"],"correct":2},"lesson":null}'),
    ('N3_2022_12', 'GRAMMAR', 14, '{"pattern":"～ことがある/こともある","expressions":["行ったこともある"],"is_answer":false,"link":"https://onjlpt.com/ngu-phap/n3/koto-ga-aru","level":"N3","question":{"text":"12) 私は美術館が好きで、今までいろいろな美術館に行った。国内の美術館が多いが、海外の美術館に( )。","options":["1) 行ったこともある","2) 行ったことはない","3) 行くこともできる","4) 行くこともできない"],"correct":2},"lesson":null}');
INSERT INTO tmp_jlpt_study_item (exam_code, item_kind, sort_order, payload) VALUES
    ('N3_2023_07', 'VOCABULARY', 1, '{"word":"あくび","reading":"あくび","meaning_vi":"ngáp","han_viet":"","tested":true,"question_type":"context","examples":[{"ja":"ゆうべはほとんど寝ていないので、今日は眠くて何度もあくびが出てしまう。","ja_furigana":"ゆうべはほとんど寝ていないので、今日は眠くて何度もあくびが出てしまう。","vi":"Tối qua tôi hầu như không ngủ, nên hôm nay buồn ngủ và cứ ngáp mãi.","source":"exam"}]}'),
    ('N3_2023_07', 'VOCABULARY', 2, '{"word":"うっかり","reading":"うっかり","meaning_vi":"vô ý; sơ ý","han_viet":"","tested":true,"question_type":"context","examples":[{"ja":"うっかりして、鍵をかけないで家を出てしまった。","ja_furigana":"うっかりして、鍵をかけないで家を出てしまった。","vi":"Tôi đã sơ ý ra khỏi nhà mà quên khóa cửa.","source":"exam"}]}'),
    ('N3_2023_07', 'VOCABULARY', 3, '{"word":"どなる","reading":"どなる","meaning_vi":"quát tháo","han_viet":"","tested":true,"question_type":"paraphrase","examples":[{"ja":"そんなにどならないでください。","ja_furigana":"そんなにどならないでください。","vi":"Xin đừng quát lớn như vậy.","source":"exam"}]}'),
    ('N3_2023_07', 'VOCABULARY', 4, '{"word":"にこにこ","reading":"にこにこ","meaning_vi":"mỉm cười thân thiện","han_viet":"","tested":true,"question_type":"usage","examples":[{"ja":"遊んでいる私たちを見て、祖母はうれしそうににこにこしていた。","ja_furigana":"遊んでいる私たちを見て、祖母はうれしそうににこにこしていた。","vi":"Nhìn chúng tôi đang chơi, bà tôi mỉm cười rất vui vẻ.","source":"exam"}]}'),
    ('N3_2023_07', 'VOCABULARY', 5, '{"word":"めんどうくさい","reading":"めんどうくさい","meaning_vi":"phiền phức","han_viet":"","tested":true,"question_type":"context","examples":[{"ja":"仕事で疲れているときは、夕飯を作るのがめんどうくさいので、外食することが多い。","ja_furigana":"仕事で疲れているときは、夕飯を作るのがめんどうくさいので、外食することが多い。","vi":"Khi mệt vì công việc, tôi thấy nấu bữa tối rất phiền nên thường ăn ngoài.","source":"exam"}]}'),
    ('N3_2023_07', 'VOCABULARY', 6, '{"word":"よい","reading":"よい","meaning_vi":"tốt","han_viet":"","tested":true,"question_type":"paraphrase","examples":[{"ja":"この公園はとても良い。","ja_furigana":"この公園はとても良い。","vi":"Công viên này rất đẹp.","source":"dictionary"}]}'),
    ('N3_2023_07', 'VOCABULARY', 7, '{"word":"サイズ","reading":"サイズ","meaning_vi":"kích cỡ","han_viet":"","tested":true,"question_type":"paraphrase","examples":[{"ja":"その部屋にある家具のサイズを聞いてきてください。","ja_furigana":"その部屋にある家具のサイズを聞いてきてください。","vi":"Hãy hỏi kích thước của đồ nội thất trong căn phòng đó.","source":"exam"}]}'),
    ('N3_2023_07', 'VOCABULARY', 8, '{"word":"テーマ","reading":"テーマ","meaning_vi":"chủ đề","han_viet":"","tested":true,"question_type":"context","examples":[{"ja":"「私の国の社会問題」というテーマで、レポートを書くことになった。","ja_furigana":"「私の国の社会問題」というテーマで、レポートを書くことになった。","vi":"Tôi đã được giao viết báo cáo với chủ đề “Vấn đề xã hội ở nước tôi”.","source":"exam"}]}'),
    ('N3_2023_07', 'VOCABULARY', 9, '{"word":"交流","reading":"こうりゅう","meaning_vi":"giao lưu","han_viet":"GIAO LƯU","tested":true,"question_type":"usage","examples":[{"ja":"息子の学校は、海外の人たちと交流する機会が多いようだ。","ja_furigana":"息子の学校は、海外の人たちと交流する機会が多いようだ。","vi":"Trường của con trai tôi dường như có nhiều cơ hội giao lưu với người nước ngoài.","source":"exam"}]}'),
    ('N3_2023_07', 'VOCABULARY', 10, '{"word":"付き合う","reading":"つきあう","meaning_vi":"giao du với; đi chơi với; hẹn hò với","han_viet":"","tested":true,"question_type":"context","examples":[{"ja":"夫とは、3年間付き合ってから結婚しました。","ja_furigana":"夫とは、3年間付き合ってから結婚しました。","vi":"Tôi đã kết hôn sau khi hẹn hò với chồng 3 năm.","source":"exam"}]}'),
    ('N3_2023_07', 'VOCABULARY', 11, '{"word":"制服","reading":"せいふく","meaning_vi":"đồng phục","han_viet":"CHẾ PHỤC","tested":true,"question_type":"orthography","examples":[{"ja":"私の学校は制服がありません。","ja_furigana":"私の学校は制服がありません。","vi":"Trường tôi không có đồng phục.","source":"exam"}]}'),
    ('N3_2023_07', 'VOCABULARY', 12, '{"word":"動作","reading":"どうさ","meaning_vi":"cử động; động tác","han_viet":"ĐỘNG TÁC","tested":true,"question_type":"context","examples":[{"ja":"私のパソコンは古いので、動作が遅いです。","ja_furigana":"私のパソコンは古いので、動作が遅いです。","vi":"Máy tính của tôi cũ nên chạy chậm.","source":"exam"}]}'),
    ('N3_2023_07', 'VOCABULARY', 13, '{"word":"可能","reading":"かのう","meaning_vi":"có thể","han_viet":"KHẢ NĂNG","tested":true,"question_type":"context","examples":[{"ja":"まだ空席が少しあるので、今なら予約は可能です。","ja_furigana":"まだ空席が少しあるので、今なら予約は可能です。","vi":"Vẫn còn một ít chỗ trống nên bây giờ vẫn có thể đặt chỗ.","source":"exam"}]}'),
