    ('N3_2023_12', 'VOCABULARY', 82, '{"word":"自動的","reading":"じどうてき","meaning_vi":"tự động","han_viet":"TỰ ĐỘNG ĐÍCH","tested":false,"question_type":"context","examples":[{"ja":"この機械は自動的に止まる。","ja_furigana":"この機械は自動的に止まる。","vi":"Cái máy này tự động dừng lại.","source":"dictionary"}]}'),
