    ('N3_2024_12', 'VOCABULARY', 1, '{"word":"よく","reading":"よく","meaning_vi":"ham muốn","han_viet":"","tested":true,"question_type":"paraphrase","examples":[{"ja":"彼の欲は尽きない。","ja_furigana":"彼の欲は尽きない。","vi":"Lòng ham muốn của anh ấy không bao giờ dứt.","source":"dictionary"}]}'),
    ('N3_2024_12', 'VOCABULARY', 2, '{"word":"あせ","reading":"あせ","meaning_vi":"mồ hôi","han_viet":"","tested":true,"question_type":"context","examples":[{"ja":"今日は暑かったので、シャツがあせでぬれてしまった。","ja_furigana":"今日は暑かったので、シャツがあせでぬれてしまった。","vi":"Hôm nay trời nóng nên áo sơ mi đã bị ướt đẫm mồ hôi.","source":"exam"}]}'),
    ('N3_2024_12', 'VOCABULARY', 3, '{"word":"あやしい","reading":"あやしい","meaning_vi":"đáng ngờ","han_viet":"","tested":true,"question_type":"context","examples":[{"ja":"林さんはいつも冗談ばかり言うので、 その話も本当かどうかあやしい.","ja_furigana":"林さんはいつも冗談ばかり言うので、 その話も本当かどうかあやしい.","vi":"Vì anh Hayashi lúc nào cũng chỉ nói đùa, nên câu chuyện đó cũng không biết có thật hay không.","source":"exam"}]}'),
    ('N3_2024_12', 'VOCABULARY', 4, '{"word":"ぐっすり","reading":"ぐっすり","meaning_vi":"ngủ say","han_viet":"","tested":true,"question_type":"usage","examples":[{"ja":"今日は疲れているので、朝までぐっすり眠れそうだ。","ja_furigana":"今日は疲れているので、朝までぐっすり眠れそうだ。","vi":"Hôm nay tôi mệt nên có vẻ sẽ ngủ một mạch đến sáng.","source":"exam"}]}'),
    ('N3_2024_12', 'VOCABULARY', 5, '{"word":"もったいない","reading":"もったいない","meaning_vi":"lãng phí","han_viet":"","tested":true,"question_type":"context","examples":[{"ja":"このコートは古いがまだ着られるので、 捨ててしまうのは もったいない。","ja_furigana":"このコートは古いがまだ着られるので、 捨ててしまうのは もったいない。","vi":"Chiếc áo khoác này cũ nhưng vẫn mặc được, nên vứt đi thì thật phí.","source":"exam"}]}'),
    ('N3_2024_12', 'VOCABULARY', 6, '{"word":"やっと","reading":"やっと","meaning_vi":"cuối cùng","han_viet":"","tested":true,"question_type":"paraphrase","examples":[{"ja":"やっと宿題が終わった。","ja_furigana":"やっと宿題が終わった。","vi":"Cuối cùng tôi đã làm xong bài tập về nhà.","source":"dictionary"}]}'),
    ('N3_2024_12', 'VOCABULARY', 7, '{"word":"ようやく","reading":"ようやく","meaning_vi":"tóm tắt","han_viet":"","tested":true,"question_type":"paraphrase","examples":[{"ja":"田中さんがようやく来てくれました。","ja_furigana":"田中さんがようやく来てくれました。","vi":"Anh Tanaka cuối cùng cũng đã đến.","source":"exam"}]}'),
    ('N3_2024_12', 'VOCABULARY', 8, '{"word":"バック","reading":"バック","meaning_vi":"phía sau","han_viet":"","tested":true,"question_type":"paraphrase","examples":[{"ja":"ちょっとバックしてください。","ja_furigana":"ちょっとバックしてください。","vi":"Lùi lại một chút.","source":"exam"}]}'),
    ('N3_2024_12', 'VOCABULARY', 9, '{"word":"マイク","reading":"マイク","meaning_vi":"micrô","han_viet":"","tested":true,"question_type":"context","examples":[{"ja":"皆さんに声がよく聞こえるように、 マイク を使って話してください。","ja_furigana":"皆さんに声がよく聞こえるように、 マイク を使って話してください。","vi":"Để mọi người nghe rõ, hãy nói bằng micro.","source":"exam"}]}'),
    ('N3_2024_12', 'VOCABULARY', 10, '{"word":"一応","reading":"いちおう","meaning_vi":"tạm thời","han_viet":"NHẤT ỨNG","tested":true,"question_type":"context","examples":[{"ja":"山口さんは今度のパーティーには来られないかもしれないが、一応 誘うつもりだ。","ja_furigana":"山口さんは今度のパーティーには来られないかもしれないが、一応 誘うつもりだ。","vi":"Anh Yamaguchi có lẽ sẽ không đến bữa tiệc lần này, nhưng tôi định vẫn mời anh ấy.","source":"exam"}]}'),
    ('N3_2024_12', 'VOCABULARY', 11, '{"word":"一流","reading":"いちりゅう","meaning_vi":"hàng đầu","han_viet":"NHẤT LƯU","tested":true,"question_type":"paraphrase","examples":[{"ja":"鈴木さんは一流の選手です。","ja_furigana":"鈴木さんは一流の選手です。","vi":"Anh Suzuki là một vận động viên hàng đầu.","source":"exam"}]}'),
