    ('N3_2024_12', 'VOCABULARY', 17, '{"word":"加熱","reading":"かねつ","meaning_vi":"gia nhiệt","han_viet":"GIA NHIỆT","tested":true,"question_type":"reading","examples":[{"ja":"これは加熱して食べてください。","ja_furigana":"これは加熱して食べてください。","vi":"Hãy làm nóng rồi ăn món này.","source":"exam"}]}'),
    ('N3_2024_12', 'VOCABULARY', 18, '{"word":"勤める","reading":"つとめる","meaning_vi":"làm việc","han_viet":"CẦN","tested":true,"question_type":"orthography","examples":[{"ja":"父は銀行に勤めています。","ja_furigana":"父は銀行に勤めています。","vi":"Bố tôi làm việc ở ngân hàng.","source":"exam"}]}'),
