    ('N3_2024_12', 'VOCABULARY', 29, '{"word":"素晴らしい","reading":"すばらしい","meaning_vi":"tuyệt vời","han_viet":"","tested":true,"question_type":"paraphrase","examples":[{"ja":"この景色は素晴らしい。","ja_furigana":"この景色は素晴らしい。","vi":"Khung cảnh này thật tuyệt vời.","source":"dictionary"}]}'),
