    ('N3_2024_12', 'GRAMMAR', 1, '{"pattern":"～んです","expressions":["行くところなんです","行っているところなんです"],"is_answer":true,"link":"https://onjlpt.com/ngu-phap/n4/ndesu","level":"N4","question":{"text":"13. (会社で) 南「中山さん、今、ちょっといいですか。」 中山「あ、これから ABC 銀行に( )。戻ってきてからでもいいですか。」","options":["1) 行くところだからです","2) 行くところなんです","3) 行っているところだからです","4) 行っているところなんです"],"correct":2},"lesson":{"pattern":"～んです","name":"Thể hiện sự quan tâm đến người đối diện, muốn hỏi thêm thông tin hoặc cần lời giải thích","meaning":"Dùng để giải thích, hỏi nguyên nhân lý do hoặc thể hiện sự quan tâm, muốn biết thêm thông tin.","note":"Lưu ý: Mẫu câu 「～んです」chủ yếu được dùng để giải thích hoặc đưa ra nguyên nhân cho sự việc gì đó. Khi dùng dưới dạng câu hỏi thì ngụ ý quan tâm, hoặc có nhu cầu biết thêm thông tin từ người đối diện. Vì vậy không dùng mẫu câu này để hỏi những người không liên quan hoặc không có trách nhiệm phải biết lý do hay nguyên nhân đó.\nVí dụ cách dùng không phù hợp: （ｘ）A: せんせい、マイクさんはまだこないんですか。(Thưa cô, bạn Mike vẫn chưa đến ạ?)\nThay vào đó nên dùng: A: せんせい、マイクさんはまだきていませんか。\nCấu trúc: [Thể thường (普通形)] + んです。(「～だ」→ なんです)\nVí dụ: いく → いくんです、あった → あったんです、こない → こないんです。すきだ → すきなんです、がくせいだ → がくせいなんです、あつい → あついんです。","usages":[{"title":"Thể hiện sự quan tâm, muốn hỏi thêm thông tin","meaning":"Thể hiện sự quan tâm đến người đối diện, muốn hỏi thêm thông tin hoặc cần lời giải thích","description":"Dùng để hỏi thêm thông tin một cách lịch sự, thể hiện sự quan tâm thực sự.","structure":"[Thể thường (普通形)] + んです","examples":[{"ja":"どこでしらべたんですか。","ja_furigana":"どこでしらべたんですか。","vi":"Bạn đã tra cứu ở đâu thế?"},{"ja":"どこで買ったんですか。","ja_furigana":"どこで買ったんですか。","vi":"Cậu đã mua ở đâu vậy?"},{"ja":"えいごがぺらぺらですね。アメリカにすんでいたことがあるんですか。","ja_furigana":"えいごがぺらぺらですね。アメリカにすんでいたことがあるんですか。","vi":"Cậu nói tiếng Anh trôi chảy quá. Cậu đã từng sống ở Mỹ chưa?"},{"ja":"あれ？どうして日本に行ったんですか？","ja_furigana":"あれ？どうして日本に行ったんですか？","vi":"Ơ? Tại sao bạn lại đến Nhật vậy?"}]},{"title":"Hỏi và trả lời về nguyên nhân, lý do","meaning":"Đặt câu hỏi về nguyên nhân, lý do của việc gì đó & trả lời cho câu hỏi đó","description":"Dùng để hỏi lý do hoặc giải thích nguyên nhân cho một sự việc.","structure":"[Thể thường (普通形)] + んです","examples":[{"ja":"どこに行くんですか。","ja_furigana":"どこに行くんですか。","vi":"Bạn đi đâu thế?"},{"ja":"のどがかわいたんです。","ja_furigana":"のどがかわいたんです。","vi":"Tôi bị khát nước."},{"ja":"どうしてねこがにげたんですか。","ja_furigana":"どうしてねこがにげたんですか。","vi":"Tại sao con mèo chạy mất vậy?","note":"にげる: chạy mất"},{"ja":"友達がずっと来なかったんです。","ja_furigana":"友達がずっと来なかったんです。","vi":"Tại bạn mãi không đến.","note":"ずっと～ない: mãi không …"}]},{"title":"Bổ sung, giải thích thêm thông tin","meaning":"Bổ sung, giải thích thêm cho thông tin mình đưa ra","description":"Dùng để cung cấp thêm thông tin giải thích cho câu nói trước đó.","structure":"[Thể thường (普通形)] + んです","examples":[{"ja":"きのう、かれはしごとをやすみました。かぜをひいたんです。","ja_furigana":"きのう、かれはしごとをやすみました。かぜをひいたんです。","vi":"Hôm qua anh ấy nghỉ làm. (Vì) anh ấy bị cảm.","note":"かぜをひく: bị cảm"},{"ja":"おなかがいたいんです。くすりをのんでもいいですか。","ja_furigana":"おなかがいたいんです。くすりをのんでもいいですか。","vi":"Bụng em đau quá. Em có thể uống thuốc được không?"},{"ja":"ええ、いぬが 2ひきもいるんですか。","ja_furigana":"ええ、いぬが 2ひきもいるんですか。","vi":"Oa, bạn có tới 2 con chó cơ à?"},{"ja":"そうです。ちょっと疲れているんです。","ja_furigana":"そうです。ちょっと疲れているんです。","vi":"Ừ, tại tớ hơi mệt mà."}]},{"title":"Mở đầu câu chuyện","meaning":"Mở đầu câu chuyện, thu hút sự chú ý của người đối diện trước khi vào chủ đề chính","description":"Dùng như một cách mở đầu câu chuyện một cách lịch sự.","structure":"[Thể thường (普通形)] + んです","examples":[{"ja":"ちょっと、聞きたいことがあるんですが。","ja_furigana":"ちょっと、聞きたいことがあるんですが。","vi":"Này, tôi có điều muốn hỏi."}]}],"examples":[{"ja":"どこでしらべたんですか。","ja_furigana":"どこでしらべたんですか。","vi":"Bạn đã tra cứu ở đâu thế?"},{"ja":"どこで買ったんですか。","ja_furigana":"どこで買ったんですか。","vi":"Cậu đã mua ở đâu vậy?"},{"ja":"えいごがぺらぺらですね。アメリカにすんでいたことがあるんですか。","ja_furigana":"えいごがぺらぺらですね。アメリカにすんでいたことがあるんですか。","vi":"Cậu nói tiếng Anh trôi chảy quá. Cậu đã từng sống ở Mỹ chưa?"},{"ja":"あれ？どうして日本に行ったんですか？","ja_furigana":"あれ？どうして日本に行ったんですか？","vi":"Ơ? Tại sao bạn lại đến Nhật vậy?"},{"ja":"どこに行くんですか。","ja_furigana":"どこに行くんですか。","vi":"Bạn đi đâu thế?"},{"ja":"のどがかわいたんです。","ja_furigana":"のどがかわいたんです。","vi":"Tôi bị khát nước."},{"ja":"どうしてねこがにげたんですか。","ja_furigana":"どうしてねこがにげたんですか。","vi":"Tại sao con mèo chạy mất vậy?","note":"にげる: chạy mất"},{"ja":"友達がずっと来なかったんです。","ja_furigana":"友達がずっと来なかったんです。","vi":"Tại bạn mãi không đến.","note":"ずっと～ない: mãi không …"},{"ja":"きのう、かれはしごとをやすみました。かぜをひいたんです。","ja_furigana":"きのう、かれはしごとをやすみました。かぜをひいたんです。","vi":"Hôm qua anh ấy nghỉ làm. (Vì) anh ấy bị cảm.","note":"かぜをひく: bị cảm"},{"ja":"おなかがいたいんです。くすりをのんでもいいですか。","ja_furigana":"おなかがいたいんです。くすりをのんでもいいですか。","vi":"Bụng em đau quá. Em có thể uống thuốc được không?"},{"ja":"ええ、いぬが 2ひきもいるんですか。","ja_furigana":"ええ、いぬが 2ひきもいるんですか。","vi":"Oa, bạn có tới 2 con chó cơ à?"},{"ja":"そうです。ちょっと疲れているんです。","ja_furigana":"そうです。ちょっと疲れているんです。","vi":"Ừ, tại tớ hơi mệt mà."},{"ja":"ちょっと、聞きたいことがあるんですが。","ja_furigana":"ちょっと、聞きたいことがあるんですが。","vi":"Này, tôi có điều muốn hỏi."}],"structures":[{"Cách dùng":"Thể hiện sự quan tâm, muốn hỏi thêm thông tin","Cấu trúc":"[Thể thường (普通形)] + んです","Nghĩa":"Thể hiện sự quan tâm đến người đối diện, muốn hỏi thêm thông tin hoặc cần lời giải thích"},{"Cách dùng":"Hỏi và trả lời về nguyên nhân, lý do","Cấu trúc":"[Thể thường (普通形)] + んです","Nghĩa":"Đặt câu hỏi về nguyên nhân, lý do của việc gì đó & trả lời cho câu hỏi đó"},{"Cách dùng":"Bổ sung, giải thích thêm thông tin","Cấu trúc":"[Thể thường (普通形)] + んです","Nghĩa":"Bổ sung, giải thích thêm cho thông tin mình đưa ra"},{"Cách dùng":"Mở đầu câu chuyện","Cấu trúc":"[Thể thường (普通形)] + んです","Nghĩa":"Mở đầu câu chuyện, thu hút sự chú ý của người đối diện trước khi vào chủ đề chính"}],"related":[{"title":"～ほうがいいです","link":"https://onjlpt.com/ngu-phap/n4/hou-ga-ii-desu"},{"title":"Động từ thể ý chí","link":"https://onjlpt.com/ngu-phap/n4/doutai-there-y-chi"},{"title":"～ようと思います/ようと思っています","link":"https://onjlpt.com/ngu-phap/n4/you-to-omoimasu-you-to-omotteimasu"},{"title":"～つもりです","link":"https://onjlpt.com/ngu-phap/n4/tsumori-desu"}],"description":"Dùng để giải thích, hỏi nguyên nhân lý do hoặc thể hiện sự quan tâm, muốn biết thêm thông tin."}}'),
    ('N3_2024_12', 'GRAMMAR', 2, '{"pattern":"～ていただけませんか","expressions":["貸していただけませんか"],"is_answer":true,"link":"https://onjlpt.com/ngu-phap/n4/te-itadakemasen-ka","level":"N4","question":{"text":"11. (大学の事務所で) 学生「すみません。ペンを( )」 事務所の人「あ、はい。これを使ってください。」","options":["1) お貸しできますか","2) お貸しいたしますか","3) 貸したらいかがですか","4) 貸していただけませんか"],"correct":4},"lesson":{"pattern":"～ていただけませんか","name":"Làm ơn... được không?","meaning":"Diễn đạt lời đề nghị, yêu cầu lịch sự nhờ ai đó làm gì giúp mình, mang tính trang trọng hơn ～てください","note":"～ていただけませんか: cách yêu cầu lịch sự, trang trọng nhất.\n～くださいませんか: cách yêu cầu trang trọng nhưng ít hơn いただけませんか.\n～てください: cách yêu cầu thông thường, ít trang trọng hơn.\nThứ tự mức độ lịch sự: ～ていただけませんか → ～くださいませんか → ～てください.\nDùng trong tình huống cần sự lịch sự, trang trọng với người lớn tuổi, cấp trên hoặc người không thân thiết.","usages":[{"title":"Yêu cầu lịch sự","meaning":"Làm ơn... được không?","description":"Diễn đạt yêu cầu, đề nghị lịch sự nhất","structure":"[Động từ thể て] + いただけませんか","examples":[{"ja":"この書類を英語に翻訳していただけませんか。","ja_furigana":"この書類を英語に翻訳していただけませんか。","vi":"Làm ơn dịch tài liệu này sang tiếng Anh giúp tôi được không?","note":"Mức độ lịch sự cao nhất"},{"ja":"この書類を確認していただけませんか。","ja_furigana":"この書類を確認していただけませんか。","vi":"Làm ơn kiểm tra giúp tôi tài liệu này được không?","note":"書類: tài liệu"},{"ja":"この書類をチェックしていただけませんか。","ja_furigana":"この書類をチェックしていただけませんか。","vi":"Làm ơn kiểm tra giúp tôi tài liệu này được không?","note":"書類: しょるい: tài liệu, チェック: kiểm tra"}]},{"title":"Yêu cầu trang trọng","meaning":"Làm ơn... được không?","description":"Diễn đạt yêu cầu trang trọng nhưng ít hơn いただけませんか","structure":"[Động từ thể て] + くださいませんか","examples":[{"ja":"この書類をチェックしていただけませんか。","ja_furigana":"この書類をチェックしていただけませんか。","vi":"Làm ơn kiểm tra giúp tôi tài liệu này được không?","note":"Mức độ lịch sự trung bình"},{"ja":"この書類をチェックしていただけませんか。","ja_furigana":"この書類をチェックしていただけませんか。","vi":"Làm ơn kiểm tra giúp tôi tài liệu này được không?"}]}],"examples":[{"ja":"この書類を英語に翻訳していただけませんか。","ja_furigana":"この書類を英語に翻訳していただけませんか。","vi":"Làm ơn dịch tài liệu này sang tiếng Anh giúp tôi được không?","note":"Mức độ lịch sự cao nhất"},{"ja":"この書類を確認していただけませんか。","ja_furigana":"この書類を確認していただけませんか。","vi":"Làm ơn kiểm tra giúp tôi tài liệu này được không?","note":"書類: tài liệu"},{"ja":"この書類をチェックしていただけませんか。","ja_furigana":"この書類をチェックしていただけませんか。","vi":"Làm ơn kiểm tra giúp tôi tài liệu này được không?","note":"書類: しょるい: tài liệu, チェック: kiểm tra"},{"ja":"この書類をチェックしていただけませんか。","ja_furigana":"この書類をチェックしていただけませんか。","vi":"Làm ơn kiểm tra giúp tôi tài liệu này được không?","note":"Mức độ lịch sự trung bình"},{"ja":"この書類をチェックしていただけませんか。","ja_furigana":"この書類をチェックしていただけませんか。","vi":"Làm ơn kiểm tra giúp tôi tài liệu này được không?"}],"structures":[{"Cách dùng":"Yêu cầu lịch sự","Cấu trúc":"[Động từ thể て] + いただけませんか","Nghĩa":"Làm ơn... được không?"},{"Cách dùng":"Yêu cầu trang trọng","Cấu trúc":"[Động từ thể て] + くださいませんか","Nghĩa":"Làm ơn... được không?"}],"related":[{"title":"～んです","link":"https://onjlpt.com/ngu-phap/n4/ndesu"},{"title":"～ほうがいいです","link":"https://onjlpt.com/ngu-phap/n4/hou-ga-ii-desu"},{"title":"Động từ thể ý chí","link":"https://onjlpt.com/ngu-phap/n4/doutai-there-y-chi"},{"title":"～ようと思います/ようと思っています","link":"https://onjlpt.com/ngu-phap/n4/you-to-omoimasu-you-to-omotteimasu"}],"description":"Diễn đạt lời đề nghị, yêu cầu lịch sự nhờ ai đó làm gì giúp mình, mang tính trang trọng hơn ～てください"}}'),
    ('N3_2024_12', 'GRAMMAR', 3, '{"pattern":"～たびに","expressions":["たびに"],"is_answer":false,"link":"https://onjlpt.com/ngu-phap/n3/tabi-ni","level":"N3","question":{"text":"17. 部長が＿＿＿ ＿＿＿ ＿★＿ ＿＿＿クッキーがとてもおいしいので、私も東京に行くことがあったら、買おうと思う。","options":["1) たびに","2) 買ってきてくれる","3) お土産の","4) 東京へ出張に行く"],"correct":2},"lesson":null}'),
    ('N3_2024_12', 'GRAMMAR', 4, '{"pattern":"～ために、～ように","expressions":["ために"],"is_answer":false,"link":"https://onjlpt.com/ngu-phap/n4/tame-ni-you-ni","level":"N4","question":{"text":"16. 私は、健康の＿＿＿ ＿＿＿ ＿★＿ ＿＿＿。","options":["1) している","2) ために","3) 毎日8時間以上寝る","4) ように"],"correct":4},"lesson":{"pattern":"～ために、～ように","name":"Để làm gì/Vì cái gì","meaning":"Diễn đạt mục đích với sự khác biệt về sắc thái: ～ために cho mục đích trực tiếp, ～ように cho mục đích gián tiếp hoặc không thuộc kiểm soát trực tiếp","note":"「～ために」dùng cho mục đích trực tiếp thuộc kiểm soát của người nói\n「～ように」dùng cho mục đích gián tiếp, không thuộc kiểm soát trực tiếp, hoặc liên quan đến khả năng\nThể ない thường chỉ dùng với 「ように」\nMục đích hướng về người khác thường dùng 「ように」","usages":[{"title":"～ために (Danh từ)","meaning":"Để làm gì/Vì cái gì","description":"Diễn đạt mục đích trực tiếp với danh từ","structure":"[Danh từ] + の + ために","examples":[{"ja":"健康のために、毎朝ジョギングしています。","ja_furigana":"健康のために、毎朝ジョギングしています。","vi":"Tôi chạy bộ mỗi sáng để giữ sức khỏe.","note":"健康: けんこう: sức khỏe, 毎朝: まいあさ: mỗi sáng"},{"ja":"健康のために、毎日ジョギングをしています。","ja_furigana":"健康のために、毎日ジョギングをしています。","vi":"Tôi chạy bộ mỗi ngày để giữ gìn sức khỏe.","note":"健康: けんこう: sức khỏe"}]},{"title":"～ために (Động từ)","meaning":"Để làm gì/Vì cái gì","description":"Diễn đạt mục đích trực tiếp với động từ","structure":"[Động từ thể từ điển] + ために","examples":[{"ja":"仕事をするために、東京に引っ越しました。","ja_furigana":"仕事をするために、東京に引っ越しました。","vi":"Tôi đã chuyển đến Tokyo để làm việc."},{"ja":"旅行に行くために、荷物を準備します。","ja_furigana":"旅行に行くために、荷物を準備します。","vi":"Tôi chuẩn bị hành lý để đi du lịch.","note":"旅行: りょこう: du lịch, 荷物: にもつ: hành lý, 準備: じゅんび: chuẩn bị"},{"ja":"映画を見るために、映画館に行きました。","ja_furigana":"映画を見るために、映画館に行きました。","vi":"Tôi đã đi đến rạp chiếu phim để xem phim."},{"ja":"彼は仕事をするために、新しいパソコンを買いました。","ja_furigana":"彼は仕事をするために、新しいパソコンを買いました。","vi":"Anh ấy mua máy tính mới để làm việc.","note":"→ mục đích hướng về bản thân \"anh ấy\""}]},{"title":"～ように","meaning":"Để có thể mà, để mà…","description":"Diễn đạt mục đích gián tiếp, không thuộc kiểm soát trực tiếp","structure":"[Động từ thể từ điển/thể ない/thể khả năng] + ように","examples":[{"ja":"学生が理解できるように、説明をゆっくりしました。","ja_furigana":"学生が理解できるように、説明をゆっくりしました。","vi":"Tôi đã giải thích chậm rãi để học sinh có thể hiểu."},{"ja":"風邪をひかないように、暖かくして寝ます。","ja_furigana":"風邪をひかないように、暖かくして寝ます。","vi":"Tôi giữ ấm khi ngủ để không bị cảm."},{"ja":"試験に合格できるように、毎日勉強しています。","ja_furigana":"試験に合格できるように、毎日勉強しています。","vi":"Tôi học mỗi ngày để có thể đỗ kỳ thi.","note":"試験: しけん: kỳ thi, 合格する: ごうかくする: đỗ, 毎日: まいにち: mỗi ngày, 勉強する: べんきょうする: học"},{"ja":"犬が飲めるように、牛乳を温かくしました。","ja_furigana":"犬が飲めるように、牛乳を温かくしました。","vi":"Tôi làm ấm sữa để chó có thể uống được.","note":"温かい: あたたかい: ấm"},{"ja":"けがをしないように、運動靴を履いた。","ja_furigana":"けがをしないように、運動靴を履いた。","vi":"Tôi đi giày thể thao để không bị thương.","note":"けが: chấn thương, 運動靴: うんどうぐつ: giày thể thao, 履く: はく: đi (giày)"},{"ja":"彼女が料理を習うように、料理教室に通わせています。","ja_furigana":"彼女が料理を習うように、料理教室に通わせています。","vi":"Tôi cho cô ấy tham gia lớp học nấu ăn để cô ấy học nấu ăn.","note":"料理教室: りょうりきょうしつ: lớp học nấu ăn → mục đích hướng về \"cô ấy\""},{"ja":"学生に理解してもらうために、図を描きました。","ja_furigana":"学生に理解してもらうために、図を描きました。","vi":"Tôi đã vẽ sơ đồ để học sinh có thể hiểu.","note":"理解: りかい: hiểu → mục đích hướng về \"tôi\""},{"ja":"日本語が上手に話せるように、毎日練習しています。","ja_furigana":"日本語が上手に話せるように、毎日練習しています。","vi":"Tôi luyện tập mỗi ngày để có thể nói tiếng Nhật giỏi.","note":"練習する: れんしゅうする: luyện tập → thuộc về khả năng"}]}],"examples":[{"ja":"健康のために、毎朝ジョギングしています。","ja_furigana":"健康のために、毎朝ジョギングしています。","vi":"Tôi chạy bộ mỗi sáng để giữ sức khỏe.","note":"健康: けんこう: sức khỏe, 毎朝: まいあさ: mỗi sáng"},{"ja":"健康のために、毎日ジョギングをしています。","ja_furigana":"健康のために、毎日ジョギングをしています。","vi":"Tôi chạy bộ mỗi ngày để giữ gìn sức khỏe.","note":"健康: けんこう: sức khỏe"},{"ja":"仕事をするために、東京に引っ越しました。","ja_furigana":"仕事をするために、東京に引っ越しました。","vi":"Tôi đã chuyển đến Tokyo để làm việc."},{"ja":"旅行に行くために、荷物を準備します。","ja_furigana":"旅行に行くために、荷物を準備します。","vi":"Tôi chuẩn bị hành lý để đi du lịch.","note":"旅行: りょこう: du lịch, 荷物: にもつ: hành lý, 準備: じゅんび: chuẩn bị"},{"ja":"映画を見るために、映画館に行きました。","ja_furigana":"映画を見るために、映画館に行きました。","vi":"Tôi đã đi đến rạp chiếu phim để xem phim."},{"ja":"彼は仕事をするために、新しいパソコンを買いました。","ja_furigana":"彼は仕事をするために、新しいパソコンを買いました。","vi":"Anh ấy mua máy tính mới để làm việc.","note":"→ mục đích hướng về bản thân \"anh ấy\""},{"ja":"学生が理解できるように、説明をゆっくりしました。","ja_furigana":"学生が理解できるように、説明をゆっくりしました。","vi":"Tôi đã giải thích chậm rãi để học sinh có thể hiểu."},{"ja":"風邪をひかないように、暖かくして寝ます。","ja_furigana":"風邪をひかないように、暖かくして寝ます。","vi":"Tôi giữ ấm khi ngủ để không bị cảm."},{"ja":"試験に合格できるように、毎日勉強しています。","ja_furigana":"試験に合格できるように、毎日勉強しています。","vi":"Tôi học mỗi ngày để có thể đỗ kỳ thi.","note":"試験: しけん: kỳ thi, 合格する: ごうかくする: đỗ, 毎日: まいにち: mỗi ngày, 勉強する: べんきょうする: học"},{"ja":"犬が飲めるように、牛乳を温かくしました。","ja_furigana":"犬が飲めるように、牛乳を温かくしました。","vi":"Tôi làm ấm sữa để chó có thể uống được.","note":"温かい: あたたかい: ấm"},{"ja":"けがをしないように、運動靴を履いた。","ja_furigana":"けがをしないように、運動靴を履いた。","vi":"Tôi đi giày thể thao để không bị thương.","note":"けが: chấn thương, 運動靴: うんどうぐつ: giày thể thao, 履く: はく: đi (giày)"},{"ja":"彼女が料理を習うように、料理教室に通わせています。","ja_furigana":"彼女が料理を習うように、料理教室に通わせています。","vi":"Tôi cho cô ấy tham gia lớp học nấu ăn để cô ấy học nấu ăn.","note":"料理教室: りょうりきょうしつ: lớp học nấu ăn → mục đích hướng về \"cô ấy\""},{"ja":"学生に理解してもらうために、図を描きました。","ja_furigana":"学生に理解してもらうために、図を描きました。","vi":"Tôi đã vẽ sơ đồ để học sinh có thể hiểu.","note":"理解: りかい: hiểu → mục đích hướng về \"tôi\""},{"ja":"日本語が上手に話せるように、毎日練習しています。","ja_furigana":"日本語が上手に話せるように、毎日練習しています。","vi":"Tôi luyện tập mỗi ngày để có thể nói tiếng Nhật giỏi.","note":"練習する: れんしゅうする: luyện tập → thuộc về khả năng"}],"structures":[{"Cách dùng":"～ために (Danh từ)","Cấu trúc":"[Danh từ] + の + ために","Nghĩa":"Để làm gì/Vì cái gì"},{"Cách dùng":"～ために (Động từ)","Cấu trúc":"[Động từ thể từ điển] + ために","Nghĩa":"Để làm gì/Vì cái gì"},{"Cách dùng":"～ように","Cấu trúc":"[Động từ thể từ điển/thể ない/thể khả năng] + ように","Nghĩa":"Để có thể mà, để mà…"}],"related":[{"title":"～んです","link":"https://onjlpt.com/ngu-phap/n4/ndesu"},{"title":"～ほうがいいです","link":"https://onjlpt.com/ngu-phap/n4/hou-ga-ii-desu"},{"title":"Động từ thể ý chí","link":"https://onjlpt.com/ngu-phap/n4/doutai-there-y-chi"},{"title":"～ようと思います/ようと思っています","link":"https://onjlpt.com/ngu-phap/n4/you-to-omoimasu-you-to-omotteimasu"}],"description":"Diễn đạt mục đích với sự khác biệt về sắc thái: ～ために cho mục đích trực tiếp, ～ように cho mục đích gián tiếp hoặc không thuộc kiểm soát trực tiếp"}}'),
    ('N3_2024_12', 'GRAMMAR', 5, '{"pattern":"～なら","expressions":["なら"],"is_answer":false,"link":"https://onjlpt.com/ngu-phap/n4/nara","level":"N4","question":{"text":"1. 私は、自分の作ったパンをたくさんの人( ) 食べてほしいと思って、パン屋を始めた。","options":["1) は","2) に","3) まで","4) なら"],"correct":2},"lesson":{"pattern":"～なら","name":"Nếu A thì B (đề xuất)","meaning":"Mẫu câu điều kiện diễn đạt giả định dựa trên thông tin có sẵn, dùng để đưa ra đánh giá, mệnh lệnh, mong muốn hoặc ý định","note":"Đặc điểm khác biệt:\nKhác với các mẫu câu điều kiện khác, ～なら không yêu cầu mối quan hệ thời gian giữa hai vế (vế 1 không cần xảy ra trước vế 2)\nThường dùng để phản hồi lại thông tin đã nghe từ người đối diện\nCó thể thêm の hoặc ん phía trước なら để nhấn mạnh mà không thay đổi nghĩa","usages":[{"title":"Đưa ra đánh giá, đề xuất","meaning":"Nếu A thì B (đề xuất)","description":"Dựa vào giả định/điều kiện ở vế 1 để đưa ra đánh giá, mệnh lệnh, mong muốn hoặc ý định","structure":"Vる/Vた/Vない + なら\\nAい + なら\\nAな + なら\\nN + なら","examples":[{"ja":"大阪へ行くなら, 飛行機が速いです。","ja_furigana":"大阪へ行くなら, 飛行機が速いです。","vi":"Nếu mà đi Osaka thì đi máy bay là nhanh.","note":"飛行機: ひこうき: máy bay、速い: はやい: nhanh"},{"ja":"天気がいいなら、公園に行きましょう。","ja_furigana":"天気がいいなら、公園に行きましょう。","vi":"Nếu thời tiết đẹp thì đi công viên đi."},{"ja":"雨なら、家にいたほうがいいですよ。","ja_furigana":"雨なら、家にいたほうがいいですよ。","vi":"Nếu mà trời mưa thì ở nhà sẽ tốt hơn đấy.","note":"雨: あめ: mưa"},{"ja":"日本人なら","ja_furigana":"日本人なら","vi":"Nếu là người Nhật thì chắc chắn thích sushi."},{"ja":"行くなら早く行ったほうがいい。","ja_furigana":"行くなら早く行ったほうがいい。","vi":"Nếu đi thì nên đi sớm."}]},{"title":"Phản hồi thông tin","meaning":"Nếu đã A thì B (phản hồi)","description":"Dùng để phản hồi lại thông tin nghe được từ người đối diện và đưa ra nhận xét","structure":"Vる/Vた/Vない + なら\\nAい + なら\\nAな + なら\\nN + なら","examples":[{"ja":"スマホがあるなら、写真が撮れますね。","ja_furigana":"スマホがあるなら、写真が撮れますね。","vi":"Nếu có điện thoại thông minh thì chụp được ảnh nhỉ.","note":"Phản hồi thông tin từ người đối diện"}]}],"examples":[{"ja":"大阪へ行くなら, 飛行機が速いです。","ja_furigana":"大阪へ行くなら, 飛行機が速いです。","vi":"Nếu mà đi Osaka thì đi máy bay là nhanh.","note":"飛行機: ひこうき: máy bay、速い: はやい: nhanh"},{"ja":"天気がいいなら、公園に行きましょう。","ja_furigana":"天気がいいなら、公園に行きましょう。","vi":"Nếu thời tiết đẹp thì đi công viên đi."},{"ja":"雨なら、家にいたほうがいいですよ。","ja_furigana":"雨なら、家にいたほうがいいですよ。","vi":"Nếu mà trời mưa thì ở nhà sẽ tốt hơn đấy.","note":"雨: あめ: mưa"},{"ja":"日本人なら","ja_furigana":"日本人なら","vi":"Nếu là người Nhật thì chắc chắn thích sushi."},{"ja":"行くなら早く行ったほうがいい。","ja_furigana":"行くなら早く行ったほうがいい。","vi":"Nếu đi thì nên đi sớm."},{"ja":"スマホがあるなら、写真が撮れますね。","ja_furigana":"スマホがあるなら、写真が撮れますね。","vi":"Nếu có điện thoại thông minh thì chụp được ảnh nhỉ.","note":"Phản hồi thông tin từ người đối diện"}],"structures":[{"Cách dùng":"Đưa ra đánh giá, đề xuất","Cấu trúc":"Vる/Vた/Vない + なら\\nAい + なら\\nAな + なら\\nN + なら","Nghĩa":"Nếu A thì B (đề xuất)"},{"Cách dùng":"Phản hồi thông tin","Cấu trúc":"Vる/Vた/Vない + なら\\nAい + なら\\nAな + なら\\nN + なら","Nghĩa":"Nếu đã A thì B (phản hồi)"}],"related":[{"title":"～んです","link":"https://onjlpt.com/ngu-phap/n4/ndesu"},{"title":"～ほうがいいです","link":"https://onjlpt.com/ngu-phap/n4/hou-ga-ii-desu"},{"title":"Động từ thể ý chí","link":"https://onjlpt.com/ngu-phap/n4/doutai-there-y-chi"},{"title":"～ようと思います/ようと思っています","link":"https://onjlpt.com/ngu-phap/n4/you-to-omoimasu-you-to-omotteimasu"}],"description":"Mẫu câu điều kiện diễn đạt giả định dựa trên thông tin có sẵn, dùng để đưa ra đánh giá, mệnh lệnh, mong muốn hoặc ý định"}}'),
    ('N3_2024_12', 'GRAMMAR', 6, '{"pattern":"～にとって","expressions":["にとって"],"is_answer":false,"link":"https://onjlpt.com/ngu-phap/n3/ni-totte","level":"N3","question":{"text":"2. (研究室) 学生「先生、今、よろしいですか。来躍の発表( ) 、ちょっとご相談したいのですが。」 先生「ええ、いいですよ。」","options":["1) にとって","2) によると","3) のことで","4) のほか"],"correct":3},"lesson":null}'),
    ('N3_2024_12', 'GRAMMAR', 7, '{"pattern":"～によれば/～によると","expressions":["によると"],"is_answer":false,"link":"https://onjlpt.com/ngu-phap/n3/ni-yoreba-ni-yoru-to","level":"N3","question":{"text":"2. (研究室) 学生「先生、今、よろしいですか。来躍の発表( ) 、ちょっとご相談したいのですが。」 先生「ええ、いいですよ。」","options":["1) にとって","2) によると","3) のことで","4) のほか"],"correct":3},"lesson":null}'),
    ('N3_2024_12', 'GRAMMAR', 8, '{"pattern":"～に対して","expressions":["に対して"],"is_answer":false,"link":"https://onjlpt.com/ngu-phap/n3/ni-taishite","level":"N3","question":{"text":"14. 山川大学では、＿＿＿ ＿＿＿ ＿★＿ ＿＿＿新入生がにアンケート調売を行っている。","options":["1) 大学生活","2) 持っている","3) に対して","4) イメージ"],"correct":2},"lesson":null}'),
    ('N3_2024_12', 'GRAMMAR', 9, '{"pattern":"～まで","expressions":["まで"],"is_answer":false,"link":"https://onjlpt.com/ngu-phap/n3/made","level":"N3","question":{"text":"1. 私は、自分の作ったパンをたくさんの人( ) 食べてほしいと思って、パン屋を始めた。","options":["1) は","2) に","3) まで","4) なら"],"correct":2},"lesson":null}'),
    ('N3_2024_12', 'GRAMMAR', 10, '{"pattern":"～ように、～ような","expressions":["ように"],"is_answer":false,"link":"https://onjlpt.com/ngu-phap/n3/you-ni-you-na","level":"N3","question":{"text":"16. 私は、健康の＿＿＿ ＿＿＿ ＿★＿ ＿＿＿。","options":["1) している","2) ために","3) 毎日8時間以上寝る","4) ように"],"correct":4},"lesson":null}'),
    ('N3_2024_12', 'GRAMMAR', 11, '{"pattern":"～ながら","expressions":["景色を楽しみながら"],"is_answer":false,"link":"https://onjlpt.com/ngu-phap/n4/nagara","level":"N4","question":{"text":"18. 私はこの図書館が好きだ。広くて本の数が多い＿＿＿ ＿＿＿ ＿★＿ ＿＿＿いい。","options":["1) 景色を楽しみながら","2) 大きな窓から海が見えて","3) だけでなく","4) 読書ができるのも"],"correct":1},"lesson":{"pattern":"～ながら","name":"Ôn JLPTChào mừng ngày 30/4 - Tự hào Việt Nam – Một lần ngoảnh lại, vạn niềm kiêu hãnh!","meaning":"Diễn tả một hành động diễn ra cùng lúc với một hành động khác","note":"Ý nghĩa: Mẫu câu này diễn tả một hành động diễn ra cùng lúc với một hành động khác. Hành động được miêu tả ở vế 「～ながら」đứng trước, hành động ở vế sau là hành động chính.\nCấu trúc: [Động từ thể ます (bỏ ます)] + ながら\nVí dụ: 書く（かく）→ 書きます → 書きながら、話す（はなす）→ 話します → 話しながら、食べる（たべる）→ 食べます → 食べながら、する → します → しながら","usages":[{"title":"Hai hành động đồng thời","meaning":"Ôn JLPTChào mừng ngày 30/4 - Tự hào Việt Nam – Một lần ngoảnh lại, vạn niềm kiêu hãnh!","description":"Follow Onjlpt Luyện tập N3N2N1 Luyện đề N5N4N3N2N1 Kanji N3N2 Từ vựng Từ vựng đề thi214 Bộ thủHiraganaKatakana Ngữ pháp N5N4N3N2N1 Video HomeGóp ý Furigana Chưa thuộc ～ながら Diễn tả một hành động diễn ra cùng lúc với một hành động khác Các cách sử dụng Hai hành động đồng thời Diễn tả hai hành động xảy ra đồng thời Hành động ở vế 「～ながら」là hành động phụ, hành động ở vế sau là hành động chính","structure":"[Động từ thể ます (bỏ ます)] + ながら","examples":[{"ja":"音楽を聞きながら、宿題をします。","ja_furigana":"音楽を聞きながら、宿題をします。","vi":"Tôi nghe nhạc trong khi làm bài tập.","note":"Làm bài tập là hành động chính"},{"ja":"テレビを見ながら、ご飯を食べています。","ja_furigana":"テレビを見ながら、ご飯を食べています。","vi":"Tôi xem tivi trong khi đang ăn cơm","note":"Ăn cơm là hành động chính"},{"ja":"音楽を聞きながら、料理をするのが好きです。","ja_furigana":"音楽を聞きながら、料理をするのが好きです。","vi":"Tôi thích nấu ăn trong khi nghe nhạc.","note":"Nấu ăn là hành động chính"},{"ja":"彼女(かのじょ)は音楽(おんがく)を聴(き)きながら、料理(りょうり)をしています。","ja_furigana":"彼女(かのじょ)は音楽(おんがく)を聴(き)きながら、料理(りょうり)をしています。","vi":"Cô ấy nghe nhạc trong khi nấu ăn.","note":"Nấu ăn là hành động chính"},{"ja":"音楽(おんがく) を聞(き)きながら、宿題(しゅくだい) をします。","ja_furigana":"音楽(おんがく) を聞(き)きながら、宿題(しゅくだい) をします。","vi":"Tôi vừa nghe nhạc vừa làm bài tập về nhà."}]}],"examples":[{"ja":"音楽を聞きながら、宿題をします。","ja_furigana":"音楽を聞きながら、宿題をします。","vi":"Tôi nghe nhạc trong khi làm bài tập.","note":"Làm bài tập là hành động chính"},{"ja":"テレビを見ながら、ご飯を食べています。","ja_furigana":"テレビを見ながら、ご飯を食べています。","vi":"Tôi xem tivi trong khi đang ăn cơm","note":"Ăn cơm là hành động chính"},{"ja":"音楽を聞きながら、料理をするのが好きです。","ja_furigana":"音楽を聞きながら、料理をするのが好きです。","vi":"Tôi thích nấu ăn trong khi nghe nhạc.","note":"Nấu ăn là hành động chính"},{"ja":"彼女(かのじょ)は音楽(おんがく)を聴(き)きながら、料理(りょうり)をしています。","ja_furigana":"彼女(かのじょ)は音楽(おんがく)を聴(き)きながら、料理(りょうり)をしています。","vi":"Cô ấy nghe nhạc trong khi nấu ăn.","note":"Nấu ăn là hành động chính"},{"ja":"音楽(おんがく) を聞(き)きながら、宿題(しゅくだい) をします。","ja_furigana":"音楽(おんがく) を聞(き)きながら、宿題(しゅくだい) をします。","vi":"Tôi vừa nghe nhạc vừa làm bài tập về nhà."}],"structures":[{"Cách dùng":"Hai hành động đồng thời","Cấu trúc":"[Động từ thể ます (bỏ ます)] + ながら","Nghĩa":"Ôn JLPTChào mừng ngày 30/4 - Tự hào Việt Nam – Một lần ngoảnh lại, vạn niềm kiêu hãnh!"}],"related":[{"title":"～んです","link":"https://onjlpt.com/ngu-phap/n4/ndesu"},{"title":"～ほうがいいです","link":"https://onjlpt.com/ngu-phap/n4/hou-ga-ii-desu"},{"title":"Động từ thể ý chí","link":"https://onjlpt.com/ngu-phap/n4/doutai-there-y-chi"},{"title":"～ようと思います/ようと思っています","link":"https://onjlpt.com/ngu-phap/n4/you-to-omoimasu-you-to-omotteimasu"}],"description":"Diễn tả một hành động diễn ra cùng lúc với một hành động khác"}}'),
    ('N3_2024_12', 'GRAMMAR', 12, '{"pattern":"～ないと、～なくちゃ","expressions":["着ておかないと","着てみないと"],"is_answer":false,"link":"https://onjlpt.com/ngu-phap/n3/nai-to-nakucha","level":"N3","question":{"text":"7. 私はよくインターネットで買い物をするが、洋服は買わない。実際に( )買いたいからだ。","options":["1) 着てみないと","2) 着ておかないと","3) 着てみてから","4) 着ておいてから"],"correct":3},"lesson":null}'),
    ('N3_2024_12', 'GRAMMAR', 13, '{"pattern":"～ばいい/～たらいい/～といい","expressions":["行けたらいいなあ"],"is_answer":false,"link":"https://onjlpt.com/ngu-phap/n3/ba-ii-tara-ii-to-ii","level":"N3","question":{"text":"10. (大学で) A 「日曜日の留学生交流会、どうだった?」 B 「楽しかったよ。初めてだったからちょっと緊張したけど、新しい友達もできたし、( )」","options":["1) 行ってよかったよ","2) 行こうかと思うよ","3) 行きたかったなあ","4) 行けたらいいなあ"],"correct":1},"lesson":null}');
INSERT INTO tmp_jlpt_study_item (exam_code, item_kind, sort_order, payload) VALUES
    ('N3_2025_07', 'VOCABULARY', 1, '{"word":"早い","reading":"はやい","meaning_vi":"nhanh","han_viet":"TẢO","tested":true,"question_type":"paraphrase","examples":[{"ja":"彼は早いです。","ja_furigana":"彼は早いです。","vi":"Anh ấy nhanh.","source":"dictionary"}]}'),
    ('N3_2025_07', 'VOCABULARY', 2, '{"word":"いろいろ","reading":"いろいろ","meaning_vi":"nhiều loại","han_viet":"","tested":true,"question_type":"paraphrase","examples":[{"ja":"色々な本を読みました。","ja_furigana":"色々な本を読みました。","vi":"Tôi đã đọc nhiều loại sách.","source":"dictionary"}]}'),
    ('N3_2025_07', 'VOCABULARY', 3, '{"word":"くやしい","reading":"くやしい","meaning_vi":"bực bội","han_viet":"","tested":true,"question_type":"context","examples":[{"ja":"この前は試合に負けてくやしかったが、今回は勝てたので、本当にうれしい。","ja_furigana":"この前は試合に負けてくやしかったが、今回は勝てたので、本当にうれしい。","vi":"Lần trước tôi thua trận nên rất tiếc, nhưng lần này thắng được nên tôi thật sự rất vui.","source":"exam"}]}'),
    ('N3_2025_07', 'VOCABULARY', 4, '{"word":"さまざま","reading":"さまざま","meaning_vi":"đa dạng; nhiều loại","han_viet":"","tested":true,"question_type":"paraphrase","examples":[{"ja":"この店ではさまざまな料理が食べられます。","ja_furigana":"この店ではさまざまな料理が食べられます。","vi":"Ở quán này có thể ăn nhiều món khác nhau.","source":"exam"}]}'),
    ('N3_2025_07', 'VOCABULARY', 5, '{"word":"そっと","reading":"そっと","meaning_vi":"nhẹ nhàng","han_viet":"","tested":true,"question_type":"paraphrase","examples":[{"ja":"本田さんと佐藤さんは、部屋からそっと出ていった。","ja_furigana":"本田さんと佐藤さんは、部屋からそっと出ていった。","vi":"Anh Honda và anh Sato đã lặng lẽ ra khỏi phòng.","source":"exam"}]}'),
    ('N3_2025_07', 'VOCABULARY', 6, '{"word":"たつ","reading":"たつ","meaning_vi":"cắt đứt","han_viet":"","tested":true,"question_type":"paraphrase","examples":[{"ja":"ここに来てから1週間くらいたちました。","ja_furigana":"ここに来てから1週間くらいたちました。","vi":"Từ khi đến đây đã khoảng một tuần trôi qua.","source":"exam"}]}'),
    ('N3_2025_07', 'VOCABULARY', 7, '{"word":"ばらばら","reading":"ばらばら","meaning_vi":"rời rạc; rời ra; tan tác","han_viet":"","tested":true,"question_type":"usage","examples":[{"ja":"床に落としてしまい、資料がばらばらになってしまった。","ja_furigana":"床に落としてしまい、資料がばらばらになってしまった。","vi":"Tôi đã làm rơi xuống sàn nên tài liệu bị tung ra khắp nơi.","source":"exam"}]}'),
    ('N3_2025_07', 'VOCABULARY', 8, '{"word":"ふく","reading":"ふく","meaning_vi":"phó; phụ; bản sao; trạng từ","han_viet":"","tested":true,"question_type":"context","examples":[{"ja":"シャワーの後は、このタオルで体をふいてください。","ja_furigana":"シャワーの後は、このタオルで体をふいてください。","vi":"Sau khi tắm xong, hãy dùng khăn này để lau người.","source":"exam"}]}'),
    ('N3_2025_07', 'VOCABULARY', 9, '{"word":"オーダー","reading":"オーダー","meaning_vi":"đặt hàng","han_viet":"","tested":true,"question_type":"usage","examples":[{"ja":"レストランで食事の後にデザートをオーダーした。","ja_furigana":"レストランで食事の後にデザートをオーダーした。","vi":"Tôi đã gọi món tráng miệng sau bữa ăn ở nhà hàng.","source":"exam"}]}'),
    ('N3_2025_07', 'VOCABULARY', 10, '{"word":"リスト","reading":"リスト","meaning_vi":"danh sách","han_viet":"","tested":true,"question_type":"context","examples":[{"ja":"来週の旅行に持っていく物のリストを作った。","ja_furigana":"来週の旅行に持っていく物のリストを作った。","vi":"Tôi đã lập danh sách những thứ sẽ mang theo cho chuyến đi tuần sau.","source":"exam"}]}'),
    ('N3_2025_07', 'VOCABULARY', 11, '{"word":"中古","reading":"ちゅうこ","meaning_vi":"đã qua sử dụng","han_viet":"TRUNG CỔ","tested":true,"question_type":"context","examples":[{"ja":"この店では、以前誰かが使っていた中古の車を売っている。","ja_furigana":"この店では、以前誰かが使っていた中古の車を売っている。","vi":"Ở cửa hàng này, họ bán xe cũ từng được ai đó sử dụng trước đây.","source":"exam"}]}'),
    ('N3_2025_07', 'VOCABULARY', 12, '{"word":"列","reading":"れつ","meaning_vi":"hàng; dòng; hàng ngũ; hàng đợi","han_viet":"LIỆT","tested":true,"question_type":"context","examples":[{"ja":"この店はとても人気があり、店の前にはいつも、開店を待つ人の長い列ができている。","ja_furigana":"この店はとても人気があり、店の前にはいつも、開店を待つ人の長い列ができている。","vi":"Cửa hàng này rất được ưa chuộng, và trước cửa hàng lúc nào cũng có một hàng dài người chờ mở cửa.","source":"exam"}]}'),
    ('N3_2025_07', 'VOCABULARY', 13, '{"word":"可能","reading":"かのう","meaning_vi":"có thể","han_viet":"KHẢ NĂNG","tested":true,"question_type":"orthography","examples":[{"ja":"文字の色を変えることは可能でしょうか。","ja_furigana":"文字の色を変えることは可能でしょうか。","vi":"Có thể đổi màu chữ không?","source":"exam"}]}'),
    ('N3_2025_07', 'VOCABULARY', 14, '{"word":"呼吸","reading":"こきゅう","meaning_vi":"hơi thở","han_viet":"HÔ HẤP","tested":true,"question_type":"reading","examples":[{"ja":"ゆっくり呼吸をしてください。","ja_furigana":"ゆっくり呼吸をしてください。","vi":"Hãy thở chậm thôi.","source":"exam"}]}'),
    ('N3_2025_07', 'VOCABULARY', 15, '{"word":"困る","reading":"こまる","meaning_vi":"khó xử","han_viet":"KHỐN","tested":true,"question_type":"reading","examples":[{"ja":"前田さんは困っているようだ。","ja_furigana":"前田さんは困っているようだ。","vi":"Có vẻ anh Maeda đang gặp khó khăn.","source":"exam"}]}'),
    ('N3_2025_07', 'VOCABULARY', 16, '{"word":"地面","reading":"じめん","meaning_vi":"mặt đất","han_viet":"ĐỊA DIỆN","tested":true,"question_type":"reading","examples":[{"ja":"雨で地面がぬれている。","ja_furigana":"雨で地面がぬれている。","vi":"Vì mưa nên mặt đất bị ướt.","source":"exam"}]}'),
    ('N3_2025_07', 'VOCABULARY', 17, '{"word":"坂道","reading":"さかみち","meaning_vi":"đường dốc","han_viet":"PHẢN ĐẠO","tested":true,"question_type":"context","examples":[{"ja":"私の家から駅までは坂道なので、駅まで歩くと疲れます。","ja_furigana":"私の家から駅までは坂道なので、駅まで歩くと疲れます。","vi":"Từ nhà tôi đến ga là đường dốc nên đi bộ đến ga rất mệt.","source":"exam"}]}'),
    ('N3_2025_07', 'VOCABULARY', 18, '{"word":"大変","reading":"たいへん","meaning_vi":"rất","han_viet":"ĐẠI BIẾN","tested":true,"question_type":"paraphrase","examples":[{"ja":"この仕事は大変だ。","ja_furigana":"この仕事は大変だ。","vi":"Công việc này rất khó.","source":"dictionary"}]}'),
    ('N3_2025_07', 'VOCABULARY', 19, '{"word":"完全","reading":"かんぜん","meaning_vi":"hoàn toàn","han_viet":"HOÀN TOÀN","tested":true,"question_type":"reading","examples":[{"ja":"けがは完全に治りました。","ja_furigana":"けがは完全に治りました。","vi":"Vết thương đã lành hẳn rồi.","source":"exam"}]}'),
    ('N3_2025_07', 'VOCABULARY', 20, '{"word":"思い付く","reading":"おもいつく","meaning_vi":"nghĩ ra","han_viet":"","tested":true,"question_type":"context","examples":[{"ja":"この問題を解決するために、何かよい方法を思いついた人はいませんか。","ja_furigana":"この問題を解決するために、何かよい方法を思いついた人はいませんか。","vi":"Để giải quyết vấn đề này, có ai nghĩ ra cách nào hay không?","source":"exam"}]}'),
    ('N3_2025_07', 'VOCABULARY', 21, '{"word":"感動","reading":"かんどう","meaning_vi":"cảm động","han_viet":"CẢM ĐỘNG","tested":true,"question_type":"context","examples":[{"ja":"山の上から見た景色が素晴らしくて、とても感動した。","ja_furigana":"山の上から見た景色が素晴らしくて、とても感動した。","vi":"Phong cảnh nhìn từ trên núi thật tuyệt vời, khiến tôi vô cùng xúc động.","source":"exam"}]}'),
    ('N3_2025_07', 'VOCABULARY', 22, '{"word":"文句","reading":"もんく","meaning_vi":"phàn nàn","han_viet":"VĂN CÚ","tested":true,"question_type":"context","examples":[{"ja":"配達が遅れたせいで、お客さんから文句を言われてしまった。","ja_furigana":"配達が遅れたせいで、お客さんから文句を言われてしまった。","vi":"Vì giao hàng bị chậm nên tôi đã bị khách phàn nàn.","source":"exam"}]}'),
    ('N3_2025_07', 'VOCABULARY', 23, '{"word":"早退","reading":"そうたい","meaning_vi":"về sớm","han_viet":"TẢO THOÁI","tested":true,"question_type":"paraphrase","examples":[{"ja":"昨日、田中さんは早退したそうです。","ja_furigana":"昨日、田中さんは早退したそうです。","vi":"Nghe nói hôm qua anh Tanaka đã về sớm.","source":"exam"}]}'),
    ('N3_2025_07', 'VOCABULARY', 24, '{"word":"森林","reading":"しんりん","meaning_vi":"rừng","han_viet":"SÂM LÂM","tested":true,"question_type":"orthography","examples":[{"ja":"ここから森林が見えます。","ja_furigana":"ここから森林が見えます。","vi":"Từ đây có thể nhìn thấy rừng.","source":"exam"}]}'),
    ('N3_2025_07', 'VOCABULARY', 25, '{"word":"浴びる","reading":"あびる","meaning_vi":"tắm","han_viet":"DỤC","tested":true,"question_type":"orthography","examples":[{"ja":"朝、シャワーを浴びました。","ja_furigana":"朝、シャワーを浴びました。","vi":"Sáng nay tôi đã tắm vòi sen.","source":"exam"}]}'),
    ('N3_2025_07', 'VOCABULARY', 26, '{"word":"涙","reading":"なみだ","meaning_vi":"nước mắt","han_viet":"LỆ","tested":true,"question_type":"reading","examples":[{"ja":"急に涙が出てしまいました。","ja_furigana":"急に涙が出てしまいました。","vi":"Tôi bỗng nhiên bật khóc.","source":"exam"}]}'),
    ('N3_2025_07', 'VOCABULARY', 27, '{"word":"減少","reading":"げんしょう","meaning_vi":"giảm; suy giảm","han_viet":"GIẢM THIỂU","tested":true,"question_type":"usage","examples":[{"ja":"調査によると、この国の人口は今後減少するそうだ。","ja_furigana":"調査によると、この国の人口は今後減少するそうだ。","vi":"Theo điều tra, dân số của nước này trong tương lai sẽ giảm.","source":"exam"}]}'),
    ('N3_2025_07', 'VOCABULARY', 28, '{"word":"煙","reading":"けむり","meaning_vi":"khói","han_viet":"YÊN","tested":true,"question_type":"orthography","examples":[{"ja":"物が燃えるときに、煙が出ます。","ja_furigana":"物が燃えるときに、煙が出ます。","vi":"Khi đồ vật cháy, sẽ có khói bốc ra.","source":"exam"}]}'),
    ('N3_2025_07', 'VOCABULARY', 29, '{"word":"皮","reading":"かわ","meaning_vi":"da","han_viet":"BÌ","tested":true,"question_type":"usage","examples":[{"ja":"じゃがいもは皮をむかないで、そのままゆでます。","ja_furigana":"じゃがいもは皮をむかないで、そのままゆでます。","vi":"Khoai tây không cần gọt vỏ, cứ luộc nguyên như vậy.","source":"exam"}]}'),
    ('N3_2025_07', 'VOCABULARY', 30, '{"word":"移す","reading":"うつす","meaning_vi":"chuyển; dời","han_viet":"DI","tested":true,"question_type":"reading","examples":[{"ja":"お金はあの箱に移したほうがいいですか。","ja_furigana":"お金はあの箱に移したほうがいいですか。","vi":"Có nên chuyển tiền sang cái hộp kia không?","source":"exam"}]}'),
