-- Import JLPT study lists from src/main/resources/jlpt-study (75 exams).
-- Select the existing JLAS database before running this file on MySQL 8.
-- The import adds study lists only for exam codes that already exist.
-- Existing lists are kept on reruns, including lists edited after the import.
-- Vocabulary and grammar are display items. UNMATCHED_GRAMMAR is review data.
-- A backend change is needed to read these tables on the website.

SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;
SET @jlpt_study_saved_sql_mode = @@SESSION.sql_mode;
SET SESSION sql_mode = IF(
    FIND_IN_SET('NO_BACKSLASH_ESCAPES', @jlpt_study_saved_sql_mode) > 0,
    @jlpt_study_saved_sql_mode,
    CONCAT_WS(',', NULLIF(@jlpt_study_saved_sql_mode, ''), 'NO_BACKSLASH_ESCAPES')
);

CREATE TABLE IF NOT EXISTS jlpt_exam_study_list (
    exam_id BIGINT UNSIGNED NOT NULL,
    metadata JSON NOT NULL,
    import_batch_id BINARY(16) NULL,
    PRIMARY KEY (exam_id),
    KEY idx_jlpt_study_list_import_batch (import_batch_id),
    CONSTRAINT fk_jlpt_study_list_exam FOREIGN KEY (exam_id)
        REFERENCES jlpt_exam (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS jlpt_exam_study_item (
    id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    exam_id BIGINT UNSIGNED NOT NULL,
    item_kind ENUM('VOCABULARY','GRAMMAR','UNMATCHED_GRAMMAR') NOT NULL,
    sort_order INT UNSIGNED NOT NULL,
    payload JSON NOT NULL,
    PRIMARY KEY (id),
    UNIQUE KEY uk_jlpt_study_item_order (exam_id, item_kind, sort_order),
    CONSTRAINT fk_jlpt_study_item_list FOREIGN KEY (exam_id)
        REFERENCES jlpt_exam_study_list (exam_id) ON DELETE CASCADE,
    CONSTRAINT chk_jlpt_study_item_order CHECK (sort_order > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TEMPORARY TABLE IF EXISTS tmp_jlpt_study_item;
DROP TEMPORARY TABLE IF EXISTS tmp_jlpt_study_exam;
CREATE TEMPORARY TABLE tmp_jlpt_study_exam (
    exam_code VARCHAR(30) NOT NULL,
    metadata JSON NOT NULL,
    PRIMARY KEY (exam_code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TEMPORARY TABLE tmp_jlpt_study_item (
    exam_code VARCHAR(30) NOT NULL,
    item_kind ENUM('VOCABULARY','GRAMMAR','UNMATCHED_GRAMMAR') NOT NULL,
    sort_order INT UNSIGNED NOT NULL,
    payload JSON NOT NULL,
    PRIMARY KEY (exam_code, item_kind, sort_order)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


