SET @jlpt_study_import_batch = UUID_TO_BIN(UUID());
START TRANSACTION;

SELECT e.id, s.metadata, @jlpt_study_import_batch
FROM tmp_jlpt_study_exam s
JOIN jlpt_exam e ON e.exam_code = s.exam_code COLLATE utf8mb4_unicode_ci
ORDER BY e.id
ON DUPLICATE KEY UPDATE exam_id = jlpt_exam_study_list.exam_id;

SELECT l.exam_id, s.item_kind, s.sort_order, s.payload
FROM tmp_jlpt_study_item s
JOIN jlpt_exam e ON e.exam_code = s.exam_code COLLATE utf8mb4_unicode_ci
JOIN jlpt_exam_study_list l ON l.exam_id = e.id
WHERE l.import_batch_id = @jlpt_study_import_batch
ORDER BY l.exam_id, s.item_kind, s.sort_order;

COMMIT;

SELECT COUNT(*) AS imported_exam_lists
FROM jlpt_exam_study_list
WHERE import_batch_id = @jlpt_study_import_batch;

SELECT i.item_kind, COUNT(*) AS imported_items
FROM jlpt_exam_study_item i
JOIN jlpt_exam_study_list l ON l.exam_id = i.exam_id
WHERE l.import_batch_id = @jlpt_study_import_batch
GROUP BY i.item_kind;

SELECT s.exam_code AS missing_exam_in_database
FROM tmp_jlpt_study_exam s
LEFT JOIN jlpt_exam e ON e.exam_code = s.exam_code COLLATE utf8mb4_unicode_ci
WHERE e.id IS NULL
ORDER BY s.exam_code;

DROP TEMPORARY TABLE tmp_jlpt_study_item;
DROP TEMPORARY TABLE tmp_jlpt_study_exam;
SET SESSION sql_mode = @jlpt_study_saved_sql_mode;
